E["npc:advisor-duskingdawn"] = {t="npc",n="Advisor Duskingdawn",z="undercity",s="Advisor Duskingdawn is a blood elf advisor stationed at Tarren Mill in the Hillsbrad Foothills. She serves as a point of contact for travelers arriving in the settlement on official Horde business.",h="Advisor Duskingdawn is a blood elf advisor stationed at Tarren Mill in the Hillsbrad Foothills.",sec={{t="A Diplomatic Presence",b="Standing watch in Tarren Mill, Advisor Duskingdawn is among the few blood elves operating within Lordaeron alongside the Horde. The hamlet serves as a fortified forward base against the Alliance in Southshore and the Syndicate lingering in the hills, making regional coordination essential. Duskingdawn receives dispatch reports and ensures new arrivals assist with local operations.",sp=0}},faq={{q="Who is Advisor Duskingdawn?",a="Advisor Duskingdawn is a blood elf advisor stationed in Tarren Mill within the Hillsbrad Foothills, acting as an administrative presence for Horde affairs in the region.",al={"who is duskingdawn","duskingdawn lore","advisor duskingdawn identity"}},{q="Where can she be found?",a="She is located inside the settlement of Tarren Mill in northern Hillsbrad Foothills, coordinating regional tasks alongside Forsaken and orcish authorities.",al={"duskingdawn location","where is advisor duskingdawn","duskingdawn map"}},{q="Why is a blood elf in Tarren Mill?",a="Duskingdawn represents diplomatic and advisory interests within Lordaeron, helping direct resources and personnel who arrive to stabilize Tarren Mill against local threats.",al={"why is blood elf in hillsbrad","duskingdawn purpose"}}},ang={["faction:Horde"]="For Horde couriers and fighters, reporting to Advisor Duskingdawn is an early step in coordinating the defense of Tarren Mill against regional hostilities."},kw={"advisor duskingdawn","blood elf","duskingdawn","hillsbrad foothills","horde advisor","tarren mill"},rel={"subzone:tarren-mill","zone:hillsbrad","quest:9425","topic:horde"},src={"Advisor Duskingdawn"}}
E["npc:ambassador-sunsorrow"] = {t="npc",n="Ambassador Sunsorrow",z="undercity",s="Ambassador Sunsorrow serves as the blood elf diplomatic envoy stationed beside Lady Sylvanas Windrunner in the Royal Quarter of the Undercity. Surrounded by the restless dead, he represents the interests of Quel'Thalas and helps coordinate communication and supplies between the Forsaken and his people.",h="Ambassador Sunsorrow serves as the blood elf diplomatic envoy stationed beside Lady Sylvanas Windrunner in...",sec={{t="Diplomat in the Shadow of the Throne",b="Standing beside Lady Sylvanas Windrunner in the shadowed depths of the Royal Quarter, Ambassador Sunsorrow acts as an official diplomatic link between the blood elves and the Forsaken. Even in the gloom of the Undercity, Sunsorrow maintains courtly composure, keeping a watchful eye over visitors and directing messengers southward to Forsaken bastions like the Sepulcher in Silverpine Forest and Tarren Mill in the Hillsbrad Foothills. He shares an unspoken understanding of tragic loss with the Banshee Queen, whose former life as Ranger-General of Silvermoon remains a deeply resonant memory to the people of Quel'Thalas.",sp=0}},faq={{q="Who is Ambassador Sunsorrow?",a="He is an envoy from the blood elves of Quel'Thalas, stationed directly in the Undercity's Royal Quarter beside Lady Sylvanas Windrunner to oversee diplomatic ties and logistics between their peoples.",al={"sunsorrow who","who is sunsorrow","blood elf in undercity"}},{q="Why is a blood elf standing beside Sylvanas Windrunner?",a="Before her death and rebirth as the Banshee Queen, Lady Sylvanas was the Ranger-General of Silvermoon and died defending Quel'Thalas. The surviving blood elves maintain active diplomatic ties with her Forsaken kingdom, with Sunsorrow representing their interests.",al={"why elf in undercity","blood elf sylvanas court","sunsorrow purpose"}},{q="What tasks does Ambassador Sunsorrow give to travelers?",a="He assists in coordinating field communications and vital supplies, dispatching adventurers with orders and deliveries to key Forsaken strongholds such as the Sepulcher in Silverpine and Tarren Mill in Hillsbrad.",al={"sunsorrow quests","what does sunsorrow do","delivery to the sepulcher"}},{q="How does he react to visitors in the Royal Quarter?",a="Sunsorrow maintains strict courtly etiquette. He expects proper decorum before the Banshee Queen and keeps a close eye on anyone granted an audience in the royal chamber.",al={"sunsorrow dialogue","speaking to sunsorrow"}}},ang={["race:Undead"]="For the Forsaken, Sunsorrow is a visible reminder of their Queen's noble heritage and a rare living ally welcome at the foot of her throne.",["faction:Horde"]="Sunsorrow provides vital logistical dispatches for Horde travelers, routing hands and supplies through the Forsaken holdings of Silverpine Forest and Hillsbrad."},kw={"ambassador sunsorrow","blood elf","diplomat","envoy","royal quarter","sunsorrow","sylvanas windrunner","undercity"},rel={"npc:sylvanas-windrunner","subzone:royal-quarter","zone:undercity","topic:forsaken","topic:horde","subzone:sepulcher","subzone:tarren-mill","quest:9189"},src={"Ambassador Sunsorrow"}}
E["npc:anastasia-hartwell"] = {t="npc",n="Anastasia Hartwell",z="undercity",s="Anastasia Hartwell is a prominent Forsaken mage trainer residing in the Magic Quarter of the Undercity. She guides fledgling and developing spellcasters in mastering the arcane arts and oversees vital magical research and field missions across Lordaeron and beyond.",h="Anastasia Hartwell is a prominent Forsaken mage trainer residing in the Magic Quarter of the Undercity.",sec={{t="Arcane Mastery in the Ruins",b="Standing within the dark, echoing chambers of the Undercity's Magic Quarter, Anastasia Hartwell instructs Forsaken and Horde mages in channeling arcane energies. Though the kingdom of Lordaeron fell to ruin, former human practitioners like Anastasia have preserved their scholarly traditions in undeath. She maintains that magic demands strict discipline, warning any traveler she meets that careless incantations will quickly consume the untrained.",sp=0},{t="Field Research and Relics",b="Beyond fundamental spell instruction, Anastasia directs promising students toward vital field investigations. She dispatches mages into Tirisfal Glades, including the blighted grounds of the Balnir Farmstead and ruined alchemist workshops, to recover lost reagents and salvage remnants of forgotten arcane lore. Through her tasks, practitioners learn that securing magical dominance requires braving the hazardous ruins of their former homeland.",sp=0},{t="Allies of the Craft",b="Anastasia's connections reach well beyond the borders of Tirisfal. As Horde spellcasters grow in proficiency, she coordinates with fellow trainers in distant lands, such as Deino in Orgrimmar, and directs advanced students toward solitary masters like Tabetha in the swamplands of Dustwallow Marsh. Her guidance ensures that Forsaken mages remain woven into the wider tapestry of the Horde's magical pursuits.",sp=0}},faq={{q="Who is Anastasia Hartwell?",a="Anastasia Hartwell is a Forsaken mage trainer located in the Magic Quarter of the Undercity. She teaches spells to developing mages and provides specialized assignments to retrieve arcane artifacts and reagents across Lordaeron.",al={"anastasia hartwell","who is anastasia","hartwell undercity"}},{q="Where can I find Anastasia Hartwell?",a="She is located in the Magic Quarter of the Undercity, gathered among other arcane practitioners and trainers under the city's vaulted subterranean ceilings.",al={"anastasia hartwell location","where is anastasia hartwell","undercity mage trainer location"}},{q="What does Anastasia say to non-mages?",a="She offers cautious advice to non-mage visitors, warning them to be wary of magic as they journey across the world, noting that it readily burns the untrained.",al={"anastasia gossip","anastasia dialogue","hartwell advice"}},{q="What quests does Anastasia Hartwell offer?",a="Anastasia offers various training assignments for mages, including investigating the Balnir Farmstead, exploring ruined alchemist shops for supplies, and liaising with distant teachers such as Deino in Orgrimmar and Tabetha in Dustwallow Marsh.",al={"anastasia quests","hartwell tasks","undercity mage quests"}},{q="Is Anastasia Hartwell related to other Hartwells in Tirisfal?",a="She shares a surname with other Forsaken in Tirisfal Glades, such as Andrew Hartwell and Geoffrey Hartwell, pointing to common familial roots in pre-plague Lordaeron.",al={"hartwell family","andrew hartwell","geoffrey hartwell"}},{q="Why does Anastasia send mages to the Balnir Farmstead?",a="She directs mages to the Balnir Farmstead in Tirisfal Glades to recover specific items and conduct research into arcane remnants preserved in the blighted countryside.",al={"balnir farmstead quest","why balnir farmstead","hartwell balnir"}}},ang={["class:Mage"]="Anastasia Hartwell is an essential mentor for Horde mages passing through the Undercity, training higher spell ranks and commissioning vital class quests.",["race:Undead"]="She represents the continuation of Dalaran and Lordaeron's esteemed arcane traditions among the Forsaken, preserved even through the tragedy of undeath.",["faction:Horde"]="Through partnerships with trainers like Deino in Orgrimmar, Anastasia bridges Lordaeron's arcane heritage with the broader magical endeavors of the Horde."},kw={"anastasia","balnir","deino","forsaken","hartwell","lordaeron","mage","magic quarter","tabetha","trainer","undercity"},rel={"subzone:magic-quarter","zone:undercity","topic:forsaken","quest:1882","quest:1960","quest:1943","npc:deino","npc:tabetha"},src={"Anastasia Hartwell"}}
E["npc:andron-gant"] = {t="npc",n="Andron Gant",z="undercity",s="Andron Gant is a reclusive, frequently intoxicated Forsaken residing in the murky depths of the Apothecarium in the Undercity, handling occasional research commissions and relic recoveries for local scholars.",h="Andron Gant is a reclusive, frequently intoxicated Forsaken residing in the murky depths of the Apothecarium...",sec={{t="A Slurring Informant",b="Lounging amidst the noxious fumes of the Apothecarium, Andron Gant rarely ventures beyond the safety of the Undercity's stone walls. To the casual observer, he appears to be little more than a drunken scholar, occasionally hiring adventurous couriers to retrieve obscure relics like the Tablet of Beth'Amara or the Tablet of Markri from distant shores on behalf of local mages. However, beneath his liquor-soaked demeanor lies a clandestine operative. Gant secretly serves as an informant for the Syndicate, funneling sensitive intelligence out of the Forsaken capital in exchange for coin and illicit favors.",sp=0},{t="Unmasked by the Deathstalkers",b="Gant's treacherous dealings did not escape the notice of Undercity's intelligence network. When the Syndicate dispatched a courier named Astor Hadren to collect a ledger of compromised data, aspiring operatives within the Deathstalkers intercepted the runner. Disguised as Hadren, an agent was able to trick the drunken Gant into parting with his incriminating ledger without raising an eyebrow, handing Lord Varimathras definitive proof of Gant's treason against the Forsaken.",sp=1}},faq={{q="Where can I find Andron Gant?",a="Andron Gant is located inside the Undercity, lingering in the lower levels of the Apothecarium district.",al={"andron gant location","where is andron gant","gant undercity location"}},{q="Why is Andron Gant interested in Azshara tablets?",a="Gant acts as an intermediary for certain Undercity mages, arranging payments to scavengers and contacts like Jediga to recover ancient relics from the ruins of Azshara.",al={"andron gant azshara","tablet of markri andron gant","why does gant want tablets"}},{q="What is Andron Gant's connection to the Syndicate?",a="Despite living within the heart of the Forsaken capital, Gant secretly acts as an informant for the Syndicate, collecting intelligence into ledgers to smuggle to human outlaws.",al={"gant syndicate","is andron gant a traitor","who does andron gant work for"},sp=1},{q="Who exposed Andron Gant's treachery?",a="The Deathstalkers, the assassin and espionage order answering to Lord Varimathras, intercepted Gant's Syndicate courier and tricked him into handing over his spy ledger.",al={"who caught andron gant","deathstalkers andron gant","varimathras andron gant"},sp=1}},ang={["class:Rogue"]="Forsaken rogues climbing the ranks of the Deathstalkers learn firsthand through Gant how drunkenness and complacency can unravel even the tightest espionage operations.",["race:Undead"]="Gant serves as a stark reminder that loyalty among the Forsaken is never guaranteed, and human criminal factions like the Syndicate have eyes even within Lordaeron's catacombs."},kw={"andron gant","apothecarium","astor hadren","deathstalkers","jediga","tablet of markri","varimathras"},rel={"npc:varimathras","subzone:apothecarium","topic:syndicate","topic:forsaken","zone:undercity","zone:azshara"},src={"Andron Gant"}}
E["npc:austil-de-mon"] = {t="npc",n="Austil de Mon",z="undercity",s="Austil de Mon is a Forsaken warrior trainer stationed in Brill within Tirisfal Glades. Based out of the Gallows' End Tavern, he instructs newly risen warriors looking to hone their martial prowess in service of the Dark Lady.",h="Austil de Mon is a Forsaken warrior trainer stationed in Brill within Tirisfal Glades.",sec={{t="A Veteran in Gallows' End",b="Found inside the Gallows' End Tavern in Brill, Austil de Mon serves as one of the earliest instructors for Forsaken warriors venturing out of Deathknell. While the living once populated the inn to drink and rest, Austil now uses the gloomy refuge to teach newly liberated undead how to channel raw martial discipline and ruthless combat techniques against the kingdom's surrounding foes.",sp=0}},faq={{q="Who is Austil de Mon?",a="Austil de Mon is an undead warrior trainer located on the grounds of Brill in Tirisfal Glades, offering training to Forsaken fighters.",al={"austil de mon","austil","who is austil"}},{q="Where can I find Austil de Mon?",a="You can find him stationed in the Gallows' End Tavern in Brill, Tirisfal Glades, just north of the Undercity.",al={"austil de mon location","where is austil","austil de mon map"}},{q="What role does he play in Brill?",a="He instructs novice warriors in fighting techniques, stances, and martial abilities to help strengthen the Forsaken military against local threats.",al={"what does austil do","austil trainer","austil role"}}},ang={["class:Warrior"]="For Forsaken warriors leaving Deathknell, Austil de Mon is one of the primary mentors providing guidance and formal ability training in Tirisfal Glades.",["race:Undead"]="Austil helps steel newly risen undead into formidable frontline combatants prepared to defend Lordaeron against the Scourge and the Scarlet Crusade."},kw={"austil de mon","brill","forsaken warrior","gallows' end tavern","tirisfal glades","warrior trainer"},rel={"subzone:brill","subzone:gallows-end-tavern","zone:tirisfal","topic:forsaken","quest:1818"},src={"Austil de Mon"}}
E["npc:bethor-iceshard"] = {t="npc",n="Bethor Iceshard",z="undercity",s="Bethor Iceshard is a powerful Forsaken mage based in the Magic Quarter of the Undercity. Presiding over the arcane and shadow practitioners within the Temple of the Damned, he commands considerable authority in Sylvanas's realm. Beneath his chilly demeanor lies a past entwined with old friends torn apart by the Scourge.",h="Bethor Iceshard is a powerful Forsaken mage based in the Magic Quarter of the Undercity.",sec={{t="Master of the Magic Quarter",b="Standing within the Temple of the Damned, Bethor Iceshard oversees the practitioners of the arcane arts and shadow magic in the Undercity. Respected and feared for his intellect and icy resolve, Bethor wields sufficient political and magical weight to give direct instructions to provincial magistrates across Lordaeron. He directs agents of the Forsaken to secure valuable grimoires, investigate arcane anomalies, and stamp out rival powers that threaten the Undercity's dominion.",sp=0},{t="Bonds of Apprenticehood",b="Before the Third War devastated Lordaeron, Bethor was a mortal apprentice studying magic alongside two close companions: Gunther Arcanus and Thule Ravenclaw. As a testament to their fellowship, the three students wove their practice wands together. The Scourge shattered that bond entirely. When death and dark magic swept across the kingdom, Thule Ravenclaw willfully surrendered his soul to the Lich King, Gunther perished and rose on an isolated island in Brightwater Lake, and Bethor succumbed only to later break free as Forsaken.",sp=0},{t="Old Friends and Bittersweet Reunions",b="Bethor has not forgotten his former companions. Tracking down powerful undead spellcasters throughout Tirisfal and Silverpine, he dispatches agents to discern whether rogue practitioners serve the Lich King or might be turned toward the Forsaken cause. When Bethor identifies Gunther Arcanus raising the dead on Brightwater Lake, he works patiently to bring his old friend into Lady Sylvanas's fold, while offering no mercy to Thule Ravenclaw, whose willing betrayal doomed their past brotherhood.",sp=1}},faq={{q="Who is Bethor Iceshard?",a="Bethor Iceshard is a high-ranking Forsaken mage who presides over the Temple of the Damned in the Undercity's Magic Quarter. He coordinates magical research, rogue intelligence, and covert arcane operations on behalf of the Dark Lady.",al={"bethor iceshard","who is bethor","bethor lore"}},{q="Where can Bethor Iceshard be found?",a="Bethor resides inside the Temple of the Damned, the central structure situated in the Magic Quarter of the Undercity.",al={"where is bethor","bethor location","find bethor iceshard"}},{q="What is Bethor's history with Gunther Arcanus?",a="Bethor and Gunther were close friends during their days as apprentice mages in Lordaeron. After dying during the Scourge invasion, both eventually broke free from the Lich King's control, and Bethor orchestrated Gunther's recruitment into the Forsaken.",al={"gunther and bethor","gunther arcanus friendship","how does bethor know gunther"},sp=1},{q="Who was Thule Ravenclaw to Bethor?",a="Thule Ravenclaw was the third member of Bethor and Gunther's apprentice circle. Unlike the other two, Thule willingly pledged his soul to the Lich King during the Scourge invasion, becoming a hated necromancer residing at Fenris Isle.",al={"thule ravenclaw connection","thule and bethor","bethor ravenclaw"}},{q="What is the story behind Bethor's wand?",a="In their youth, Bethor, Gunther, and Thule wove their practice wands together as a symbol of their eternal friendship. That braided keepsake remains a poignant artifact tying the three fractured spellcasters to their mortal past.",al={"woven wand","wand to bethor","bethor apprentice wand"}},{q="What role does Bethor play in Forsaken society?",a="Bethor serves as one of the leading arcane authorities in the Undercity. He guides newly risen magi and warlocks, directs military intelligence regarding rogue necromancers, and holds authority over regional Forsaken civil officials such as magistrate Sevren.",al={"bethor role","what does bethor do","bethor authority"}}},ang={["class:Mage"]="For Forsaken mages, Bethor represents the pinnacle of perseverance, demonstrating that the arcane arts can thrive even within the cold grasp of undeath.",["race:Undead"]="Bethor's personal tragedy mirrors that of many Forsaken: severed from cherished friendships and homes by the Scourge, only to face former allies as bitter enemies.",["faction:Horde"]="Bethor coordinates crucial offensive magic and counter-necromancy operations that protect the Horde's foothold across Lordaeron."},kw={"bethor iceshard","forsaken","gunther arcanus","magic quarter","prodigal lich","temple of the damned","thule ravenclaw","undercity"},rel={"npc:gunther-arcanus","subzone:magic-quarter","zone:undercity","quest:405","quest:411","quest:446","quest:491","topic:forsaken"},src={"Bethor Iceshard"}}
E["npc:cain-firesong"] = {t="npc",n="Cain Firesong",z="undercity",s="Cain Firesong is a Forsaken mage trainer located in the settlement of Brill within Tirisfal Glades. He assists fledgling practitioners of the arcane as they grow in power, guiding them before directing them onward to deeper studies in the Undercity. When not instructing initiates, he pursues his own unsavory experiments in Brill's laboratory.",h="Cain Firesong is a Forsaken mage trainer located in the settlement of Brill within Tirisfal Glades.",sec={{t="A Practitioner in Brill",b="While many Forsaken spellcasters delve into shadow or necromancy, Cain Firesong maintains mastery over traditional arcane disciplines. Stationed in Brill, he serves as an early mentor to Forsaken mages venturing forth from Deathknell. According to local Deathguards, Cain arrived too late to secure lodgings at the Gallows' End Tavern and instead took up residence around Brill's laboratory. There, amidst brewing concoctions and alchemical apparatuses, he quietly pursues esoteric research between lessons.",sp=0},{t="Guiding New Talent",b="As novice mages under his tutelage advance beyond their preliminary studies in Tirisfal Glades, Cain ensures they do not stagnate. Recognizing the limits of what a roadside laboratory can offer, he directs his most capable students to seek out Anastasia Hartwell, a master sorceress residing in the Magic Quarter of the Undercity.",sp=0}},faq={{q="Who is Cain Firesong?",a="Cain Firesong is a Forsaken mage trainer stationed in Brill in Tirisfal Glades. He teaches arcane spells to fledgling Horde spellcasters and directs advanced students toward the Undercity.",al={"who is cain firesong","cain firesong lore","cain firesong brill"}},{q="Where does Cain Firesong stay in Brill?",a="According to the local Deathguards, Cain arrived too late to claim a room at the Gallows' End Tavern. Instead, he made a home around Brill's laboratory, where he works on arcane and unsavory projects.",al={"where is cain firesong","cain firesong location","cain tavern room"}},{q="Where does Cain send mages after their initial training?",a="Once a mage has advanced sufficiently under his guidance, Cain directs them to travel down into the Undercity's Magic Quarter to continue their instruction under Anastasia Hartwell.",al={"cain firesong quest","who does cain send mages to","speak with anastasia"}}},ang={["class:Mage"]="For young Forsaken mages stepping out from Deathknell, Cain Firesong is your primary mentor in Tirisfal Glades before you are summoned to the Undercity.",["race:Undead"]="Cain proves that even in undeath, the arcane traditions of former human magi remain a potent weapon for the Forsaken."},kw={"anastasia hartwell","arcane","brill","cain firesong","gallows' end tavern","mage trainer","tirisfal glades"},rel={"subzone:brill","zone:tirisfal","quest:1881","quest:1959","subzone:gallows-end-tavern","topic:forsaken"},src={"Cain Firesong"}}
E["npc:carendin-halgar"] = {t="npc",n="Carendin Halgar",z="undercity",s="Carendin Halgar is a prominent Forsaken warlock trainer residing in the Magic Quarter of the Undercity. Sharp-tongued and notoriously short on patience, he oversees the training of fledgling practitioners of the dark arts. He instructs aspiring warlocks on how to subjugate powerful demonic entities from the Twisting Nether, notably teaching the rituals to bind Voidwalkers and Succubi.",h="Carendin Halgar is a prominent Forsaken warlock trainer residing in the Magic Quarter of the Undercity.",sec={{t="Master of the Dark Arts",b="Within the noxious gloom of the Undercity's Magic Quarter, Carendin Halgar instructs those who delve into the Twisting Nether. He demands focus and obedience, holding little tolerance for failure, hesitation, or weakness. Under his watchful gaze, warlocks are pushed beyond basic incantations into the dangerous mastery of summonings and soul manipulation, cementing the Forsaken's ruthless approach to demonic servitude.",sp=0},{t="Subjugating the Nether",b="Carendin's core tutelage revolves around binding ever more dangerous demons to the summoner's will. He sends his students across Lordaeron and beyond to retrieve ancient runes, runic stones, and the distilled pure essence of mortals to complete treacherous summoning circles. Whether commanding a shadowy creature of the void or luring a temptress succubus into subjugation, Carendin ensures the warlock dominates the demon before it can devour its master.",sp=1}},faq={{q="Where can Carendin Halgar be found?",a="Carendin Halgar is located in the Magic Quarter of the Undercity, gathered among the other practitioners of fel and shadow magic.",al={"carendin halgar location","undercity warlock trainer location","where is halgar"}},{q="What role does Carendin Halgar play for warlocks?",a="He serves as a mentor and questgiver for Horde warlocks, instructing them in the rituals required to summon and permanently bind major demons, such as the Voidwalker and the Succubus.",al={"what does carendin do","halgar purpose","carendin quests"}},{q="What is Carendin Halgar's personality like?",a="He is notoriously blunt, demanding, and utterly devoid of patience. He expects prompt results from his pupils and despises wasting time or dealing with excuses.",al={"halgar temperament","is carendin nice","carendin halgar lore"}},{q="Why does Carendin require pure hearts for summoning rituals?",a="In his lessons on summoning a succubus, Halgar tasks acolytes with procuring the untainted hearts of the pure, using their innocence and essence as bait to entice and ensnare the fiendish demon in a binding circle.",al={"hearts of the pure purpose","succubus summoning carendin","why hearts of the pure"}},{q="Does Carendin Halgar interact with warlocks outside the Undercity?",a="Yes, Carendin maintains contact with other senior warlocks across the Horde, including Gan'rul Bloodeye in Orgrimmar, coordinating efforts to advance the dark arts across Kalimdor and the Eastern Kingdoms.",al={"carendin connections","halgar orgrimmar","gan'rul bloodeye carendin"}},{q="Who does Carendin send advanced warlocks to see?",a="Once an acolyte demonstrates sufficient mastery over basic demons, Carendin directs them outward to seek further esoteric instruction, such as sending them to find the eccentric summoner Strahad Farsan in the Barrens.",al={"seeking strahad","who does carendin send you to","halgar next mentor"}}},ang={["class:Warlock"]="Carendin Halgar is a crucial mentor in Lordaeron, guiding warlocks through the grueling trials required to dominate and bind both Voidwalkers and Succubi.",["race:Undead"]="Reflecting the uncompromising spirit of the Forsaken, Carendin shows no pity or hesitation, viewing demonic entities strictly as tools to be broken and exploited.",["faction:Horde"]="Carendin serves as the primary eastern conduit for Horde warlocks, coordinating training with fellow dark practitioners across the sea in Kalimdor."},kw={"carendin halgar","creature of the void","forsaken","halgar","magic quarter","succubus","the binding","trainer","undercity","voidwalker","warlock"},rel={"subzone:magic-quarter","zone:undercity","quest:1473","quest:1471","quest:1476","quest:1472","quest:1798","npc:gan-rul-bloodeye"},src={"Carendin Halgar"}}
E["npc:elder-darkcore"] = {t="npc",n="Elder Darkcore",z="undercity",s="Elder Darkcore is an ancient spirit who appears during the Lunar Festival within the throne room of the Ruins of Lordaeron above the Undercity. Representing the honored ancestors of the world, he offers his blessing and festive tokens to travelers who seek him out. His presence marks a peaceful, reflective moment amidst the ruins of a fallen human kingdom.",h="Elder Darkcore is an ancient spirit who appears during the Lunar Festival within the throne room of the Ruins...",sec={{t="A Spirit in the Throne Room",b="During the annual Lunar Festival, the spirits of ancient elders manifest across Azeroth to share their wisdom with adventurers. Elder Darkcore takes his vigil in one of the world's most somber locations: the royal throne room in the Ruins of Lordaeron, directly above the entrance to the Undercity. Surrounded by the blood-stained floor where King Terenas Menethil II fell, this spectral ancestor offers a Coin of Ancestry and his blessing to those brave enough to enter the heart of Forsaken territory to pay their respects.",sp=0}},faq={{q="Who is Elder Darkcore?",a="Elder Darkcore is one of the honored spectral ancestors who manifests during the seasonal Lunar Festival. He appears in the throne room above the Undercity to bestow blessings and Coins of Ancestry on visitors.",al={"elder darkcore","darkcore","who is darkcore"}},{q="Where can I find Elder Darkcore?",a="He is located in the ruined throne room of Capital City, in the Ruins of Lordaeron right above the entrance descent leading down into the Undercity.",al={"where is darkcore","darkcore location","undercity elder"}},{q="Is Elder Darkcore hostile to the Alliance?",a="Elder Darkcore himself is neutral and welcomes all travelers who come to honor him. However, because he stands within the Forsaken stronghold of the Ruins of Lordaeron, Alliance adventurers must carefully evade the hostile guards patrolling nearby.",al={"can alliance talk to darkcore","is darkcore horde","undercity lunar festival alliance"}},{q="What does honoring Elder Darkcore give you?",a="Paying respects to him completes the festival quest to honor his memory, rewarding a Coin of Ancestry and a lucky red packet containing festive treats.",al={"darkcore reward","darkcore quest"}}},ang={["faction:Alliance"]="Visiting Elder Darkcore requires slipping past high-level Forsaken sentries and royal guards stationed around Capital City's ruins, making him one of the festival's most perilous stops for the Alliance.",["race:Undead"]="Elder Darkcore lingers mere steps from the surface elevators of the Undercity, standing upon the very stones where the kingdom of Lordaeron was torn down."},kw={"ancestor","coin of ancestry","darkcore","elder darkcore","lunar festival","ruins of lordaeron","throne room","undercity"},rel={"quest:8648","zone:undercity","zone:ruinsoflordaeron","topic:lordaeron"},src={"Elder Darkcore"}}
E["npc:godrick-farsan"] = {t="npc",n="Godrick Farsan",z="undercity",s="Godrick Farsan is an undead warlock assistant located in the Undercity, serving alongside Carendin Halgar in the Magic Quarter. Despite being entirely blind, he possesses mystical senses that allow him to perceive the dark energies and souls around him.",h="Godrick Farsan is an undead warlock assistant located in the Undercity, serving alongside Carendin Halgar in...",sec={{t="Eyes in the Dark",b="Situated amidst the summoning circles of the Magic Quarter, Godrick Farsan aids Master Carendin Halgar in guiding aspiring Forsaken warlocks. Though he lacks physical sight, Godrick claims to see through unconventional, demonic means, perceiving the world through shadows and residual soul energies. He tests practitioners seeking to bind greater demonic entities, dispatching them to gather pure hearts and essences needed for intricate summoning rituals.",sp=0}},faq={{q="Who is Godrick Farsan?",a="Godrick Farsan is a Forsaken warlock stationed in the Magic Quarter of the Undercity. He serves as an assistant to Master Carendin Halgar, aiding in the instruction and rituals of fledgling warlocks.",al={"godrick farsan","who is godrick"}},{q="How can Godrick see if he is blind?",a="While Godrick has lost his mortal eyesight, he perceives his surroundings through magical senses. He taps into the flow of fel power and the spiritual resonance of souls to navigate and observe the world around him.",al={"is godrick blind","how does godrick see"}},{q="Is Godrick related to Strahad Farsan?",a="Sharing the same surname and affinity for demonology, Godrick is believed to be kin to Strahad Farsan, the warlock master residing above Ratchet in the Barrens.",al={"strahad farsan relation","strahad farsan brother","are godrick and strahad related"}},{q="What role does he play in warlock training?",a="Godrick helps oversee the binding rites for warlocks, specifically guiding them through tasks such as acquiring pure hearts to lure and bind a succubus.",al={"godrick warlock quests","hearts of the pure quest"}}},ang={["class:Warlock"]="Forsaken warlocks looking to master the art of summoning a succubus must consult Godrick to prepare the necessary lures and understand the devouring nature of demonic servants.",["race:Undead"]="Godrick exemplifies the Forsaken warlock philosophy, embracing physical ruin and blindness while honing dark magical awareness to replace mortal frailties."},kw={"carendin halgar","godrick farsan","hearts of the pure","strahad farsan","succubus","undercity","warlock"},rel={"npc:carendin-halgar","quest:1476","quest:1472","npc:strahad-farsan","zone:undercity","topic:forsaken"},src={"Godrick Farsan"}}
E["npc:gordon-wendham"] = {t="npc",n="Gordon Wendham",z="undercity",s="Gordon Wendham is a Forsaken weaponsmith and merchant operating out of the bustling Trade Quarter in the Undercity. He equips newly arrived champions and local defenders of the Dark Lady with reliable steel, blades, and bludgeons. Beyond hawking basic armaments, he frequently serves as a local point of contact for couriers arriving from the surface.",h="Gordon Wendham is a Forsaken weaponsmith and merchant operating out of the bustling Trade Quarter in the...",sec={{t="Armaments of the Trade Quarter",b="Situated amidst the damp stonework and chemical canals of the Undercity's Trade Quarter, Gordon Wendham provides essential weaponry to those taking up arms for the Forsaken. From basic daggers and hand axes to sturdy broadswords and maces, his stock caters to fledgling fighters who need dependable iron before venturing out into the contested reaches of Lordaeron.",sp=0},{t="A Courier's Destination",b="Beyond his merchant trade, Wendham is integrated into the capital's busy logistics network. Travelers sent on errands from flight masters and couriers—such as those connecting from the bat handlers atop the ruins—are often directed straight to his stall. His central location in the Trade Quarter makes him an accessible and recognizable fixture for coordinating basic supplies and dispatches throughout the underground city.",sp=0}},faq={{q="Who is Gordon Wendham?",a="Gordon Wendham is an undead merchant stationed in the Trade Quarter of the Undercity. He sells standard martial weapons and serves as a contact for couriers arriving in the capital.",al={"gordon wendham lore","who is wendham","undercity gordon"}},{q="Where is Gordon Wendham located?",a="You can find him tending his weapon stall in the Trade Quarter, the commercial ring situated within the subterranean halls of the Undercity.",al={"gordon wendham location","where is gordon undercity","trade quarter weapon vendor"}},{q="What does he sell?",a="He offers a wide array of basic, standard-grade weapons, including swords, daggers, maces, staves, axes, and various thrown armaments suited for leveling adventurers.",al={"wendham wares","what does gordon sell","gordon wendham weapons"}},{q="What quests involve him?",a="He is tied into introductory delivery runs connecting the surface bat roosts to the undercity interior, including deliveries between himself and bat handler Michael Garrett.",al={"gordon wendham quests","ride to the undercity","michael garrett quest"}}},ang={["race:Undead"]="For newly liberated Forsaken leaving Deathknell, merchants like Gordon Wendham in the Trade Quarter represent the practical backbone of their nascent nation's war effort.",["class:Warrior"]="Gordon offers dependable basic blades and blunt instruments for frontline fighters looking to practice their weapon proficiencies in the capital."},kw={"forsaken","gordon wendham","michael garrett","trade quarter","undercity","weapon vendor"},rel={"subzone:trade-quarter","zone:undercity","quest:6323","quest:6322","topic:forsaken","zone:ruinsoflordaeron","topic:lordaeron"},src={"Gordon Wendham"}}
E["npc:innkeeper-norman"] = {t="npc",n="Innkeeper Norman",z="undercity",s="Innkeeper Norman tends the hearth at the primary tavern in the Trade Quarter of the Undercity. A quiet, diligent Forsaken, he offers travelers of the Horde respite, hearthstone bindings, and food suited to the varied tastes of both the living and the dead.",h="Innkeeper Norman tends the hearth at the primary tavern in the Trade Quarter of the Undercity.",sec={{t="Hospitality in the Sewers",b="Located in the bustling Trade Quarter beneath the ruined Capital City of Lordaeron, Innkeeper Norman provides lodging for emissaries, mercenaries, and adventurers passing through the Forsaken stronghold. Despite the damp chill and alchemical stenches of the Undercity, Norman's tavern remains a bustling hub for travelers looking to anchor their hearthstones, share news from across Azeroth, or prepare for expeditions into the Plaguelands.",sp=0},{t="Festive Eccentricities",b="While Norman typically keeps to his duties selling provisions and managing rooms, the seasonal arrival of Hallow's End reveals a more peculiar side. During the holiday, Norman participates in the seasonal revelry, demanding peculiar displays—such as clucking like a chicken—from adventurous patrons eager to earn holiday treats like Undercity mints.",sp=0}},faq={{q="Where can I find Innkeeper Norman?",a="Innkeeper Norman is found inside the main tavern in the Trade Quarter of the Undercity, situated along the southern curve of the inner ring.",al={"norman location","undercity innkeeper location","where is norman"}},{q="What services does Innkeeper Norman provide?",a="He serves as a primary innkeeper for the Undercity. Players can bind their hearthstones to his tavern, purchase food and drink suited for both the living and the undead, or log out safely to earn rest.",al={"norman services","undercity hearthstone"}},{q="Why does Norman ask patrons to cluck like a chicken?",a="During the Hallow's End festival, Norman participates in traditional holiday trickery. Adventurers seeking special holiday mints must swallow their pride and cluck like a chicken to earn his favor.",al={"chicken clucking mints","norman chicken quest"}},{q="Is Norman related to Innkeeper Bates?",a="While they do not mention each other directly in life or undeath, their names are a grim nod by the Forsaken to the notorious Norman Bates, fitting the dark and macabre nature of Lordaeron's new masters.",al={"norman bates connection","innkeeper bates norman"}}},ang={["faction:Horde"]="For living Horde allies visiting the Undercity, Norman's tavern is one of the few places offering a secure place to rest and recover amid an otherwise unwelcoming subterranean fortress.",["race:Undead"]="Norman offers fellow Forsaken a central gathering place in the heart of the Trade Quarter to rest their bones between assignments for the Dark Lady."},kw={"bates","hallow's end","hearthstone","innkeeper","norman","trade quarter","undercity"},rel={"subzone:trade-quarter","zone:undercity","topic:forsaken","topic:horde","quest:8353","topic:lordaeron"},src={"Innkeeper Norman"}}
E["npc:josef-gregorian"] = {t="npc",n="Josef Gregorian",z="undercity",s="Josef Gregorian is a Forsaken tailoring trainer found working in the Magic Quarter of the Undercity. He guides ambitious Horde tailors seeking to weave enchanted fabrics, providing expertise and directing them toward specialized garments.",h="Josef Gregorian is a Forsaken tailoring trainer found working in the Magic Quarter of the Undercity.",sec={{t="Weaver of the Magic Quarter",b="Amid the dim alchemical lanterns and damp vaults of the Magic Quarter, Josef Gregorian maintains the fine craft of tailoring for the Forsaken and their Horde allies. While life in the subterranean kingdom has turned cold, cloth-working remains vital for warlocks, mages, and priests who channel raw energies through woven fibers. Gregorian serves as a dependable instructor in the capital, ready to teach foundational patterns and direct advanced practitioners toward securing rare materials for enchanted attire.",sp=0}},faq={{q="Where can I find Josef Gregorian?",a="Josef Gregorian is located in the Magic Quarter of the Undercity, practicing and teaching the tailoring craft among the city's casters and scholars.",al={"josef gregorian location","where is gregorian","undercity tailor trainer"}},{q="What role does Josef Gregorian serve in the Undercity?",a="He is a tailoring trainer who teaches sewing recipes and techniques to Horde crafters. He also offers instruction on obtaining rare materials to craft specialized caster vestments like the Robe of the Archmage or other enchanted garments.",al={"what does josef gregorian do","josef gregorian trainer","undercity tailoring"}},{q="What quests does Josef Gregorian offer?",a="Gregorian assists tailoring practitioners with quests such as Gathering Materials and fashioning Spellfire Robes, tasking crafters with collecting elusive reagents needed to produce potent cloth garments.",al={"josef gregorian quests","robe quests undercity"}}},ang={["profession:Tailoring"]="For Horde clothiers, Josef Gregorian is a prime contact in Lordaeron, offering instruction and guiding skilled weavers in gathering materials for powerful woven robes.",["race:Undead"]="Gregorian demonstrates that despite death and undeath, the delicate arts of human tailoring survived the fall of Lordaeron to serve the new Forsaken society."},kw={"gathering materials","josef gregorian","magic quarter","spellfire robes","tailoring trainer","undercity"},rel={"subzone:magic-quarter","zone:undercity","quest:1961","quest:1962","topic:forsaken","topic:horde","topic:lordaeron"},src={"Josef Gregorian"}}
E["npc:lor-themar-theron"] = {t="npc",n="Lor'themar Theron",z="undercity",s="Lor'themar Theron is the Regent Lord of Quel'Thalas, entrusted with governing the ruined kingdom of the blood elves while Prince Kael'thas is away. A veteran ranger lord and former second-in-command to Ranger-General Sylvanas Windrunner, he bears the heavy burden of keeping his shattered people alive in the wake of the Scourge invasion.",h="Lor'themar Theron is the Regent Lord of Quel'Thalas, entrusted with governing the ruined kingdom of the blood...",sec={{t="From Ranger Lord to Regent",b="Before the Third War, Lor'themar Theron spent centuries serving as a decorated commander of the Farstriders, defending the northern elven borders against the Amani trolls and rising to become second-in-command to Ranger-General Sylvanas Windrunner. When Arthas and the Scourge decimated Quel'Thalas and destroyed the Sunwell, Lor'themar was among the surviving veterans who rallied the living remnants. When Prince Kael'thas Sunstrider departed for the south—and eventually into the unknown seeking a cure for their people's devastating addiction to magic—he named Lor'themar Regent Lord to safeguard the kingdom in his absence.",sp=0},{t="The Weight of the Sunstriders",b="Lor'themar never sought the crown or the political labyrinth of elven nobility. By instinct, he remains a scout and a soldier who prefers a bow and plain orders to courtly diplomacy. Yet with the Sunstrider dynasty abroad and Quel'Thalas surrounded by undead prowling the Ghostlands, Theron oversees the grueling day-to-day survival of the blood elves. His duties frequently bring diplomatic entanglements with the kingdom's former defender, now the Banshee Queen ruling Undercity, whose aid the desperate survivors of Quel'Thalas find difficult to refuse.",sp=0}},faq={{q="Who is Lor'themar Theron?",a="He is the Regent Lord of Quel'Thalas and leader of the blood elves remaining in Azeroth. Formerly the second-in-command of the Farstriders under Sylvanas Windrunner, he was granted leadership of the homeland by Prince Kael'thas Sunstrider.",al={"lorthemar lore","who is regent lord","who leads blood elves"}},{q="What is his relationship with Sylvanas Windrunner?",a="Lor'themar served as Sylvanas's trusted second-in-command during her life as Ranger-General of Silvermoon. Though they were longtime comrades in the Farstriders, her death, transformation into a banshee, and rule over the Forsaken have made their current relationship far more complicated and guarded.",al={"lorthemar and sylvanas","did lorthemar know sylvanas"}},{q="Is Lor'themar the king of the blood elves?",a="No. Lor'themar holds the title of Regent Lord, governing in the name of Prince Kael'thas Sunstrider, who remains the rightful monarch and leader of the sin'dorei while away seeking a remedy for their arcane withdrawal.",al={"is lorthemar king","is he prince kaelthas","who rules quel'thalas"}},{q="What military background does he have?",a="He is a veteran ranger lord who fought in the Second War against the Old Horde and Amani trolls, and served as a warden of the Sunwell. He spent centuries leading Farstrider companies before politics forced him into rulership.",al={"was lorthemar a farstrider","is lorthemar a ranger"}}},ang={["race:Undead"]="Forsaken travelers often remember that Sylvanas Windrunner's former comrades still breathe in the ruined north, with Lor'themar serving as the fragile bridge between Silvermoon and the Dark Lady's realm.",["class:Hunter"]="To marksmanship veterans and scouts, Lor'themar represents the pinnacle of the Farstrider tradition—a master marksman thrust from forest patrols into the burden of statecraft."},kw={"blood elf","farstriders","kael'thas","lor'themar","quel'thalas","regent lord","silvermoon","sin'dorei","theron"},rel={"npc:sylvanas-windrunner","topic:scourge","topic:lordaeron","topic:second-war","topic:third-war","subzone:the-sunstrider","topic:troll","topic:horde"},src={"Lor'themar Theron"}}
E["npc:master-apothecary-faranell"] = {t="npc",n="Master Apothecary Faranell",z="undercity",s="Master Apothecary Faranell is the head of the Royal Apothecary Society, stationed within the depths of the Apothecarium in the Undercity. In life a respected Dalaran scholar, in undeath he directs the Forsaken's search for a devastating New Plague to eradicate both the Scourge and the living.",h="Master Apothecary Faranell is the head of the Royal Apothecary Society, stationed within the depths of the...",sec={{t="A Mind Unhinged by Death",b="Before the Third War, Faranell was an esteemed alchemist who spent decades studying alongside the learned mages of Dalaran. He spent his mortal days seeking cures, remedies, and potions to improve mortal health. When the Scourge plague claimed his life and he arose as a free-willed Forsaken, his former scientific curiosity curdled into cruelty. Retaining his encyclopedic intellect, he traded healing salves for catastrophic reagents, quickly becoming one of Queen Sylvanas Windrunner's most valued researchers in the bowels of Lordaeron's fallen capital.",sp=0},{t="The Master of the Apothecarium",b="Operating out of the noxious laboratories of the Apothecarium, Faranell coordinates the far-flung research of the Royal Apothecary Society. He oversees the construction of lumbering abominations and directs subordinate apothecaries stationed throughout Lordaeron and beyond. Every batch of strange venom, tainted blood, and cursed flora gathered by field researchers across the continents eventually passes through his vats for distillation and refinement.",sp=0},{t="Crafting the New Plague",b="Faranell's single driving obsession is fulfilling the Dark Lady's mandate: uncovering the New Plague. To brew a contagion capable of destroying Arthas and his mindless Scourge legions, Faranell coordinates extensive reagent gathering. He dispatches adventurers to recover the research notes of his fallen colleague Apothecary Berard from Pyrewood Village, procures bat guano from the deep dens of Razorfen Kraul, and tests acidic colloids against the organs of zealots from the Scarlet Monastery.",sp=1}},faq={{q="Who is Master Apothecary Faranell?",a="Faranell is the head of the Royal Apothecary Society, the alchemical guild serving Lady Sylvanas Windrunner in the Undercity. He oversees all research regarding toxins, stitched abominations, and the development of the New Plague.",al={"who is faranell","faranell lore","apothecary leader"}},{q="Where can Faranell be found?",a="He resides in the Apothecarium, the alchemical quarter located in the western sector of the Undercity, surrounded by bubbling cauldrons, testing cages, and his apothecary subordinates.",al={"faranell location","where is master apothecary faranell","find faranell"}},{q="What was Faranell's background before he died?",a="In life, Faranell was an acclaimed alchemist and doctor who studied with the wizards of Dalaran. He spent his living years inventing remedies to heal disease before the plague killed him and twisted his curiosity toward lethal toxins.",al={"faranell history","was faranell in dalaran","faranell mortal life"}},{q="What is the Royal Apothecary Society trying to create?",a="Under Queen Sylvanas's directive, the society is manufacturing a New Plague. Their goal is to craft a weapon virulent enough to destroy the Scourge and exact vengeance upon the Lich King, while also defending the Forsaken from mortal enemies.",al={"what is the new plague","what are apothecaries making","apothecary goals"}},{q="Why does Faranell send adventurers to Pyrewood Village?",a="He seeks the research journal of his former colleague, Apothecary Berard, who went mad and succumbed to the worgen curse in Pyrewood. Berard's field notes contain critical data on toxic agents needed to refine their plague experiments.",al={"recipe for death quest faranell","why pyrewood village","apothecary berard journal"}},{q="Why does he need reagents from Razorfen Kraul and the Scarlet Monastery?",a="Faranell tests how opposing volatile compounds interact. He uses kraul guano collected from the razorfen quilboar dens alongside the freshly harvested hearts of Scarlet Crusade zealots to test acidic colloids and biological contamination.",al={"kraul guano faranell","hearts of zeal","scarlet monastery hearts"}}},ang={["race:Undead"]="For the Forsaken, Faranell represents the vanguard of biological sovereignty, laboring in the dark to ensure their people possess weapons capable of shattering the Lich King.",["faction:Horde"]="Though orc, troll, and tauren allies may be unsettled by the green ooze and caged subjects of the Apothecarium, Faranell's research is tolerated as vital warfare against the common threat of the Scourge.",["profession:Herbalism"]="Faranell's vats consume endless quantities of rare flora, mosses, and fungal extracts, serving as a dark demonstration of botanical study weaponized for destruction."},kw={"abomination","apothecarium","blight","faranell","master apothecary faranell","new plague","renferrel","royal apothecary society","sylvanas","undercity"},rel={"topic:royal-apothecary-society","subzone:apothecarium","zone:undercity","npc:sylvanas-windrunner","npc:apothecary-renferrel","quest:447","quest:509","topic:forsaken"},src={"Master Apothecary Faranell"}}
E["npc:raleigh-andrean"] = {t="npc",n="Raleigh Andrean",z="undercity",s="Raleigh Andrean is a Forsaken resident found lingering in the Trade Quarter of the Undercity. Once a living citizen of Lordaeron, he exemplifies the cold, twisted detachment common among the undead, caring little for the loss of his wife but fiercely desiring retribution against the friend who murdered her.",h="Raleigh Andrean is a Forsaken resident found lingering in the Trade Quarter of the Undercity.",sec={{t="A Bitter Afterlife",b="Before the Third War devastated Lordaeron, Raleigh Andrean lived an ordinary human life, married to a woman named Deliah and keeping company with his friend Valdred Moray. Like countless others, he fell when the Scourge tore through the kingdom, only to be raised as a mindless thrall in service to the Lich King. He regained his free will following the shattering of the Ner'zhul's grip and Sylvanas Windrunner's uprising, taking his place among the Forsaken in the Undercity.",sp=0},{t="Vengeance over Grief",b="When presented with his late wife's wedding ring, Raleigh displays the callous emotional decay of undeath. He harbors no sorrow or lingering love for Deliah, coldly dismissing her death. Instead, his focus fixates entirely on spite: he demands the severed hands of Valdred Moray, his former friend who murdered her. Raleigh keeps the gruesome trophies not out of affection for Deliah, but as an eternal memento of betrayal, rewarding whoever aids him with a ring forged of pure scorn.",sp=1}},faq={{q="Where is Raleigh Andrean located?",a="Raleigh Andrean resides within the bustling Trade Quarter of the Undercity, standing among the subterranean city's Forsaken populace.",al={"raleigh andrean location","where is raleigh","find raleigh andrean"}},{q="Who was Raleigh when he was alive?",a="In life, Raleigh was a mortal resident of the kingdom of Lordaeron. He was married to a woman named Deliah and shared a friendship with a man named Valdred Moray before the Scourge swept through the realm.",al={"raleigh backstory","who was raleigh","raleigh andrean lore"}},{q="Why does Raleigh want revenge on Valdred Moray?",a="Valdred Moray murdered Raleigh's wife, Deliah. While Raleigh no longer feels love or grief for his deceased spouse due to his undead state, he remains driven by bitter fury over his former friend's treacherous betrayal.",al={"why kill valdred","raleigh wife","valdred moray murder"}},{q="How did Raleigh become free from the Scourge?",a="Raleigh was slain and raised into servitude by the Scourge during the Third War. When the Lich King's control slipped following attacks on the Frozen Throne, Sylvanas Windrunner led an uprising, freeing Raleigh and many others to form the Forsaken.",al={"how did raleigh become forsaken","raleigh scourge freedom"}}},ang={["race:Undead"]="Raleigh is a grim reflection of Forsaken reality: undeath strips away warmth and grief, leaving behind only the cold embers of spite, vengeance, and lingering hatred toward those who betrayed them in life."},kw={"a husband's revenge","deliah","forsaken","raleigh andrean","ring of scorn","trade quarter","undercity","valdred moray"},rel={"quest:530","quest:441","zone:undercity","subzone:trade-quarter","topic:forsaken","topic:scourge","topic:lordaeron","topic:lich-king"},src={"Raleigh Andrean"}}
E["npc:sylvanas-windrunner"] = {t="npc",n="Sylvanas Windrunner",z="undercity",s="Lady Sylvanas Windrunner is the Banshee Queen and supreme ruler of the Forsaken, holding court in the Undercity beneath the ruins of Lordaeron. Once the brave Ranger-General of Silvermoon, she was slain and raised into undeath by Arthas Menethil before breaking free from the Lich King's grip. Now allied with Thrall's Horde out of mutual survival, she is fiercely dedicated to securing a future for her free-willed undead and exacting vengeance upon the Scourge.",h="Lady Sylvanas Windrunner is the Banshee Queen and supreme ruler of the Forsaken, holding court in the...",sec={{t="Fall of the Ranger-General",b="In life, Lady Sylvanas was the celebrated Ranger-General of Silvermoon, commanding the defense of Quel'Thalas during the Third War. When Prince Arthas Menethil marched the Scourge into the high elven kingdom to reach the Sunwell, Sylvanas fought fiercely to delay his advance. Frustrated by her resistance, Arthas murdered her, but denied her a clean death. He ripped her soul from her corpse and twisted it into a vengeful banshee, forcing her to serve the Scourge and assist in the slaughter of her own people.",sp=0},{t="Rise of the Forsaken",b="When the Lich King's magical grip fractured after the Third War, Sylvanas broke free of his dominion and repossessed her preserved body. Amassing other undead who had regained their free will, she overthrew the dreadlords occupying the ruins of Lordaeron, dubbed her people the Forsaken, and established the subterranean realm of the Undercity. Recognizing the precarious isolation of her people—threatened by Scourge remnants, zealous Scarlet crusaders, and suspicious human realms—she forged an uneasy alliance of convenience with Warchief Thrall and the Horde.",sp=0}},faq={{q="Who is Sylvanas Windrunner?",a="She is the sovereign leader of the Forsaken, holding court in the Royal Quarter of the Undercity. In life she was the elven Ranger-General of Quel'Thalas, but after being slain and raised by Arthas Menethil, she broke away from the Scourge to lead the free-willed undead.",al={"banshee queen","who is the dark lady","lady sylvanas","undercity leader"}},{q="Why did Sylvanas align the Forsaken with the Horde?",a="The Forsaken are reviled by the living nations of the Alliance, who see them only as monsters. Surrounded by the Scourge and the Scarlet Crusade in Lordaeron, Sylvanas required strong allies to ensure her fledgling nation's survival, prompting her to petition Warchief Thrall for entry into the Horde.",al={"why are undead in horde","forsaken horde alliance","sylvanas thrall pact"}},{q="How did Sylvanas break free from the Lich King?",a="When the Lich King's psychic power began to bleed away during the aftermath of the Third War, his iron control over the Scourge fractured. Sylvanas was among the first powerful spirits to regain her autonomy, immediately reclaiming her mortal remains and turning her wrath upon Arthas.",al={"how did sylvanas escape arthas","sylvanas free will","lich king control"}},{q="What is Sylvanas's primary goal?",a="Above all else, Sylvanas seeks total retribution against Arthas Menethil and the Scourge for destroying her homeland and enslaving her soul. Concurrently, she strives to fortify the Undercity and carve out a secure, permanent haven for the Forsaken in Lordaeron.",al={"what does sylvanas want","sylvanas motivation","dark lady goal"}}},ang={["race:Undead"]="To the Forsaken, the Dark Lady is a liberator and protector, the solitary reason they possess free will and a fortified home rather than mindlessly serving the Scourge.",["faction:Horde"]="Though accepted into the Horde through the advocacy of Archdruid Hamuul Runetotem and Thrall's compassion, many orcs and trolls view Sylvanas and her court with lingering wariness."},kw={"arthas","banshee queen","dark lady","forsaken","lordaeron","ranger-general","sylvanas","undercity","windrunner"},rel={"zone:undercity","topic:forsaken","topic:scourge","topic:arthas-menethil","topic:horde","npc:thrall","zone:tirisfal","topic:lordaeron"},src={"Sylvanas Windrunner"}}
E["npc:varimathras"] = {t="npc",n="Varimathras",z="undercity",s="Varimathras is a dreadlord of the nathrezim race who serves as the chief lieutenant and military advisor to Lady Sylvanas Windrunner. Forced to pledge loyalty to the Banshee Queen after suffering defeat during the civil war for Lordaeron, he now stands at her right hand in the Royal Quarter of the Undercity.",h="Varimathras is a dreadlord of the nathrezim race who serves as the chief lieutenant and military advisor to...",sec={{t="Jailor of the Lich King",b="Before the Third War, Varimathras and his fellow dreadlords worked directly under Kil'jaeden to break and reshape the spirit of Ner'zhul into the Lich King. Bound alongside his brothers Detheroc and Balnazzar, he oversaw the Scourge in Lordaeron while Archimonde invaded Kalimdor. When the Legion fell at Mount Hyjal, the triumvirate remained entrenched in the ruins of the Capital City, entirely unaware of their master's demise until Prince Arthas returned to drive them into hiding.",sp=0},{t="A Demon's Surrender",b="As the Lich King's hold over his undead forces fractured, Varimathras attempted to coerce the newly freed banshee Sylvanas Windrunner into serving the dreadlords' new regime. Sylvanas refused, rallying liberated undead to crush Varimathras's outpost. Facing execution, the dreadlord fell to his knees and bartered for his life, trading tactical secrets and knowledge of his brothers' fortifications in exchange for survival. Sylvanas accepted, binding him to her service as a living weapon against his kin.",sp=0},{t="Brother Against Brother",b="To secure Sylvanas's trust, Varimathras was made to commit the unthinkable: violating the sacred nathrezim law that forbids a dreadlord from killing another. Under her direct command, he assassinated his sibling Balnazzar after the conquest of the Capital City and summarily executed the human warlord Grand Marshal Garithos. Now stationed beside Sylvanas's throne, Varimathras coordinates military excursions across the Plaguelands, though many in the Horde look upon this demonic ally with deep unease.",sp=1}},faq={{q="Why is a demon serving the Forsaken?",a="When Sylvanas Windrunner gathered her army of newly liberated undead during the Lordaeron civil war, she routed Varimathras's forces. Facing imminent death, the dreadlord pleaded for mercy and offered his cunning, military knowledge, and service in exchange for his life. Sylvanas spared him to use as a tactician and enforcer.",al={"why is varimathras in undercity","why dreadlord with sylvanas","varimathras allegiance"}},{q="What kind of creature is Varimathras?",a="Varimathras is a nathrezim, commonly known as a dreadlord. The nathrezim are an intelligent, manipulative race of demons who serve the Burning Legion, specializing in mental domination, shadow magic, and spreading plague and discord.",al={"what race is varimathras","is varimathras a vampire","varimathras species"}},{q="Where does Varimathras stand in the Undercity?",a="He can be found standing on the dais in the Royal Quarter of the Undercity, directly beside Lady Sylvanas Windrunner, surrounded by Forsaken royal guards.",al={"where is varimathras","varimathras location","find varimathras"}},{q="Did Varimathras really kill his fellow dreadlord Balnazzar?",a="Yes. Dreadlords are strictly forbidden by their own kind from killing another nathrezim. To test his loyalty and secure his place, Sylvanas forced Varimathras to strike down Balnazzar after the reclaiming of Lordaeron's capital city, crossing a line no demon was thought capable of crossing.",al={"did varimathras kill balnazzar","varimathras brother","dreadlord taboo"}},{q="What role did Varimathras play in creating the Scourge?",a="On the orders of Kil'jaeden, Varimathras and his fellow dreadlords tortured the captive spirit of the orc shaman Ner'zhul in the Twisting Nether, breaking his sanity and binding him inside the Frozen Throne to fashion the Lich King before deploying him to Azeroth.",al={"varimathras nerzhul","varimathras lich king origin"}},{q="Do the other Horde leaders trust Varimathras?",a="Not at all. The orcs, trolls, and tauren carry deep scars from demonic corruption and regard dreadlords as monstrous manipulators. Even among the Forsaken, many view Varimathras as an uneasy weapon held on a very tight leash rather than a true brother-in-arms.",al={"does the horde trust varimathras","thrall varimathras","is varimathras trusted"}}},ang={["race:Undead"]="Varimathras represents the Forsaken's pragmatic willingness to turn the weapons of their oppressors against them, standing subdued beside the Dark Lady who freed Lordaeron from his grip.",["class:Warlock"]="To practitioners of demonic magic, the sight of a high-ranking nathrezim serving a mortal undead queen is an impressive, if unsettling, display of leveraged will.",["faction:Horde"]="The dreadlord's presence in Undercity is a source of intense friction with Orgrimmar, as the Horde spent decades breaking free from the very demonic masters Varimathras served."},kw={"balnazzar","detheroc","dreadlord","nathrezim","royal quarter","sylvanas","undercity","varimathras"},rel={"npc:sylvanas-windrunner","zone:undercity","topic:forsaken","topic:lordaeron","topic:burning-legion","topic:scourge","topic:lich-king","topic:third-war"},src={"Varimathras"}}
E["npc:varok-saurfang"] = {t="npc",n="Varok Saurfang",z="undercity",s="High Overlord Varok Saurfang is a legendary orc warrior of the Blackrock clan and a veteran of the First, Second, and Third Wars. Serving as Warchief Thrall's trusted military commander, he represents the proud martial spine of the modern Horde while privately carrying the heavy remorse of past atrocities.",h="High Overlord Varok Saurfang is a legendary orc warrior of the Blackrock clan and a veteran of the First...",sec={{t="A Living Legend of the Wars",b="Few living warriors possess a martial pedigree to rival Varok Saurfang. A member of the revered Blackrock clan, Saurfang served alongside Eitrigg under Blackhand and later became the trusted second-in-command to Warchief Orgrim Doomhammer himself. Through the savage assaults on Stormwind in the First War and the brutal northern marches across the Hillsbrad Foothills and the Hinterlands in the Second War, Saurfang was considered an unstoppable force on the battlefield. When Thrall rallied the scattered orc clans to cross the Great Sea and establish Durotar, Saurfang took up arms once more, defending Kalimdor through the Third War and standing as a bulwark of the newborn Horde.",sp=0},{t="The Weight of the Blood",b="Though he stands as an unmatched champion of the Horde, Saurfang is not driven by reckless battle-lust. Like many of his generation, he freely partook in the demonic blood of Mannoroth before the opening of the Dark Portal and bears deep sorrow for the cruelties carried out under the Blood Curse. Following the sacrifice of Grommash Hellscream that freed the orcs, Saurfang has dedicated much of his life to counseling fellow veterans through their guilt. While he will relentlessly defend the Horde and enforce Thrall's rule against any threat, Saurfang harbors a profound disdain for warmongering and fights strictly for honor and preservation.",sp=0}},faq={{q="Who is Varok Saurfang?",a="Varok Saurfang is a renowned orc warrior of the Blackrock clan, brother of the famous Broxigar, and the primary military commander serving Warchief Thrall in the Horde.",al={"varok saurfang backstory","who is saurfang","high overlord saurfang"}},{q="What wars did Saurfang fight in?",a="Saurfang fought in the First, Second, and Third Wars. He led Blackrock forces during the sack of Stormwind, served as Orgrim Doomhammer's second-in-command across Lordaeron, and defended Mount Hyjal alongside Thrall's forces.",al={"saurfang war history","did saurfang fight in the first war","saurfang battles"}},{q="How does Saurfang view the Horde's past?",a="Saurfang deeply regrets the atrocities committed under the demon blood curse, especially the slaughter of innocent draenei on Draenor. The memory haunts him so thoroughly that he refuses to eat pork because the sound of swine slaughter echoes the screams of dying children.",al={"saurfang blood curse","saurfang draenei guilt","why does saurfang regret the past"}},{q="What is Saurfang's role in the current Horde?",a="He serves as High Overlord of Thrall's forces, overseeing military readiness, enforcing the Warchief's commands, and acting as a seasoned mentor to younger warriors within the Horde.",al={"what does saurfang do now","saurfang orgrimmar role"}}},ang={["race:Orc"]="To the orcs, High Overlord Saurfang is both the ultimate paragon of martial strength and a sobering reminder of the spiritual toll exacted by the demonic blood curse.",["class:Warrior"]="Warriors revere Saurfang as a peerless veteran whose axe technique, tactical battlefield brilliance, and enduring resolve define the ideal soldier."},kw={"blackrock","broxigar","doomhammer","korkron","overlord","saurfang","thrall","varok","warrior"},rel={"npc:thrall","npc:orgrim-doomhammer","npc:eitrigg","topic:blackrock-clan","topic:grommash-hellscream","topic:first-war","topic:second-war","topic:third-war"},src={"Varok Saurfang"}}
E["quest:1359"] = {t="quest",n="Zinge's Delivery",z="undercity",s="Zinge's Delivery is a courier task dispatched by Apothecary Renferrel from the Sepulcher in Silverpine Forest. It transports strangely toxic wolf heart tissue back to Apothecary Zinge in the Undercity for formal study by the Royal Apothecary Society.",h="Zinge's Delivery is a courier task dispatched by Apothecary Renferrel from the Sepulcher in Silverpine Forest.",sec={{t="A Toxic Anomaly",b="While examining local wildlife around Silverpine Forest, Apothecary Renferrel observed an unsettling physiological trait within the wolves roaming the ruined woods. Their hearts carried a level of toxicity so profound that, under any ordinary circumstances, it ought to have killed the beasts housing them. Rather than discarding the tissue, Renferrel packaged several samples to share with colleagues at the Apothecarium in the Undercity.",sp=0},{t="The Eyes of the Apothecarium",b="The preserved organs are delivered directly to Apothecary Zinge, a researcher working in the subterranean headquarters of the Royal Apothecary Society. For the society, whose primary ambition is formulating potent plagues and novel alchemical compounds, naturally occurring poisons that sustain rather than slay are of paramount interest. Zinge welcomes the delivery as the foundation for further laboratory trials across the Forsaken alchemical network.",sp=0}},faq={{q="What are the wolf heart samples?",a="They are preserved biological tissue gathered from wolves in Silverpine Forest. Apothecary Renferrel discovered that the hearts contain natural toxins deadly enough that the animals should not have survived carrying them.",al={"wolf hearts","what are wolf heart samples","renferrel samples"}},{q="Who is Apothecary Renferrel?",a="Apothecary Renferrel is a member of the Royal Apothecary Society stationed at the Sepulcher in Silverpine Forest. He oversees field research on regional flora and fauna to harvest ingredients and biological insights for Forsaken alchemy.",al={"who is renferrel","renferrel silverpine"}},{q="Who is Apothecary Zinge?",a="Apothecary Zinge is an alchemical researcher based within the Apothecarium quarter of the Undercity. She experiments with incoming biological specimens to uncover new toxins and alchemical agents for the Forsaken.",al={"who is zinge","zinge undercity","apothecary zinge lore"}},{q="Where does this delivery lead next?",a="Once Zinge receives and inspects the strange heart tissue, the research continues as samples are routed to other alchemical outposts, such as Apothecary Helbrim stationed across the sea in the Barrens.",al={"next quest","what happens after zinge's delivery","follow up quest"},sp=1},{q="Why is the Royal Apothecary Society interested in wolf hearts?",a="The Royal Apothecary Society constantly seeks exotic poisons, diseases, and biological anomalies. A beast that survives lethal self-toxicity presents unique chemical pathways that could aid their development of new plagues and compounds.",al={"why do apothecaries want wolf hearts","ras wolf hearts"}},{q="Where is the Apothecarium in Undercity?",a="The Apothecarium forms the southwestern wing of the Undercity. It serves as the primary laboratory complex and governing headquarters of the Royal Apothecary Society.",al={"undercity apothecary location","where is zinge","apothecarium map"}}},ang={["race:Undead"]="Field samples collected in Lordaeron feed directly into the central alchemical laboratories beneath the Capital City ruins, advancing the scientific power of the Forsaken.",["faction:Horde"]="Messengers carrying biological reagents keep remote outposts like the Sepulcher unified with the leadership and research hubs in the Undercity."},kw={"apothecarium","apothecary renferrel","apothecary zinge","sepulcher","silverpine","undercity","wolf heart samples","zinge's delivery"},rel={"npc:apothecary-zinge","npc:apothecary-renferrel","topic:royal-apothecary-society","zone:undercity","quest:1358","quest:3221"},m={start="Apothecary Renferrel",["end"]="Apothecary Zinge",level="15",faction="Horde",id=1359},src={"Zinge's Delivery"}}
E["quest:1471"] = {t="quest",n="The Binding",z="undercity",s="The Binding is the culminating rite for Forsaken warlocks seeking to command a voidwalker. In the Magic Quarter of the Undercity, Carendin Halgar requires initiates to summon, conquer, and permanently subjugate a creature of the Void.",h="The Binding is the culminating rite for Forsaken warlocks seeking to command a voidwalker.",sec={{t="A Rite of Subjugation",b="Unlike minor imps, which are easily coerced into pacts with dark magic, creatures of the Void despise reality and possess formidable physical might. To earn the right to summon a voidwalker, an aspiring warlock in the Undercity must prove total mastery over it. In the shadowed enclave of the Magic Quarter, the Forsaken mentor Carendin Halgar provides the mystic runes required to tear a voidwalker from the Nether into the physical realm.",sp=0},{t="Within the Circle",b="The ritual takes place within the glowing summoning circle etched beneath the mentor's dais. Once the runes are activated, an unbound voidwalker materializes in fury. Subduing it is not an exercise in diplomacy; the summoner must break the entity through sheer arcane force and raw will. Only when the entity is thoroughly crushed does Carendin reveal the true formula of summoning, binding the creature's essence to the practitioner indefinitely.",sp=0}},faq={{q="What is the purpose of this ritual?",a="The ritual tests an aspiring warlock's ability to overpower a creature of the Void. By defeating an unbound voidwalker in combat, the summoner proves their will is strong enough to control it, allowing Carendin Halgar to teach them the permanent summoning spell.",al={"why do the binding","what does the binding quest do","binding reward"}},{q="Where does the summoning take place?",a="It takes place directly within the purple summoning circle etched into the floor beneath Carendin Halgar's platform in the Magic Quarter of the Undercity.",al={"where do i summon voidwalker","where is the summoning circle","circle of summoning undercity"}},{q="Who is Carendin Halgar?",a="Carendin Halgar is the primary warlock trainer residing in the Magic Quarter of the Undercity, overseeing the instruction and dark initiations of newly raised Forsaken practitioners.",al={"who is halgar","carendin halgar lore"}},{q="Do warlocks need to defeat every demon they want to summon?",a="Warlocks must establish authority over powerful extradimensional beings before commanding them. While smaller entities like imps are bound by simple contracts and rituals, voidwalkers require physical and magical dominance before they submit to servitude.",al={"do warlocks always fight demons","why fight the voidwalker"}},{q="What happens if a warlock fails to subdue the voidwalker?",a="An unbound voidwalker will relentlessly batter and destroy anyone nearby. As Halgar warns, failing to meet his expectations is nothing compared to the danger of being torn apart by the untamed entity within the circle.",al={"what if i fail the binding","failure lore warlock"}},{q="What is a voidwalker?",a="Voidwalkers are shadowy, extradimensional beings originating from the Void. They possess immense physical resilience and an innate desire to extinguish living light and energy, making them ideal protective shields for practitioners of dark magic.",al={"what is a voidwalker","voidwalker lore"}}},ang={["class:Warlock"]="This rite marks the warlock's transition from petty trickery with imps to genuine domination over entities capable of absorbing immense physical punishment on the battlefield.",["race:Undead"]="For the Forsaken, binding a creature of shadow is a natural extension of their resilience and lack of moral restraint regarding forbidden magic."},kw={"carendin halgar","magic quarter","runes of summoning","subjugation","the binding","undercity","voidwalker","warlock quest"},rel={"npc:carendin-halgar","quest:1473","quest:1478","subzone:magic-quarter","zone:undercity"},m={start="Carendin Halgar",level="10",faction="Horde",id=1471},src={"The Binding (Voidwalker, Undercity)"}}
E["quest:1472"] = {t="quest",n="Devourer of Souls",z="undercity",s="Devourer of Souls is an introductory step in a Forsaken warlock's journey to summon and bind a succubus. Directed by Carendin Halgar in the Undercity's Temple of the Damned, the practitioner must confer with his assistant, Godrick Farsan, to learn how to lure such a creature from the Twisting Nether. The ritual demands an irresistible stimulus: the hearts of pure and loving mortals.",h="Devourer of Souls is an introductory step in a Forsaken warlock's journey to summon and bind a succubus.",sec={{t="Baiting the Nether",b="Carendin Halgar teaches that a succubus cannot simply be pulled across the threshold on command; it must be enticed. Driven by an insatiable hunger to ruin virtue and consume mortal essence, the demon requires a specific lure. The warlock's strategy relies on exploiting this singular desire by offering up the hearts of genuinely virtuous, loving men as bait. Halgar directs his acolytes to Godrick Farsan, who knows where such rare quarry can be harvested.",sp=0},{t="The Blind Assistant",b="Located deeper within the Temple of the Damned, Godrick Farsan assists Carendin with the practical preparations of demonic binding. Though Farsan has lost his physical eyesight, he claims his condition grants him a profound second sight—allowing him to perceive underlying spiritual currents and far-off souls with uncanny clarity. He serves as the guide for locating the pure hearts necessary to draw the demon forth.",sp=0}},faq={{q="What is the purpose of this quest?",a="This quest bridges Carendin Halgar's initial summons with the practical hunting phase required to bind a succubus. It sends the warlock to Godrick Farsan, who details the morbid components needed for the ritual.",al={"why do devourer of souls","succubus quest undercity","warlock quest level 20"}},{q="Why does a succubus need pure hearts to be summoned?",a="A succubus thrives on corrupting goodness, tempting mortal hearts, and devouring virtuous souls. Carendin Halgar explains that the demon cannot easily breach into this world without an irresistible stimulus, making the untainted devotion of good men the ideal bait to lure it across.",al={"why hearts of the pure","succubus bait lore"}},{q="Who is Godrick Farsan?",a="Godrick Farsan is an undead warlock acolyte assisting Carendin Halgar in the Temple of the Damned. Despite being physically blind, he possesses mystical senses that allow him to perceive spiritual truths and locate suitable prey across the Eastern Kingdoms.",al={"who is farsan","blind warlock assistant"}},{q="Where is this quest completed?",a="The quest is turned in directly within the Temple of the Damned in the Undercity, just a few paces away from Carendin Halgar, where Godrick Farsan stands waiting.",al={"where is godrick farsan","devourer of souls turn in"}},{q="What comes after Devourer of Souls?",a="Farsan immediately assigns the quest 'Hearts of the Pure,' tasking the warlock with traveling to the Wetlands and the Hillsbrad Foothills to claim the hearts of two virtuous mortals.",al={"next quest after devourer of souls","hearts of the pure next"}},{q="Can any race undertake this ritual?",a="While it is situated in the Undercity and instructed by Forsaken practitioners, any Horde warlock seeking to bind a succubus through Undercity mentors can perform the ritual steps provided by Halgar and Farsan.",al={"who can do devourer of souls","undead only warlock quest"}}},ang={["class:Warlock"]="Binding a succubus is a major milestone in a warlock's training, demonstrating the dark art of leveraging a demon's inherent vices and appetites to enslave it.",["race:Undead"]="The Forsaken warlock trainers in the Temple of the Damned operate without moral restraint, casually treating living purity and devotion as disposable reagents for Nether rituals."},kw={"bait","carendin halgar","godrick farsan","hearts of the pure","succubus","temple of the damned","undercity"},rel={"npc:carendin-halgar","npc:godrick-farsan","quest:1476"},m={start="Carendin Halgar",["end"]="Godrick Farsan",level="20",faction="Horde",id=1472},src={"Devourer of Souls (Undercity)"}}
E["quest:1473"] = {t="quest",n="Creature of the Void",z="undercity",s="Creature of the Void is a pivotal rite of passage for Forsaken warlocks, tasking them with recovering a lost arcane text from the Scarlet Crusade. To learn how to summon and bind a chaotic voidwalker, an initiate must venture west of Tirisfal Glades and retrieve Egalin's Grimoire from hostile zealots.",h="Creature of the Void is a pivotal rite of passage for Forsaken warlocks, tasking them with recovering a lost...",sec={{t="A Teacher's Legacy",b="Within the dark alcoves of the Temple of the Damned in the Undercity, Carendin Halgar oversees the development of rising Forsaken summoners. When an acolyte proves competent enough to wield power beyond petty imps, Halgar directs them toward binding a creature forged from pure shadow and chaos: the voidwalker. Rather than relying on simple instinct, Forsaken practitioners base their summons on the meticulous research of Egalin, Halgar's own former master, who first penned the rituals necessary to subjugate these monstrous denizens of the void.",sp=0},{t="The Stolen Grimoire",b="Mastery of the voidwalker cannot be achieved without Egalin's Grimoire, which contains the precise methods for channeling such volatile magic. However, the precious tome was stolen by an agent of the Scarlet Crusade—a zealot named Perrine stationed in an outpost tower to the west. While Perrine and his crusaders likely viewed the grimoire as mere blasphemous contraband to confiscate and hoard, recovering it is essential if the Forsaken are to secure the ritual secrets before attempting to tear open the veil.",sp=0}},faq={{q="What is Egalin's Grimoire?",a="Egalin's Grimoire is a magical manual authored by the warlock Egalin, who taught Carendin Halgar. It details the intricate channeling techniques and spells required to breach the void and summon a voidwalker under the caster's absolute control.",al={"egalins grimoire","what is the book","who was egalin"}},{q="Why did the Scarlet Crusade steal the book?",a="The Scarlet Crusade considers all demonic and shadow magic inherently corrupt. An agent named Perrine seized the grimoire during a skirmish or infiltration, stashing it away in a western watchtower in Tirisfal Glades, seemingly unaware of the specific summoning power contained inside.",al={"why did scarlet crusade take it","perrine grimoire","scarlet tower west"}},{q="Who is Carendin Halgar?",a="Carendin Halgar is a master warlock trainer residing in the Temple of the Damned within the Undercity. He guides novice Forsaken warlocks, teaching them respect for volatile cosmic forces and caution born from his own past summoning mistakes.",al={"carendin halgar","warlock trainer undercity","temple of the damned trainer"}},{q="What happens if a warlock loses control of a voidwalker?",a="Voidwalkers are beings of pure chaos and shadow. As Carendin Halgar warns, if an initiate attempts to conjure one without flawless discipline and binding will, the entity will violently tear its summoner apart.",al={"can voidwalker kill you","voidwalker danger","summoning failure"}},{q="What comes after recovering the grimoire?",a="Once Halgar has the book, he studies the text to impart the ritual runes to you. This immediately leads into 'The Binding', where the initiate must use the summoning circle to conjure a voidwalker and defeat it in personal combat to establish dominance.",al={"what next after grimoire","next quest","binding ritual"},sp=1},{q="Where is the Scarlet Crusade outpost located?",a="The grimoire is hidden inside a Scarlet Crusade watchtower situated to the west across Tirisfal Glades, guarded by crusaders under the command of Perrine.",al={"where is perrine","scarlet tower location","where is the book"}}},ang={["class:Warlock"]="This quest marks your transition from dabbling with imps to controlling heavy frontline shadow entities capable of absorbing immense physical punishment.",["race:Undead"]="Striking the Scarlet Crusade to reclaim dark knowledge underscores the bitter struggle between the Forsaken and the living zealots occupying Lordaeron's ruins.",["faction:Horde"]="The dark arts practiced in the Undercity operate on strict scholarly technique, turning dangerous planar forces into reliable assets for the Horde's frontier wars."},kw={"carendin halgar","egalin","egalins grimoire","perrine","scarlet crusade","temple of the damned","tirisfal glades","undercity","voidwalker"},rel={"npc:carendin-halgar","quest:1471","quest:1478","topic:scarlet-crusade","zone:undercity"},m={start="Carendin Halgar",level="10",faction="Horde",id=1473},src={"Creature of the Void (Undercity)"}}
E["quest:1474"] = {t="quest",n="The Binding",z="undercity",s="The Binding is the final initiation in an Undercity warlock's journey to summon and command a succubus. Directed by Carendin Halgar, the practitioner uses pure hearts to draw a demon from the Twisting Nether into a ritual circle, subjugating its will through combat.",h="The Binding is the final initiation in an Undercity warlock's journey to summon and command a succubus.",sec={{t="A Test of Will",b="Within the dark alcoves of the Magic Quarter, Forsaken warlocks refine their command over demonic entities. Summoning a succubus is considered a critical rite of passage. Unlike the brute force of a voidwalker or the minor malice of an imp, a succubus wields seductive and mental enchantments capable of ensnaring the caster. Carendin Halgar requires initiates to prove their mind and magic are ironclad before trusting them with permanent dominion over such an entity.",sp=0},{t="Subjugation in the Circle",b="Drawing upon the harvested Pure Hearts gathered from innocent souls in the wetlands and hills, the warlock unlocks an aperture into the Twisting Nether. Once summoned into the binding circle, the demon attacks instantly, seeking to overpower or entrance the caster. Only by breaking its physical form and casting its essence back into the void does the warlock assert complete mastery, earning the knowledge needed to call forth the demon at will.",sp=1}},faq={{q="What is the purpose of this quest?",a="This ritual allows Forsaken warlocks to prove their mastery over higher demons. By summoning and defeating a succubus in the Magic Quarter, the warlock proves they cannot be swayed by its charms, earning the spell to summon and command one in battle.",al={"why do the binding","what does the binding reward","what is this quest for"}},{q="Who is Carendin Halgar?",a="Carendin Halgar is a warlock trainer located in the Magic Quarter of the Undercity. He oversees the training and trials of Forsaken spellcasters, testing their mental endurance and dark arts before granting them more dangerous summoning rituals.",al={"who gives the binding","carendin halgar lore"}},{q="Why were pure hearts needed to summon the demon?",a="Demons of the succubus breed feed upon emotion, purity, and corruption. The Pure Hearts acquired in earlier tasks act as an irresistible metaphysical bait, coaxing the demon to manifest directly into the mortal realm through the summoning circle.",al={"why pure hearts","hearts of the pure purpose"}},{q="Where does the summoning take place?",a="The summoning takes place directly in the Magic Quarter of the Undercity, using the specialized ritual circle near Carendin Halgar and the warlock mentors.",al={"where do i summon the succubus","undercity summoning circle location"}},{q="Why does the succubus need to be slain?",a="Warlocks do not negotiate with their minions; they subjugate them. By shattering the demon's form in the summoning circle, the warlock bends its spirit to their dominance, ensuring it returns as a subservient thrall rather than a master.",al={"why fight the succubus","why kill summoned succubus"}},{q="Are succubi dangerous to Undercity warlocks?",a="Yes. Even though Forsaken possess considerable mental resilience against fear and sleep, Carendin Halgar explicitly warns that a succubus's charms have bound many strong minds. Carelessness during the ritual results in death or enslavement.",al={"can a succubus charm undead","succubus danger"}}},ang={["class:Warlock"]="This rite represents a crucial step in your dark path, demonstrating your capacity to master seductive mental forces and bind cunning Nether-spawn to your will.",["race:Undead"]="Forsaken practitioners view demonic subjugation pragmatically, using whatever dark tools are necessary to secure survival and dominion in Lordaeron."},kw={"binding","carendin halgar","magic quarter","pure hearts","succubus","undercity","warlock"},rel={"npc:carendin-halgar","quest:1476","subzone:magic-quarter","zone:undercity"},m={start="Carendin Halgar",level="20",faction="Horde",id=1474},src={"The Binding (Succubus, Undercity)"}}
E["quest:1476"] = {t="quest",n="Hearts of the Pure",z="undercity",s="Hearts of the Pure is a sinister warlock trial assigned in the Undercity by Godrick Farsan on behalf of Carendin Halgar. In order to prepare the ritual bait needed to bind a succubus, an aspiring summoner must hunt down and butcher two uniquely righteous human men. Their pure hearts serve as an irresistible temptation for the demonic temptress awaiting summoning.",h="Hearts of the Pure is a sinister warlock trial assigned in the Undercity by Godrick Farsan on behalf of...",sec={{t="Bait for a Demon",b="Binding a succubus requires an understanding of temptation that cuts both ways. While the Nether's sirens prey upon desire and ruin, nothing draws them out of the Twisting Nether quite like untainted virtue ripe for corruption. Within the Temple of the Damned, master summoner Carendin Halgar delegates the groundwork to Godrick Farsan, who scours human lands for souls whose goodness remains pristine and unbroken.",sp=0},{t="The Quarry",b="Farsan identifies two distinct paragons of virtue. The first is Dalin Forgewright, an honorable man attending to desperate Lordaeron refugees barred from sanctuary outside the sealed Greymane Wall in southern Silverpine. The second is Comar Villard, a faithful husband tirelessly searching the perilous marshlands of the Wetlands for any trace of his lost wife. To a Forsaken warlock, their devotion, empathy, and loyalty make them prime sacrifices.",sp=0},{t="A Forsaken Perspective",b="Carrying out the hunt requires the summoner to traverse dangerous Alliance-held and wild territories, culminating in the butchery of both men. Upon returning the bloody prizes to the Temple of the Damned, Carendin Halgar observes with dark irony that the physical organ of a good man appears no different than any other corpse's remains. Yet in the dark arts of demonology, the spiritual purity clinging to their flesh is potent enough to lure a succubus into captivity.",sp=1}},faq={{q="Why do warlocks need pure hearts to summon a succubus?",a="A succubus thrives on corrupting mortal innocence and virtue. To lure one across the Nether and trap her in a binding circle, Carendin Halgar requires bait she cannot resist. The hearts of genuinely pure and selfless men provide that irresistible spiritual temptation.",al={"why pure hearts","succubus bait lore","why kill dalin and comar"}},{q="Who is Dalin Forgewright?",a="Dalin Forgewright is an honorable human patrolling on horseback along the closed gates of the Greymane Wall in southern Silverpine Forest. He dedicated his life to caring for and protecting the displaced refugees of Lordaeron who were rejected and shut out by the kingdom of Gilneas.",al={"dalin forgewright lore","who is dalin","greymane wall guy"}},{q="Who is Comar Villard?",a="Comar Villard is a devoted human wanderer found searching the northern road of the Wetlands just south of the Thandol Span. Unlike common travelers, he is driven purely by grief and steadfast love, refusing to abandon his search for his missing wife.",al={"comar villard lore","who is comar","wetlands human heart"}},{q="Where does this quest chain lead?",a="Delivering the two hearts to Carendin Halgar allows him to prepare the summoning circle in the Temple of the Damned. This immediately leads into 'The Binding', where the warlock summons and subdues a succubus to serve as a permanent minion.",al={"what comes next","after hearts of the pure","succubus quest reward"},sp=1},{q="Who gives this quest?",a="Godrick Farsan, an assistant located in the Temple of the Damned within the Undercity's Magic Quarter, gives the assignment. He projects magical illusions of Dalin and Comar to show the warlock exactly whom to hunt.",al={"who starts hearts of the pure","godrick farsan quest"}},{q="Why does Carendin Halgar dismiss the appearance of the hearts?",a="Upon completing the quest, Carendin observes with grim detachment that the physical heart of a goodly man looks virtually identical to any other slab of flesh. As an Undead practitioner of the dark arts, physical morality means little to him beyond its utility as a magical reagent.",al={"carendin dialogue","heart appearance"}}},ang={["class:Warlock"]="This rite of passage teaches that a warlock must learn to weaponize not just misery and fear, but the very nobility of others to bind demons to their will.",["race:Undead"]="The mission illustrates the chilling worldview of the Forsaken, who casually view the remaining survivors of Lordaeron and their enduring virtues as convenient livestock for ritual slaughter.",["faction:Alliance"]="The victims are tragic figures among the Alliance and human remnants—one guarding starving refugees shut out by Gilneas, the other searching in vain for a lost spouse in the marshlands."},kw={"carendin halgar","comar villard","dalin forgewright","godrick farsan","greymane wall","hearts of the pure","succubus","temple of the damned","thandol span","undercity"},rel={"npc:carendin-halgar","npc:godrick-farsan","subzone:greymane-wall","subzone:thandol-span","zone:silverpine","zone:wetlands","topic:lordaeron","topic:alliance"},m={start="Godrick Farsan",["end"]="Carendin Halgar",level="20",faction="Horde",id=1476},src={"Hearts of the Pure"}}
E["quest:1478"] = {t="quest",n="Halgar's Summons",z="undercity",s="Halgar's Summons is a formal directive given to rising Forsaken warlocks who have reached a critical threshold in their dark craft. Master Carendin Halgar requires their presence in the Magic Quarter of the Undercity to begin rigorous advanced training. Answering his call sets the stage for summoning and binding dangerous entities from the Nether.",h="Halgar's Summons is a formal directive given to rising Forsaken warlocks who have reached a critical...",sec={{t="A Master's Notice",b="When a warlock operating around Brill or the Tirisfal wilderness demonstrates adequate control over basic fel energies, word reaches the deeper subterranean halls of the Undercity. Senior practitioners such as Ageron Kargal serve as talent spotters, relaying notices to those who show genuine promise. To be summoned by Carendin Halgar is both a rare privilege and a perilous undertaking, indicating that basic imps and petty curses no longer suffice for the practitioner's education.",sp=0},{t="The Magic Quarter",b="Halgar oversees warlock rites from the shadowed reaches of the Magic Quarter, situated near the sinister altar known as the Temple of the Damned. Forsaken darkcasters operate without the squeamish moral restrictions of the living, yet even they demand rigorous discipline when dabbling in planar summonings. Halgar does not tolerate hesitation or sentimentality; his summons expects immediate deference and complete readiness to confront the hostile horrors of the Twisting Nether.",sp=0}},faq={{q="Who is Carendin Halgar?",a="Carendin Halgar is the primary warlock trainer residing in the Magic Quarter of the Undercity. He oversees the dark development of Forsaken summoners and tests their resolve before teaching them to bind powerful Nether creatures.",al={"carendin halgar","master halgar","who is halgar"}},{q="Who directs me to Halgar?",a="Ageron Kargal, an established warlock trainer stationed in Brill, dispatches you after receiving word that Master Halgar has taken a personal interest in your progression.",al={"who gives halgars summons","ageron kargal","who gives quest"}},{q="Where can I find Carendin Halgar in Undercity?",a="Halgar is located within the Magic Quarter of the Undercity, positioned close to the dark dais known as the Temple of the Damned.",al={"halgar location","where is halgar","magic quarter halgar"}},{q="Why is this summons important?",a="The summons marks your transition from rudimentary spellcasting to high-risk demonic subjugation, specifically initiating the trials required to bind a Voidwalker into your service.",al={"why do i need this quest","quest purpose","what does halgars summons lead to"}},{q="Is Halgar willing to teach anyone?",a="Halgar specifically focuses his attention on promising warlocks. He wastes little time on idle pleasantries and demands that any apprentice brought before him has proven capable of handling volatile fel arts.",al={"can anyone talk to halgar","halgar requirements"}},{q="What happens after reporting to Halgar?",a="Once you report to Halgar, he immediately tests your magical capability by assigning you tasks to acquire the components needed to summon and bind an otherworldly shadow minion.",al={"what comes next","after halgars summons"}}},ang={["class:Warlock"]="This rite of passage bridges elementary training with true planar enslavement, bringing you under the scrutiny of Undercity's foremost master of the dark arts.",["race:Undead"]="Forsaken warlocks pursue shadow and fel with ruthless, uninhibited ambition, and Halgar's sanctum exemplifies their pragmatic disregard for living caution."},kw={"ageron kargal","carendin halgar","halgar's summons","magic quarter","temple of the damned","undercity","voidwalker","warlock"},rel={"npc:carendin-halgar","quest:1473","quest:1471","subzone:magic-quarter","zone:undercity"},m={start="Ageron Kargal",["end"]="Carendin Halgar",level="10",faction="Horde",id=1478},src={"Halgar's Summons"}}
E["quest:1803"] = {t="quest",n="Tome of the Cabal",z="undercity",s="This quest tasks Horde warlocks with reuniting the severed halves of the ancient Tome of the Cabal for Jorah Annison in the Undercity. Once kept within the kingdom of Lordaeron, the grimoire was torn apart and scattered across the world before being lost entirely. Tracking down its damp and tattered remnants requires braving hostile waters in the Eastern Kingdoms and deep centaur territory in Kalimdor.",h="This quest tasks Horde warlocks with reuniting the severed halves of the ancient Tome of the Cabal for Jorah...",sec={{t="A Divided Legacy",b="The Tome of the Cabal was once preserved within the library walls of the old kingdom of Lordaeron. At some point prior to the kingdom's downfall, the sinister grimoire was deliberately vandalized, stripped of nearly half its pages, and sundered into two pieces. The remaining formal text was slated for transit south to the dwarven halls of Ironforge, but fate intervened: the transport wrecked along the rocky coastline west of Southshore, leaving the pages to rot in the shallows under the watchful eyes of scavenging murlocs.",sp=0},{t="Scattered across Continents",b="The vandalized half of the tome wandered even farther afield. Snatched away from Lordaeron, it traveled all the way to southern Kalimdor, falling into the rough possession of the Galak centaur deep within Splithoof Hold in Thousand Needles. Recovering the complete text demands that a warlock scour the damp Hillsbrad shoreline for the Moldy Tome and infiltrate the dust and savagery of the centaur canyons for the Tattered Manuscript. Once both remnants are brought together before Jorah Annison, the legendary dark text is restored to a single, readable volume.",sp=1}},faq={{q="What is the Tome of the Cabal?",a="It is an arcane and demonic grimoire once held in the capital of Lordaeron. Containing advanced warlock rituals, it was defaced and split into two portions before being lost across two different continents.",al={"tome of the cabal lore","what is this book","tome of cabal"}},{q="Why is one part of the book near Southshore?",a="After the book was vandalized, the surviving bound portion was slated for transfer to the scholars of Ironforge. However, the vessel carrying it wrecked on the coast west of Southshore, leaving the grimoire stranded amidst the local murlocs.",al={"why southshore","moldy tome origin","coast west of southshore"}},{q="How did the pages end up with the centaur in Thousand Needles?",a="Roughly half the pages were torn out of the original tome in Lordaeron and smuggled away. Through trade, plunder, or wandering hands, that tattered manuscript eventually wound up deep inside Splithoof Hold, kept inside a chest by the Galak centaur.",al={"why centaur have it","thousand needles pages","splithoof hold book"}},{q="Who is Jorah Annison?",a="Jorah Annison is a Forsaken warlock practitioner based in the Magic Quarter of the Undercity. He guides rising Horde warlocks in recovering forgotten, forbidden lore to deepen their mastery over demonic forces.",al={"jorah annison lore","who is jorah"}},{q="Who vandalized the tome in the first place?",a="The exact identity of the culprit remains unknown. Jorah Annison himself laments the vandalism, questioning who could commit such a heinous act against a text of such profound occult power.",al={"who tore the book","who stole the pages","tome vandal"}},{q="What does Jorah do with the book once you bring both parts back?",a="Upon receiving both the Moldy Tome and the Tattered Manuscript, Jorah Annison assembles the pieces into a single volume and reads through its pages, preparing you for the next steps in your demonic rites.",al={"what happens after turn in","restored tome"}}},ang={["class:Warlock"]="Reclaiming the Tome of the Cabal is a rite of passage for intermediate practitioners, gathering lost Lordaeron arcana to expand your summoning repertoire.",["race:Undead"]="The tome was preserved in Lordaeron before the kingdom fell, making its recovery a reclamation of occult heritage from the Forsaken's past human lives.",["faction:Horde"]="Tracking down the manuscript sends you through the canyons of Thousand Needles, where Horde forces stationed at Freewind Post wage constant war against the native centaur."},kw={"galak","jorah annison","lordaeron","moldy tome","southshore","splithoof hold","tattered manuscript","thousand needles","tome of the cabal","warlock quest"},rel={"npc:jorah-annison","zone:undercity","subzone:southshore","subzone:splithoof-hold","zone:thousandneedles","topic:centaur","topic:murloc","quest:4841"},m={start="Jorah Annison",level="30",faction="Horde",id=1803},src={"Tome of the Cabal (Horde, 2)"}}
E["quest:1818"] = {t="quest",n="Speak with Dillinger",z="undercity",s="Speak with Dillinger is a Horde military directive issued in the Undercity. Austil de Mon dispatches able-bodied fighters to Deathguard Dillinger in Brill to take on a hazardous combat mission in service of Lady Sylvanas.",h="Speak with Dillinger is a Horde military directive issued in the Undercity.",sec={{t="A Summons to the Front",b="Within the subterranean halls of the Undercity, Austil de Mon keeps a watchful eye out for promising combatants willing to serve the Dark Lady. When the Deathguards stationed on the surface require capable hands, de Mon directs unproven adventurers out of the royal capital and into the field. Deathguard Dillinger, who oversees security on the western edges of Brill, has requested someone with martial competence for an urgent task.",sp=0},{t="Testing the Faithful",b="Brill sits squarely on the front line of Tirisfal Glades, where the Forsaken must constantly prove their martial dominance against hostile threats. Dillinger's post near the village graveyard puts him in prime position to manage local incursions. For the young warrior, reporting to Dillinger is more than a simple errand: it is a formal test of combat prowess and political loyalty to the newly forged Forsaken nation.",sp=0}},faq={{q="Who sends me on this mission?",a="Austil de Mon, located in the Undercity, identifies potential soldiers and sends them to assist Deathguard Dillinger.",al={"quest giver","austil de mon","who starts speak with dillinger"}},{q="Where can Deathguard Dillinger be found?",a="Deathguard Dillinger is stationed on the western edge of Brill in Tirisfal Glades, near the graveyard entrance.",al={"dillinger location","where is dillinger","find dillinger"}},{q="What is the purpose of reporting to Dillinger?",a="Dillinger requires an able-bodied champion for a combat mission to defend Brill and prove their allegiance to the Forsaken cause.",al={"why speak with dillinger","dillinger purpose"}},{q="What assignment does Dillinger have prepared?",a="Once you report to Deathguard Dillinger, he tasks you with hunting down a dangerous threat known as Ulag the Cleaver.",al={"what does dillinger want","next quest dillinger"},sp=1},{q="Do other Horde races receive this order?",a="Any Horde warrior who has earned the trust of Undercity officials can take the assignment, though it is primarily designed to assess recruits defending Tirisfal Glades.",al={"is this undead only","can orcs do this"}},{q="Why is this directive given in the Undercity instead of Brill?",a="Austil de Mon serves as an intake scout within the capital, funneling newly capable adventurers outward to frontier commanders who need immediate muscle.",al={"why undercity start","austil de mon role"}}},ang={["race:Undead"]="For newly liberated Forsaken, responding to Dillinger's call is a crucial step in proving your dedication to the Dark Lady and the defense of Tirisfal.",["class:Warrior"]="Deathguard commanders value sheer martial grit above all else, making this dispatch a direct test of your combat capabilities on the front line.",["faction:Horde"]="Answering defense calls for the Undercity cements cross-faction solidarity between Kalimdor's allies and the newly integrated Forsaken."},kw={"austil de mon","brill","deathguard dillinger","speak with dillinger","tirisfal glades","ulag the cleaver","undercity"},rel={"npc:deathguard-dillinger","npc:austil-de-mon","subzone:brill","topic:forsaken"},m={start="Austil de Mon",["end"]="Deathguard Dillinger",level="10",faction="Horde",id=1818},src={"Speak with Dillinger"}}
E["quest:1846"] = {t="quest",n="Dragonmaw Shinbones",z="undercity",s="Dragonmaw Shinbones is a Horde warrior quest directed by the armorer Velora Nitely in the Undercity. To craft the resilient Brutal Legguards, warriors are dispatched into the southern Wetlands to harvest exceptionally thick shinbones from the hostile Dragonmaw orcs.",h="Dragonmaw Shinbones is a Horde warrior quest directed by the armorer Velora Nitely in the Undercity.",sec={{t="A Gruesome Armature",b="Forging armor fit for a seasoned frontline warrior demands unorthodox materials. When tasked with fashioning Brutal Legguards, the Forsaken armorer Velora Nitely specifies a structural brace constructed from thick, resilient bone. Rather than utilizing common beasts, she directs aspiring warriors toward the Dragonmaw orcs of the Wetlands, whose dense skeletal builds provide the necessary resilience to withstand heavy blows in combat.",sp=0},{t="Testing the Marrow",b="Harvesting bone from the Dragonmaw is only half the ordeal. Velora instructs warriors to manually test every bone taken in the field; any specimen brittle enough to snap in bare hands is utterly useless for the forge. Warriors must scour the renegade encampments along the Wetlands' crags, breaking weak bones until eight genuinely sturdy examples survive the test of strength.",sp=0}},faq={{q="Why does Velora Nitely need orc shinbones specifically?",a="Velora requires dense, thick material to act as a supportive framework for the Brutal Legguards. She considers the Dragonmaw orcs of the Wetlands uniquely suited because their heavy, powerful skeletal frame provides far more structural rigidity than ordinary game or scavenged remains.",al={"why orc shinbones","why dragonmaw bones","velora bone armor"}},{q="Why are the Dragonmaw orcs fair game for Horde warriors?",a="The Dragonmaw clan remnants entrenched in the Wetlands are hostile renegades clinging to the dark legacy of the Second War. They hold no allegiance to Thrall's modern Horde, making them enemies of the state and fair quarry for Horde adventurers.",al={"are dragonmaw in the horde","why fight dragonmaw","dragonmaw horde standing"}},{q="Where are the Dragonmaw found for this task?",a="They reside in the Wetlands, south across the Thandol Span from the Arathi Highlands. Warriors typically hunt them around the mountainous bluffs of the Angerfang Encampment, situated southwest of the main northern highway.",al={"dragonmaw location","where to find dragonmaw shinbones","angerfang encampment location"}},{q="Why do so many of the bones break during the quest?",a="Velora requires only the densest marrow frames for armor forging. As part of her instructions, warriors test each bone by hand; any bone that snaps under raw physical force is discarded as too fragile to protect a warrior's legs in battle.",al={"broken shinbones","why do shinbones snap","sturdy bone test"}},{q="Who is Velora Nitely?",a="Velora Nitely is a Forsaken armorer operating within the Undercity. Gruff, morbidly dry, and prone to grim attempts at humor, she assists Horde warriors in fabricating specialized martial gear suited for battle-hardened veterans.",al={"velora nitely lore","who is velora","undercity armorer"}},{q="What armor piece is forged from these bones?",a="The collected bones form the internal framing for the Brutal Legguards, a durable set of plate-style greaves created for mid-level Horde warriors.",al={"shinbones reward","what are the shinbones for","brutal legguards craft"}}},ang={["class:Warrior"]="This trial tests both a warrior's physical fortitude in the field and their willingness to harvest morbid materials to craft superior armor.",["faction:Horde"]="Striking down the rogue Dragonmaw clan in Khaz Modan weakens a dangerous Old Horde remnant while empowering the champions of Thrall's new coalition.",["race:Orc"]="For orcs loyal to Orgrimmar, culling the unrepentant Dragonmaw is a stark reminder of their people's fel past and the violent cost of redemption.",["race:Undead"]="Velora Nitely's pragmatic use of humanoid remains exemplifies the Forsaken mentality of weaponizing every available resource, however macabre."},kw={"angerfang encampment","brutal legguards","dragonmaw","shinbones","thandol span","undercity","velora nitely","wetlands"},rel={"npc:velora-nitely","quest:1841","subzone:angerfang-encampment","zone:wetlands","subzone:thandol-span","zone:undercity","zone:arathi","subzone:hammerfall"},m={start="Velora Nitely",level="30",faction="Horde",id=1846},src={"Dragonmaw Shinbones"}}
E["quest:1881"] = {t="quest",n="Speak with Anastasia",z="undercity",s="Speak with Anastasia is an introductory summons directing promising Forsaken mages to Anastasia Hartwell in the Undercity. Dispatched by mage trainer Cain Firesong, the young caster is called to the Magic Quarter to undertake critical work for the magi of the Forsaken. This brief summons sets the stage for investigations out into the blighted lands of Tirisfal Glades.",h="Speak with Anastasia is an introductory summons directing promising Forsaken mages to Anastasia Hartwell in...",sec={{t="A Call to the Magic Quarter",b="As nascent spellcasters hone their early talents under the guidance of Cain Firesong, they are soon directed deeper into the capital. The mages of the Forsaken maintain a dedicated enclave within the Magic Quarter of the Undercity, organizing both arcane scholarship and strategic defensive efforts across Lordaeron. Cain Firesong acts as an evaluator, filtering out mere novices and sending those who demonstrate genuine talent directly to senior practitioners who require capable field hands.",sp=0},{t="Anastasia Hartwell's Ambition",b="Anastasia Hartwell stands among the prominent mage instructors within the Undercity. Rather than leaving promising students to study trivial incantations in safety, she wastes little time pressing them into service for the Forsaken's territorial and practical interests. Answering her summons is both a rite of passage for arcane practitioners and an induction into the shadowy, pragmatic magical pursuits that define the post-Scourge undead.",sp=0}},faq={{q="Who sends you to speak with Anastasia Hartwell?",a="Cain Firesong, a Forsaken mage trainer, sends you to her after recognizing that your arcane talents are developed enough to assist with more demanding matters within the capital.",al={"who gives speak with anastasia","quest giver speak with anastasia","cain firesong summons"}},{q="Where can Anastasia Hartwell be found?",a="Anastasia Hartwell resides in the Magic Quarter of the Undercity, where she coordinates and instructs practitioners of the arcane arts for the Forsaken.",al={"where is anastasia hartwell","anastasia hartwell location","find anastasia"}},{q="What is the purpose of this summons?",a="Anastasia is seeking a capable caster to perform practical tasks outside the city walls, starting with field assignments in Tirisfal Glades such as investigating the Balnir Farmstead.",al={"why does she want me","speak with anastasia purpose","what does anastasia need"}},{q="What quest follows Speak with Anastasia?",a="Reporting to Anastasia directly leads into 'The Balnir Farmstead', sending you back out into Tirisfal Glades to assist her associate Talen.",al={"what quest comes next","next quest after speak with anastasia","speak with anastasia followup"}},{q="Is this quest limited to certain classes?",a="Yes, this quest is specifically intended for mages of the Forsaken, serving as a class progression stepping stone as they reach early competence around circle ten.",al={"is this a mage only quest","who can do speak with anastasia","class requirement"}},{q="Why do the Forsaken mages maintain their own quarters in Undercity?",a="The Magic Quarter provides a dedicated sanctuary for Forsaken arcanists, warlocks, and researchers to study and cast away from the physical quarters, continuing their pre-Third War traditions within the underbelly of Lordaeron.",al={"why magic quarter","forsaken mages undercity"}}},ang={["class:Mage"]="This quest marks your transition from basic arcane training into active service for the mages of the Undercity.",["race:Undead"]="For Forsaken arcanists, answering Hartwell's call represents an opportunity to leverage Lordaeron's intellectual past against its present perils."},kw={"anastasia hartwell","balnir farmstead","cain firesong","mage quest","magic quarter","undercity"},rel={"npc:anastasia-hartwell","npc:cain-firesong","quest:1882","subzone:magic-quarter","zone:undercity","npc:talen","subzone:balnir-farmstead","topic:forsaken"},m={start="Cain Firesong",["end"]="Anastasia Hartwell",level="10",faction="Horde",id=1881},src={"Speak with Anastasia"}}
E["quest:1882"] = {t="quest",n="The Balnir Farmstead",z="undercity",s="\"The Balnir Farmstead\" is an early rite of passage for young Forsaken mages, directed by Anastasia Hartwell in the Undercity's Mage Quarter. Initiates are sent to eastern Tirisfal Glades to gather snapdragons from an abandoned farmstead sitting dangerously close to the border of the Plaguelands. The floral samples serve as barometers for the encroaching magical corruption spreading from the Scourge-blighted east.",h="\"The Balnir Farmstead\" is an early rite of passage for young Forsaken mages, directed by Anastasia Hartwell...",sec={{t="A Magical Barometer",b="While the Royal Apothecary Society frequently studies the effects of necromancy and decay, the mages of the Forsaken maintain their own watchful eye on the borderlands. Anastasia Hartwell tasks novice spellcasters with travelling to the Balnir Farmstead in eastern Tirisfal Glades. Snapdragons native to the farm's gardens are naturally sensitive to shifting magical currents, absorbing ambient energies from the soil and atmosphere. By examining these blooms, arcane scholars in the Undercity can measure whether the corruptive contagion of the Lich King's domain has seeped past the bulwark into Tirisfal proper.",sp=0},{t="The Eastern Border",b="The Balnir Farmstead sits near the fringes of the glades, uncomfortably near the blight-scarred wilderness of the Western Plaguelands. The Forsaken recognize that the Lich King's plague is an unruly and destructive power that actively rots the land itself. Although the Forsaken harness their own dark arts, uncontained Scourge corruption threatens their territorial borders and security. Anastasia intends to pass the gathered snapdragons along to the apothecaries, uniting arcane observation with alchemical investigation to defend Lordaeron's reclaimed heartland.",sp=0}},faq={{q="Why does Anastasia Hartwell want snapdragons specifically?",a="Balnir snapdragons possess a distinct natural sensitivity to ambient magical forces. Because they absorb energies directly from the earth and air, studying them allows Forsaken mages to determine whether the arcane and necromantic blight of the nearby Plaguelands is contaminating Tirisfal Glades.",al={"why snapdragons","balnir snapdragons purpose","what are snapdragons for"}},{q="Where is the Balnir Farmstead located?",a="The farmstead lies in eastern Tirisfal Glades, tucked toward the border where the glades approach the blighted frontier of the Western Plaguelands. The snapdragons grow within the overgrown plots and gardens surrounding the decrepit farm buildings.",al={"balnir farmstead location","where is balnir farm","find balnir farmstead"}},{q="Who is Anastasia Hartwell?",a="Anastasia Hartwell is a prominent Forsaken mage and trainer residing in the Mage Quarter of the Undercity. She guides newly emergent undead casters, instructing them on discipline, arcane balance, and the practical defense of their borders against rival powers.",al={"anastasia hartwell lore","who is anastasia"}},{q="Why do Forsaken mages care about stopping the plague?",a="Though the Forsaken experiment with their own plagues and blights, the Lich King's infectious scourge magic is considered an uncontrolled aberration. Left unchecked, the Scourge's corruption would swallow Tirisfal Glades whole and undermine the Forsaken's independence.",al={"why stop the plague","do forsaken hate the plague"}},{q="What happens to the flowers after you collect them?",a="Upon receiving the snapdragons, Anastasia prepares to hand them over to the Undercity's apothecaries. The alchemists and mages dissect the specimens together to assess how deeply the soil and flora have been tainted by the Scourge.",al={"what does anastasia do with the flowers","who gets the snapdragons"}},{q="Is this quest restricted to mages?",a="Yes. This task serves as a dedicated class quest offered exclusively to young Forsaken mages who have advanced beyond their initial lessons in Deathknell and arrived in the capital to prove their grasp of arcane theory.",al={"is balnir farmstead mage only","mage class quest"}}},ang={["class:Mage"]="This early trial teaches novice mages that their study of the arcane is essential for monitoring and defending against foreign magical corruption.",["race:Undead"]="For the Forsaken, safeguarding the borders of Tirisfal Glades against the encroaching Scourge is a matter of immediate survival and sovereignty.",["profession:Herbalism"]="The Balnir snapdragon provides an example of how botanical specimens can serve as direct reservoirs and indicators of magical pollution."},kw={"anastasia","balnir","farmstead","hartwell","mage","plaguelands","snapdragons","tirisfal","undercity"},rel={"npc:anastasia-hartwell","quest:1881","subzone:balnir-farmstead","subzone:mage-quarter","zone:undercity","zone:tirisfal","topic:forsaken","topic:lich-king"},m={start="Anastasia Hartwell",level="10",faction="Horde",id=1882},src={"The Balnir Farmstead"}}
E["quest:1885"] = {t="quest",n="Mennet Carkad",z="undercity",s="Mennet Carkad is an introductory rogue quest in the Undercity that brings promising operatives into the fold of the Deathstalkers. Directed by Marion Call, aspiring assassins are summoned to report directly to Mennet Carkad deep within the Rogues' Quarter.",h="Mennet Carkad is an introductory rogue quest in the Undercity that brings promising operatives into the fold...",sec={{t="A Summons from the Shadows",b="Within the dark corridors of the Undercity, word travels quietly among the Forsaken's covert operatives. When a scout or assassin catches the eye of the higher leadership, an invitation is issued. Marion Call passes down word that Mennet Carkad, a prominent figure among the rogue handlers, has taken personal notice. Given the lethal reputation of the Forsaken intelligence apparatus, ignoring such a directive is not considered a viable option.",sp=0},{t="Joining the Deathstalkers",b="Mennet Carkad waits in the shadowy alcoves of the Rogues' Quarter, watching over recruits and evaluating their readiness. Those who heed his call are not simply joining an ordinary guild of thieves; they are being tested for entry into the Deathstalkers, the dreaded espionage and assassination arm of the Forsaken. Swift obedience is merely the first baseline test for anyone seeking to serve the Dark Lady from the shadows.",sp=0}},faq={{q="Who is Mennet Carkad?",a="Mennet Carkad is a rogue trainer and Deathstalker handler operating within the Rogues' Quarter of the Undercity. He oversees promising covert agents and assigns critical missions on behalf of the Forsaken leadership.",al={"mennet carkad lore","who is carkad"}},{q="What happens if someone ignores Mennet Carkad's summons?",a="Marion Call warns that you would not want to know the fate of those who ignored Carkad's call in the past. In the ruthless hierarchy of the Forsaken, refusing or ignoring orders from intelligence commanders typically results in swift, fatal elimination.",al={"ignoring carkad","what happens if you ignore summons"}},{q="Who are the Deathstalkers?",a="The Deathstalkers are the elite order of rogues, spies, and assassins serving the Forsaken. Operating from the shadows of the Undercity, they eliminate high-value targets, gather intelligence, and secure Lordaeron from enemies like the Scarlet Crusade and the Scourge.",al={"deathstalker lore","what are the deathstalkers"}},{q="Where can I find Mennet Carkad?",a="Mennet Carkad is located in the Rogues' Quarter of the Undercity, typically surrounded by other covert operatives, trainers, and shadowcraft supplies.",al={"carkad location","where is mennet carkad"}},{q="Who gives the quest to seek out Mennet Carkad?",a="The task is assigned by Marion Call in the Rogues' Quarter, who notices your burgeoning skills and warns you that Carkad expects prompt obedience.",al={"who starts this quest","marion call quest"}},{q="What comes after reporting to Mennet Carkad?",a="Reporting to Mennet Carkad immediately leads into direct service for the Deathstalkers, starting with tasks designed to prove your cunning and loyalty to the Forsaken cause.",al={"next quest after carkad","what does carkad want"}}},ang={["class:Rogue"]="This summons marks your transition from an unproven cutpurse into a recognized asset of the Deathstalkers, the Forsaken's elite shadow network.",["race:Undead"]="The Deathstalkers are essential to the survival of the Forsaken, hunting Scarlet zealots and Scourge remnants while protecting Queen Sylvanas from hidden threats."},kw={"assassin","deathstalkers","forsaken rogue","marion call","mennet carkad","rogues' quarter","undercity"},rel={"quest:1886","subzone:rogues-quarter","zone:undercity"},m={start="Marion Call",["end"]="Mennet Carkad",level="10",faction="Horde",id=1885},src={"Mennet Carkad (quest)"}}
E["quest:1886"] = {t="quest",n="The Deathstalkers",z="undercity",s="This task marks the trial for initiates seeking entry into the Deathstalkers, the covert and lethal arm answering to Lord Varimathras in the Undercity. Assigned by Mennet Carkad in the Rogues' Quarter, the mission demands ruthless initiative to intercept a traveling messenger. Completing it opens the door to deeper clandestine schemes within the Forsaken realm.",h="This task marks the trial for initiates seeking entry into the Deathstalkers, the covert and lethal arm...",sec={{t="A Test in the Shadows",b="The Deathstalkers do not admit just anyone into their ranks. Operating directly under dreadlord Varimathras, this secretive order acts as both the secret police and elite assassination corps of the Forsaken. To earn their notice, a hopeful agent must demonstrate cunning, discretion, and an unhesitating willingness to eliminate targets. In the shadowy corners of the Rogues' Quarter, handler Mennet Carkad sets an initiation trial designed to weed out the weak or overscrupulous.",sp=0},{t="The Interception",b="The initiate's target is Astor Hadren, a courier traveling the road between the Undercity and Silverpine Forest. Carkad offers no tactical advice, leaving the method of securing Hadren's personal introduction entirely up to the operative. The task hinges on intercepting Astor, seizing his credentials, and ensuring the Deathstalkers can masquerade their recruit as the expected envoy to an operative named Andron.",sp=1}},faq={{q="Who are the Deathstalkers?",a="The Deathstalkers are the elite stealth and assassination branch of the Forsaken. Headquartered in the Undercity's Rogues' Quarter, they handle espionage, covert executions, and information gathering, reporting directly to Lord Varimathras.",al={"deathstalkers lore","what are deathstalkers","undead rogues"}},{q="Who is Mennet Carkad?",a="Mennet Carkad is a Deathstalker handler operating out of the Rogues' Quarter in the Undercity. He oversees early trials and tests recruits hoping to join their covert ranks.",al={"mennet carkad role","who gives quest"}},{q="Why does Mennet need Astor Hadren's letter?",a="Astor Hadren is a courier traveling between Silverpine Forest and the Undercity. Securing his letter of introduction allows the Deathstalkers to substitute their new operative in Hadren's place to deceive an associate named Andron.",al={"astor hadren letter","why intercept messenger","astor letter of introduction"}},{q="Where does Astor Hadren travel?",a="Astor Hadren journeys along the path connecting the Undercity and Silverpine Forest, carrying correspondence between regions on behalf of his contacts.",al={"astor hadren route","astor hadren location","where is astor"}},{q="Who is Lord Varimathras?",a="Varimathras is a Nathrezim dreadlord who allied with Queen Sylvanas Windrunner to preserve his own existence. He oversees the Undercity's security, defense, and rogue operations from the Royal Quarter.",al={"varimathras role","dreadlord in undercity"}},{q="What happens after this trial?",a="Passing the trial proves an operative's competence, leading into a covert impersonation assignment to deliver Astor's papers and infiltrate Andron's dealings.",al={"what comes next","deathstalkers questline continuation"},sp=1}},ang={["class:Rogue"]="For Forsaken rogues, joining the Deathstalkers represents the highest echelon of state service, transitioning streetwise scoundrels into sworn instruments of Varimathras and the Dark Lady.",["race:Undead"]="The Deathstalkers represent the iron grip of internal security in Lordaeron, keeping a watchful, paranoid eye on both external foes and potential traitors within the Forsaken.",["faction:Horde"]="The Deathstalkers operate in deep secrecy, ensuring that the Forsaken maintain vital intelligence networks while keeping the Horde's southern allies largely unaware of their shadier domestic affairs."},kw={"astor hadren","deathstalkers","mennet carkad","rogues' quarter","silverpine","undercity","varimathras"},rel={"npc:varimathras","subzone:rogues-quarter","zone:undercity","quest:1885"},m={start="Mennet Carkad",level="13",faction="Horde",id=1886},src={"The Deathstalkers"}}
E["quest:1898"] = {t="quest",n="The Deathstalkers",z="undercity",s="This covert assignment sends an undercover operative into the Undercity's shadowy underbelly to interrogate an unwitting conspirator. Acting under orders handed down from Lord Varimathras, you pose as an expected messenger to uncover treason within the Forsaken's own capital.",h="This covert assignment sends an undercover operative into the Undercity's shadowy underbelly to interrogate...",sec={{t="A Web of Deceit",b="The Deathstalkers do not merely eliminate external threats to the Forsaken; they maintain a ruthless vigil over their own citizens. Acting on suspicions harbored by Lord Varimathras, Deathstalker Mennet Carkad sets an infiltration plan in motion. Armed with a forged or acquired letter of introduction belonging to Astor Hadren, you are tasked with slipping past the suspicions of a local merchant named Andron Gant.",sp=0},{t="The Shop Near the Apothecarium",b="Andron Gant operates out of a shop near the vile fumes and bubbling cauldrons of the Apothecarium. Mennet regards the shopkeeper as foolish and unobservant—lacking the wit to see through an impostor. Presenting the letter establishes your cover as a courier, prompting Gant to eagerly lower his guard and volunteer details about his dealings with an unidentified third party.",sp=1}},faq={{q="Who is Andron Gant?",a="Andron Gant is a shopkeeper in the Undercity situated near the Apothecarium. He has drawn the scrutiny of the Deathstalkers and Lord Varimathras for allegedly funneling intelligence and assistance to an unknown external faction.",al={"andron gant","who is gant","where is andron gant"}},{q="Why is Lord Varimathras interested in this merchant?",a="Varimathras suspects Gant of collaborating with an organization outside the Forsaken. To safeguard the city and weed out potential subversion, the dreadlord demands concrete proof of Gant's contacts and intentions.",al={"why varimathras cares","varimathras andron gant","why spy on andron"}},{q="How does the player deceive Andron Gant?",a="Mennet Carkad equips you with Astor's Letter of Introduction. Because Gant was expecting a courier and is deemed not particularly sharp by the Deathstalkers, showing him the credentials is all it takes to gain his confidence.",al={"astors letter","how to trick andron gant","messenger disguise"}},{q="What group are the Deathstalkers?",a="The Deathstalkers are the elite rogue order and secret intelligence agency of the Forsaken. Operating from the shadows under Queen Sylvanas and Lord Varimathras, they root out sedition, sabotage enemies, and eliminate internal threats.",al={"deathstalkers lore","who are deathstalkers","undercity rogues"}},{q="Where can Andron Gant be found?",a="He resides in his shop close to the entrance of the Apothecarium quarter in the Undercity, conducting business under the watchful eyes of the Royal Apothecary Society and the Deathstalkers.",al={"andron gant location","where is gant shop"}},{q="What happens after Gant accepts the letter?",a="Gant accepts the letter without suspicion and assumes you are merely an unburdened messenger. He immediately hints at ongoing cooperation with mutual acquaintances, setting the stage for extracting further proof of his betrayal.",al={"what does gant do","gant reaction"},sp=1}},ang={["class:Rogue"]="Infiltrating a spy ring using a dead man's identity to bait a careless conspirator is tradecraft straight from the Deathstalkers' textbook.",["race:Undead"]="For the Forsaken, vigilance is survival. Any citizen discovered aiding outside factions risks immediate purging by the dark lady's secret police.",["faction:Horde"]="Beneath the surface of the Undercity lies a nest of political intrigue, proving that even within Horde borders, trust is a rare commodity."},kw={"andron gant","apothecarium","astor hadren","deathstalkers","espionage","forsaken","mennet carkad","undercity","varimathras"},rel={"quest:1886","npc:andron-gant","npc:varimathras","quest:1885","subzone:apothecarium","zone:undercity"},m={start="Mennet Carkad",["end"]="Andron Gant",level="13",faction="Horde",id=1898},src={"The Deathstalkers (2)"}}
E["quest:1899"] = {t="quest",n="The Deathstalkers",z="undercity",s="This errand serves as a vital step in formalizing an arrangement between the informant Andron Gant and the Deathstalkers of the Undercity. After securing his cooperation, an operative delivers Gant's comprehensive ledger directly into the hands of Mennet Carkad in the Rogues' Quarter. The exchange marks the transition from simple inquiries to deeper, more covert operations on behalf of the Forsaken state.",h="This errand serves as a vital step in formalizing an arrangement between the informant Andron Gant and the...",sec={{t="A Courier in the Shadows",b="The Deathstalkers do not rely solely on brute force or shadow magic; their operations depend heavily on mundane ledgers, recorded names, and meticulous surveillance. Andron Gant, operating out of the Undercity, agrees to hand over a personal ledger crammed with intelligence that the assassins crave. Rather than dealing directly with the lethal core of the organization, Gant places his faith in an intermediary courier, demonstrating the caution typical of anyone bartering information among the dead.",sp=0},{t="Intelligence in the Rogues' Quarter",b="When delivered to Mennet Carkad in the Rogues' Quarter, the ledger proves far more revealing than the Deathstalkers anticipated. Instead of cursory notes, Gant's writings yield actionable leads that allow Carkad to widen the scope of their investigations. In an environment as paranoid and fractured as the Forsaken realm, having verified paper trails is essential to ferreting out internal subversion and monitoring external threats before they strike the capital.",sp=1}},faq={{q="What is in Andron's Ledger?",a="The ledger contains sensitive information and records gathered by Andron Gant. While the exact contents are not read aloud, Mennet Carkad notes that it contains significantly more detail and valuable intelligence than the Deathstalkers initially expected him to provide.",al={"andron ledger contents","what does the ledger say","deathstalker ledger"}},{q="Who are the Deathstalkers?",a="The Deathstalkers are the premier covert organization and assassin guild of the Forsaken. Headquartered in the Rogues' Quarter of the Undercity, they operate as Lady Sylvanas Windrunner's eyes, ears, and hidden daggers, handling espionage, intelligence, and targeted assassinations across Lordaeron.",al={"deathstalker lore","who are deathstalkers","undercity rogues"}},{q="Why does Gant want the same courier used in the future?",a="In the murky, distrustful atmosphere of the Undercity, finding an operative who can run sensitive documents without stealing or tampering with them is rare. Gant explicitly requests that future business be handled through the same runner to minimize risks and preserve his established working arrangement.",al={"why does gant like you","andron gant trust","gant courier"}},{q="Who is Mennet Carkad?",a="Mennet Carkad is a seasoned operative of the Deathstalkers stationed in the Rogues' Quarter. He coordinates local agents, gathers field intelligence from informants like Andron Gant, and directs covert assignments throughout the capital and surrounding territories.",al={"mennet carkad lore","who is carkad"}},{q="Where is the Rogues' Quarter located?",a="The Rogues' Quarter is the southern district of the Undercity. It serves as the primary base for Forsaken stealth operatives, thieves, and assassins, providing training grounds and dark alcoves far removed from the public plazas of the upper ruins.",al={"rogues quarter location","where is rogues quarter","undercity rogues quarter"}},{q="Why do the Forsaken need an internal intelligence agency?",a="Surrounded on all sides by the Scourge, the Scarlet Crusade, and wary Alliance remnants, the young Forsaken nation faces constant threats of infiltration and rebellion. The Deathstalkers root out subversion within Lordaeron's borders to ensure the fledgling regime survives.",al={"why deathstalkers exist","forsaken spies","undercity intelligence"}}},ang={["class:Rogue"]="For an aspiring rogue in the Undercity, handling sensitive courier runs for Mennet Carkad is a fundamental test of discretion, proving that an operative can manage covert assets without attracting unnecessary attention.",["race:Undead"]="Internal security in the Undercity is absolute survival; assisting the Deathstalkers directly strengthens the Dark Lady's grip over the capital against both living infiltrators and rival undead."},kw={"andron gant","assassins","deathstalkers","espionage","ledger","mennet carkad","rogues' quarter","undercity"},rel={"npc:andron-gant","subzone:rogues-quarter","zone:undercity"},m={start="Andron Gant",["end"]="Mennet Carkad",level="13",faction="Horde",id=1899},src={"The Deathstalkers (3)"}}
E["quest:1960"] = {t="quest",n="Investigate the Alchemist Shop",z="undercity",s="Investigate the Alchemist Shop is an Undercity quest for Horde mages tasked with resolving an arcane anomaly in the Apothecarium. Guided by Anastasia Hartwell, practitioners track and capture invisible creatures made of pure magical energy running loose inside Algernon's shop.",h="Investigate the Alchemist Shop is an Undercity quest for Horde mages tasked with resolving an arcane anomaly...",sec={{t="A Disturbance in the Apothecarium",b="The Undercity is no stranger to unnatural phenomena, but the Apothecarium recently developed a problem of purely arcane origin. Unseen magical entities were detected wandering Algernon's alchemy shop, passing silently among bubbling cauldrons and toxic reagents. Recognizing an unnatural breach in the flow of magic, the Undercity's mage instructor, Anastasia Hartwell, directs promising arcane initiates to investigate and contain the entities before catastrophic damage occurs.",sp=0},{t="Manifestation and Containment",b="Because the entities are invisible and composed entirely of raw arcane force, ordinary tracking methods are useless. Anastasia equips her students with a specialized Cantation of Manifestation to strip away the entities' invisibility, alongside sturdy containment coffers. Once revealed, the volatile rift spawns must be battered down and sealed safely inside the coffers before they can unravel further or harm the alchemists at work.",sp=0},{t="Accident or Arcane Assault?",b="Upon securing the specimens, Anastasia's concern shifts to their origin. A spontaneous rift in the ambient flow of magic is troubling enough, but an intentional breach would imply an active, coordinated magical assault against the Forsaken capital. The captured creatures are turned over for study to determine whether the Apothecarium merely suffered an arcane accident or sits on the frontline of a targeted threat.",sp=1}},faq={{q="Who gives this quest and where do I find them?",a="The quest is offered by Anastasia Hartwell, the mage trainer stationed in the Magic Quarter of the Undercity.",al={"quest giver","where to start","anastasia location"}},{q="Where is the disturbance located?",a="The disturbance is centered around Algernon's alchemy shop, located down within the Apothecarium district of the Undercity.",al={"where do i go","alchemist shop location","where is algernon"}},{q="What are the creatures wandering the shop?",a="They are rift spawns, invisible beings made entirely of concentrated magical energy that appeared through an anomaly in the local flow of magic.",al={"what are the monsters","invisible creatures","rift spawns"}},{q="How do you capture the creatures?",a="You must recite the Cantation of Manifestation in the shop to reveal the rift spawns, weaken them with spells, and then deploy a containment coffer to trap them inside.",al={"how to catch them","using the coffer","how to complete"}},{q="Why does Anastasia want these creatures captured alive?",a="Anastasia and the Undercity's scholars need live specimens to determine whether the tear in magic was a natural, random rift or an intentional attack against the city by an outside magical force.",al={"why capture them","containment coffers purpose","why study them"}},{q="Can classes other than mages do this quest?",a="No, this quest is specifically part of the early training lineage restricted entirely to Horde mages.",al={"mage only","who can take this quest"}}},ang={["class:Mage"]="This task tests an apprentice's mastery over pure arcane forces, demanding the use of specialized manifestation cantations and containment vessels rather than mere destructive force.",["race:Undead"]="While Forsaken apothecaries focus heavily on alchemy and plaguecraft, this mission highlights the vigilance of the Undercity's arcane scholars in guarding their city from magical infiltration."},kw={"algernon","anastasia hartwell","apothecarium","cantation of manifestation","containment coffer","magic quarter","rift spawn","undercity"},rel={"npc:anastasia-hartwell","subzone:apothecarium","zone:undercity","quest:1959"},m={start="Anastasia Hartwell",["end"]="Anastasia Hartwell",level="16",faction="Horde",id=1960},src={"Investigate the Alchemist Shop"}}
E["quest:1961"] = {t="quest",n="Gathering Materials",z="undercity",s="Gathering Materials is a rite of passage for aspiring Horde mages training in the Undercity. Assigned by Anastasia Hartwell, the task sends apprentices into Silverpine Forest to claim arcane gems from the wizards of Dalaran, assembling the components needed to weave their first true mage's robes.",h="Gathering Materials is a rite of passage for aspiring Horde mages training in the Undercity.",sec={{t="A Rite of Arcane Standing",b="Within the arcane cloisters of the Magic Quarter, novice mages must prove their mastery over more than just raw incantations. To earn their first true robes—a formal mantle marking their station and personal worth—initiates are directed by Anastasia Hartwell to harvest the raw components required for enchanted weave: a bolt of simple linen and a set of potent Dalaran mana gems.",sp=0},{t="Pragmatism of the Forsaken",b="The mana gems cannot simply be purchased or manifested; they must be torn from Dalaran mages stationed across Silverpine Forest, particularly near Ambermill. Anastasia Hartwell remarks with cold detachment that while Dalaran's arcane philosophies mirror their own, sentimental hesitation has no place in the Undercity. In the eyes of the Forsaken, if those living wizards lack the strength to defend their relics, they forfeit both their treasures and their lives.",sp=0},{t="The Tailor of the Magic Quarter",b="Once gathered, the cloth and gems are delivered to Josef Gregorian, a tailor residing in the Magic Quarter. While Gregorian readily admits he lacks the magical talent to gauge the pristine quality of Dalaran's enchanted stones, he possesses the rare artisan skill needed to weave their raw power directly into the fabric of the robes.",sp=0}},faq={{q="What is the purpose of Gathering Materials?",a="The quest serves as an initiation for Horde mages. Completing it provides the tailor Josef Gregorian with the necessary components—linen and mana gems—to craft the initiate's first formal enchanted robes.",al={"why do gathering materials","gathering materials quest purpose","mage robe quest undercity"}},{q="Why does Anastasia Hartwell send you after Dalaran mages?",a="Dalaran wizards stationed in Silverpine Forest carry refined mana gems capable of channeling strong magical currents. Hartwell views these living mages pragmatically: despite shared intellectual roots, weakness in the field means their lives and resources are forfeit to the Forsaken.",al={"why kill dalaran mages","dalaran mana gems lore","why silverpine mages"}},{q="Where are the Dalaran wizards located?",a="They can be encountered in Silverpine Forest, occupying outposts and grounds southeast of the Sepulcher, centered around the settlement of Ambermill.",al={"where to find dalaran mana gems","silverpine mages location","ambermill mages"}},{q="Who is Josef Gregorian?",a="Josef Gregorian is an Undead tailor working out of the Magic Quarter of the Undercity. Though he is an artisan rather than an arcane spellcaster, he specializes in stitching enchanted garments like spellfire robes.",al={"josef gregorian undercity","who is the tailor in magic quarter","gregorian tailor"}},{q="What robes are crafted from these materials?",a="Josef Gregorian uses the linen and Dalaran mana gems to stitch Spellfire Robes, a classic garment marking an apprentice's transition into an established mage.",al={"what robe do you get","spellfire robes reward","gathering materials reward robe"}},{q="Why does Anastasia find killing Dalaran mages somewhat distasteful?",a="Many Forsaken spellcasters, including Hartwell herself, were trained in Dalaran's traditions in life and share similar intellectual and magical philosophies. Despite this kinship, survival and necessity override sentiment.",al={"hartwell dalaran feelings","forsaken mages vs dalaran","anastasia hartwell lore"}}},ang={["class:Mage"]="This quest represents a pivotal milestone for Horde mages, marking their graduation from simple apprentice attire into tailored robes woven with captured arcane power.",["race:Undead"]="The mission illustrates the Forsaken's ruthless worldview: former kinship with Dalaran's sorcerers yields no mercy if those living wizards prove too weak to hold Silverpine.",["profession:Tailoring"]="The process highlights how mundane linen cloth can be bound with potent mana gems to create enduring enchanted garments."},kw={"ambermill","anastasia hartwell","dalaran mana gem","gathering materials","josef gregorian","linen cloth","magic quarter","spellfire robes","undercity"},rel={"quest:1962","npc:anastasia-hartwell","npc:josef-gregorian","subzone:magic-quarter","subzone:ambermill","subzone:dalaran","subzone:sepulcher","quest:1960"},m={start="Anastasia Hartwell",["end"]="Josef Gregorian",level="15",faction="Horde",id=1961},src={"Gathering Materials (Horde)"}}
E["quest:1962"] = {t="quest",n="Spellfire Robes",z="undercity",s="Spellfire Robes is the culminating rite in Josef Gregorian's training of young Horde mages in the Undercity. After gathering rare components from across the realm, the apprentice is rewarded with custom enchanted vestments that signify their growing mastery over the arcane.",h="Spellfire Robes is the culminating rite in Josef Gregorian's training of young Horde mages in the Undercity.",sec={{t="A Mage's Vestment",b="For apprentices mastering the arcane arts in Lordaeron, standard cloaks and common garments do little to channel or insulate against raw eldritch forces. Josef Gregorian, an instructor dwelling in the Magic Quarter of the Undercity, oversees promising Horde spellcasters as they gather specialized materials needed to weave genuine magical garb. The final stitching of the Spellfire Robes represents an apprentice's transition beyond basic incantations into an established practitioner of arcane and fire arts.",sp=0},{t="Woven Power",b="Crafting garments capable of safely focusing high-intensity magic is an exacting task. Rather than mere tailoring, the creation of robes such as these requires specific alchemical and arcane components secured through dangerous trials. Once these supplies are gathered and presented in Gregorian's sanctum, the tailor weaves them together on the spot, bestowing a tangible mark of status and protection upon the aspiring mage.",sp=0}},faq={{q="What is the purpose of the Spellfire Robes quest?",a="It serves as the final step in an early class rite for Horde mages, rewarding them with specially enchanted robes after they have gathered exotic tailoring components for their trainer, Josef Gregorian.",al={"spellfire robes purpose","what do spellfire robes do","why do this quest"}},{q="Who is Josef Gregorian?",a="Josef Gregorian is a Forsaken mage trainer located in the Magic Quarter of the Undercity. He guides newly minted spellcasters through practical tasks to secure arcane reagents and tailor their first proper class garments.",al={"who is josef","who makes the robe","josef gregorian undercity"}},{q="Where does this quest take place?",a="The entire interaction takes place within the Magic Quarter of the Undercity, directly at Josef Gregorian's circle of arcane study.",al={"spellfire robes location","where to turn in spellfire robes"}},{q="Why don't you have to leave to do another task for this quest?",a="All the labor was completed in the preceding assignment, Gathering Materials. Once you hand those reagents to Josef, he simply takes a moment to weave the garment and immediately hands over the finished robes.",al={"why is it instant","how to complete spellfire robes","auto complete robe"}},{q="Can classes other than Mages obtain these robes?",a="No. The entire quest chain and the resulting enchanted vestments are exclusive to mages allied with the Horde.",al={"is this mage only","can warlock get this","who can do spellfire robes"}},{q="What materials were required to make these robes?",a="The robe is constructed from the rare supplies collected during the previous task, which include thread, linen, and specialized magical reagents sourced from distant lands to properly hold an arcane charge.",al={"what goes into the robe","robe ingredients","gathering materials turn in"}}},ang={["class:Mage"]="Obtaining these robes is an early rite of passage for Horde practitioners, providing tailored attire capable of handling volatile fire and arcane energies.",["race:Undead"]="Forsaken spellcasters in the Undercity preserve Dalaran-style arcane discipline, combining old magical traditions with their new existence in Lordaeron's ruins.",["profession:Tailoring"]="The quest demonstrates how mundane cloth is augmented with exotic reagents to withstand and enhance powerful magical currents."},kw={"arcane robes","gathering materials","josef gregorian","mage quest","magic quarter","spellfire robes","undercity"},rel={"quest:1961","npc:josef-gregorian"},m={start="Josef Gregorian",level="15",faction="Horde",id=1962},src={"Spellfire Robes"}}
E["quest:1978"] = {t="quest",n="The Deathstalkers",z="undercity",s="This errand marks the formal induction of a capable operative into the ranks of the Deathstalkers, the Forsaken order of assassins and spies. Tasked with delivering Andron's Ledger directly to the dreadlord Varimathras, the courier brings proof of the Syndicate's covert activities to the highest tier of Undercity leadership.",h="This errand marks the formal induction of a capable operative into the ranks of the Deathstalkers, the...",sec={{t="Induction into the Shadows",b="After unearthing incriminating records from Andron Gant, Mennet Carkad officially welcomes the operative into the Deathstalkers. The organization serves as Lady Sylvanas's eyes, ears, and daggers throughout Lordaeron, relying on intelligence networks, ruthless efficiency, and stealth to eliminate threats before they surface. Gaining formal recognition within the order is a major milestone for any aspiring rogue or scout in the Undercity.",sp=0},{t="The Syndicate Connection",b="The prize of this covert investigation is Andron's Ledger, which exposes illicit ties between local agents and the Syndicate. Once the noble aristocracy of the fallen human kingdom of Alterac, the Syndicate turned to banditry and subversion after their realm collapsed in the Second War. Carkad expresses surprise and disdain at how far the fallen lords of Alterac have descended, stooping to petty conspiracies to claw back power.",sp=1},{t="Audience with the Dreadlord",b="Because of the sensitive nature of the intelligence, the ledger is delivered directly to Varimathras in the Royal Quarter of the Undercity. The nathrezim commander oversees Forsaken tactical intelligence under Sylvanas Windrunner. Pleased with the Deathstalkers' initiative, Varimathras welcomes the operative's demonstrated capability, noting that his intelligence division can always make use of someone who delivers results.",sp=0}},faq={{q="What are the Deathstalkers?",a="The Deathstalkers are the premier espionage, scouting, and assassination order of the Forsaken. Headquartered in the Rogues' Quarter of the Undercity, they operate across Lordaeron to neutralize political rivals, infiltrate hostile factions, and protect the Forsaken realm from external and internal subversion.",al={"who are the deathstalkers","deathstalker lore","forsaken assassins"}},{q="Why is the Syndicate involved?",a="The captured ledger reveals secret connections to the Syndicate, the displaced aristocracy of Alterac who turned to organized banditry. The Forsaken keep careful watch over Alterac remnants operating in their territory, as Syndicate agents continuously seek opportunities to reclaim lost land and plunder resources across northern Lordaeron.",al={"why syndicate","alterac connection","syndicate ledger"}},{q="Why report directly to Varimathras?",a="Varimathras serves as Queen Sylvanas's tactical advisor and oversees Undercity security and intelligence operations. Significant discoveries concerning foreign conspiracies—such as the Syndicate's covert operations—require review at the highest executive level to coordinate broader military and diplomatic countermeasures.",al={"why varimathras","who is varimathras","dreadlord role"}},{q="Who was Mennet Carkad?",a="Mennet Carkad is a senior handler and contact for the Deathstalkers operating in the Undercity. He oversees field agents, evaluates new recruits, and sifts through gathered intelligence before routing critical findings up the chain of command.",al={"mennet carkad role","quest giver carkad"}},{q="Where does this audience take place?",a="The audience takes place in the Hall of the Dark Lady, located in the Royal Quarter deep within the Undercity. Varimathras stands beside Queen Sylvanas Windrunner at the heart of the Forsaken seat of power.",al={"where is varimathras","hall of the dark lady location"}},{q="What happens after joining the Deathstalkers?",a="With your credentials established and your reliability proven to both Mennet Carkad and Varimathras, you are recognized as a trusted field operative for the Forsaken, setting the stage for future reconnaissance and elimination contracts across the contested lands of Lordaeron.",al={"deathstalker questline continuation","what next"}}},ang={["race:Undead"]="For the Forsaken, induction into the Deathstalkers is a direct pledge to safeguard the fragile sovereignty of Lordaeron from human survivors and lurking traitors.",["class:Rogue"]="This induction represents official entry into the Forsaken's dedicated rogue cadre, elevating simple cutpurses into state-sponsored intelligence operatives.",["faction:Horde"]="While internal to Forsaken security, monitoring the human remnants of Alterac protects the northern Horde territories from subversive sabotage."},kw={"alterac","andron's ledger","deathstalkers","hall of the dark lady","mennet carkad","syndicate","undercity","varimathras"},rel={"quest:1886","quest:1885","npc:varimathras","zone:undercity","topic:syndicate","topic:alterac-kingdom"},m={start="Mennet Carkad",["end"]="Varimathras",level="13",faction="Horde",id=1978},src={"The Deathstalkers (4)"}}
E["quest:1998"] = {t="quest",n="Fenwick Thatros",z="undercity",s="Mennet Carkad assigns promising rogues in the Undercity to hunt down Fenwick Thatros on orders directly from Lord Varimathras. Thatros is suspected of organizing independent undead forces along the shores of Silverpine Forest. Eliminating him proves an operative's mettle to the Deathstalkers, opening the way for more sophisticated trade training.",h="Mennet Carkad assigns promising rogues in the Undercity to hunt down Fenwick Thatros on orders directly from...",sec={{t="A Command from the Dreadlord",b="Within the dark corridors of the Rogues' Quarter, Mennet Carkad handles internal contracts and training for the Deathstalkers—the Forsaken's secretive intelligence wing. When Lord Varimathras sends down a priority target, it is not an assignment handed to novice recruits lightly. Fenwick Thatros has drawn the dreadlord's attention by establishing a foothold among the rogue undead in Silverpine Forest. Left unchecked, independent undead leadership could jeopardize Forsaken consolidation across Lordaeron's old holdings.",sp=0},{t="The Decrepit Dock on Lordamere",b="According to Deathstalker reconnaissance, Thatros does not hide in deep fortresses or crypts. Instead, scouts placed him near a decrepit dock along the waters of Lake Lordamere in Silverpine Forest. Striking him down there requires traversing contested wilderness dominated by feral beasts, the Rot Hide gnolls, and remnants of the Scourge. Bringing back his severed head provides the tangible proof Varimathras demands before inducting an operative into deeper covert operations.",sp=0}},faq={{q="Who is Fenwick Thatros?",a="Fenwick Thatros is an undead leader operating along the edges of Lake Lordamere in Silverpine Forest. Unlike the Forsaken who serve Lady Sylvanas, Thatros commands pockets of undead that remain unaligned or hostile to the Undercity, leading Lord Varimathras to single him out for execution.",al={"fenwick lore","who is thatros","fenwick thatros background"}},{q="Why does Varimathras want Fenwick Thatros dead?",a="Varimathras views Thatros as a rising threat who could rally stray undead in Silverpine against the Forsaken. To secure the borders around the Undercity, any rival leaders who threaten Sylvanas's absolute control over the region must be swiftly eliminated.",al={"varimathras thatros","why kill fenwick"}},{q="Who are the Deathstalkers?",a="The Deathstalkers are the premier espionage, assassination, and reconnaissance agency of the Forsaken. Based out of the Rogues' Quarter in the Undercity, they operate across Lordaeron to eliminate internal threats, spy on rival factions, and secure territories for the Dark Lady.",al={"deathstalkers lore","what are deathstalkers","undead rogues faction"}},{q="Where is Fenwick Thatros located?",a="Deathstalker reports place Thatros near a ruined, decrepit dock on the shore of Lake Lordamere in northeastern Silverpine Forest.",al={"where is fenwick","fenwick dock location","thatros lake lordamere"}},{q="What does completing this mission earn with the Deathstalkers?",a="Executing Thatros proves an operative's capability and loyalty to Mennet Carkad and the Deathstalkers. With your reliability demonstrated, Carkad offers to advance your training in the shadow arts through specialized trade instructions.",al={"fenwick reward lore","what comes after fenwick"}},{q="Who is Mennet Carkad?",a="Mennet Carkad is a rogue trainer and Deathstalker handler situated in the Rogues' Quarter of the Undercity. He oversees field agents and assigns missions directly tied to the security of the Forsaken realm.",al={"mennet carkad","who gives fenwick quest"}}},ang={["class:Rogue"]="This contract serves as a proving ground for Forsaken rogues, confirming their stealth and lethality before they are trusted with the deeper tools of the Deathstalker trade.",["race:Undead"]="The Forsaken cannot tolerate rival undead factions claiming sovereignty so close to the Capital City, making Thatros's head a political necessity."},kw={"deathstalkers","fenwick thatros","lake lordamere","mennet carkad","rogues' quarter","silverpine forest","undercity","varimathras"},rel={"quest:1999","npc:varimathras","quest:1886","quest:1885","subzone:rogues-quarter","zone:undercity","zone:silverpine","topic:forsaken"},m={start="Mennet Carkad",level="16",faction="Horde",id=1998},src={"Fenwick Thatros (quest)"}}
E["quest:1999"] = {t="quest",n="Tools of the Trade",z="undercity",s="Tools of the Trade is an initiation mission for Horde rogues given by Mennet Carkad in the Undercity. Ordered by Lord Varimathras, agents must obtain lockpicking gear and infiltrate Ambermill to recover sensitive Kirin Tor reports detailing Dalaran's current state.",h="Tools of the Trade is an initiation mission for Horde rogues given by Mennet Carkad in the Undercity.",sec={{t="Eyes on Ambermill",b="Following the interrogation of a Kirin Tor captive, the Deathstalkers learned that vital intelligence concerning the ruins of Dalaran lies hidden in Ambermill. Silverpine Forest remains a precarious front line, and the human mages guarding the village guard their communications fiercely. Under the orders of Lord Varimathras, Deathstalker handler Mennet Carkad directs promising operatives to bypass Kirin Tor sentries and secure the Dalaran Status Report.",sp=0},{t="The Art of the Breach",b="Unlike straightforward assassinations, this mission serves as a practical proving ground in infiltration and lockpicking. Operatives are outfitted with specialized thieves' tools from Estelle Gendry before marching into hostile Kirin Tor territory. Cracking the secured chest in Ambermill demonstrates that an operative has progressed beyond raw street brutality into an indispensable espionage asset for the Forsaken.",sp=0}},faq={{q="Who orders this mission?",a="Mennet Carkad, a master rogue of the Deathstalkers stationed in the Rogues' Quarter of the Undercity, assigns the task. The overarching mandate comes directly from Lord Varimathras, who oversees intelligence gathering for the Forsaken.",al={"who gives tools of the trade","quest giver","mennet carkad quest"}},{q="What is the Dalaran Status Report?",a="It is a sealed Kirin Tor dispatch detailing conditions within Dalaran. Deathstalker interrogators extracted its location from an imprisoned human mage, alerting the Undercity that crucial information about their southern neighbors was vulnerable.",al={"what are the documents","kirin tor papers","status report"}},{q="Where is the report kept?",a="The report is secured inside a locked chest within the Kirin Tor outpost of Ambermill, located in southern Silverpine Forest.",al={"where do i find the documents","ambermill chest location","where is the status report"}},{q="Who provides the lockpicking tools?",a="Estelle Gendry, an outfitter in the Rogues' Quarter of the Undercity, provides the necessary thieves' tools to open the Kirin Tor's locked chest.",al={"where do i get tools","estelle gendry role","outfitter tools"}},{q="Why is Dalaran important to the Forsaken right now?",a="Dalaran's surviving wizards maintain a fortified pocket behind an arcane dome right on the southern border of Silverpine Forest. The Forsaken keep careful tabs on their movements, strength, and defensive readiness to protect their own holdings in Lordaeron.",al={"why care about dalaran","forsaken vs dalaran","kirin tor threat"}},{q="What prerequisite must be completed before taking this mission?",a="Operatives must first complete the assassination contract Fenwick Thatros, hunting down a target in Silverpine Forest before Mennet Carkad trusts them with delicate infiltration work.",al={"prereq","what quest comes before","fenwick thatros quest"}}},ang={["class:Rogue"]="This mission marks a rite of passage for Horde rogues, requiring you to procure formal lockpicking tools and apply stealth and finesse rather than brute force.",["race:Undead"]="Infiltrating Ambermill allows the Forsaken to outwit the very Kirin Tor mages who seek to reclaim Lordaeron from the grave.",["faction:Horde"]="Securing human intelligence in Silverpine solidifies the Horde's foothold across northern Lordaeron against remnants of the Alliance."},kw={"ambermill","dalaran","deathstalkers","estelle gendry","kirin tor","lockpicking","mennet carkad","rogues' quarter","undercity","varimathras"},rel={"quest:1998","quest:1886","subzone:rogues-quarter","zone:undercity","subzone:ambermill","npc:varimathras","subzone:dalaran"},m={start="Mennet Carkad",level="20",faction="Horde",id=1999},src={"Tools of the Trade (Classic)"}}
E["quest:357"] = {t="quest",n="The Lich's Identity",z="undercity",s="The Lich's Identity is an Undercity quest given by Bethor Iceshard in the Magic Quarter. Seeking to uncover the identity of a reclusive lich living on Brightwater Lake, Bethor sends an emissary to steal the figure's spellbook to gauge his power and allegiance.",h="The Lich's Identity is an Undercity quest given by Bethor Iceshard in the Magic Quarter.",sec={{t="A Recluse on the Lake",b="North of the Undercity, in the misty waters of Brightwater Lake, a lone lich dwells in self-imposed exile on Mage Island. Unlike the mindless pawns of the Lich King, this necromancer possesses his own free will, yet he lives in deep paranoia. Convinced that any undead who approach him are Scourge thralls sent to drag him back into servitude, he unleashes his summoned minions on anyone setting foot on his shores.",sp=0},{t="A Valuable Asset",b="Word of the rogue lich eventually reached Bethor Iceshard, the archmage overseeing the mages in the Undercity. Bethor recognized the strategic importance of such an entity: Lady Sylvanas Windrunner seeks every scrap of magical mastery and every capable will to bolster the Forsaken against their many foes. To assess whether the hermit could be recruited, Bethor requires proof of his identity and necromantic expertise.",sp=0},{t="An Old Friend Found",b="After the stolen spellbook is delivered to the Magic Quarter, Bethor examines its arcane script and discovers the lich's true identity: Gunther Arcanus. In life, Gunther had been a talented necromancer and a close comrade of Bethor before the plague ravaged Lordaeron. The realization confirms that Gunther is not only an independent soul, but an old ally whose expanded necromantic powers could greatly benefit the Dark Lady's realm.",sp=1}},faq={{q="Who sends you on this mission?",a="Bethor Iceshard, a prominent undead mage trainer stationed in the Magic Quarter of the Undercity, assigns the task.",al={"quest giver","bethor iceshard location","who gives the lichs identity"}},{q="Why does the lich attack anyone who approaches him?",a="The lich broke free of the Lich King's control by his own will, but he mistakenly believes that all other undead in Lordaeron remain mind-controlled Scourge thralls. As a result, he orders his minions to attack any who approach his island to defend his freedom.",al={"why is gunther hostile","why does the lich attack","brightwater lich hostile"}},{q="Where is the lich's camp located?",a="He lives on an island in the middle of Brightwater Lake, located in Tirisfal Glades directly north of the Ruins of Lordaeron and Undercity.",al={"where is the lich","brightwater lake island","gunther arcanus location"}},{q="Why does Lady Sylvanas want him brought into the Forsaken?",a="Independent undead of high magical talent are exceptionally rare. A free-willed necromancer capable of wielding potent death magic would provide the Forsaken with crucial power against the Scourge and the Scarlet Crusade.",al={"why recruit the lich","forsaken interest in gunther","sylvanas lich"}},{q="Who does the lich turn out to be?",a="Bethor reveals the lich to be Gunther Arcanus, a former Dalaran mage and skilled necromancer who was a close comrade-in-arms of Bethor before the Third War.",al={"lich identity","who is the lich","identity of the lich"},sp=1},{q="What happens after you deliver the spellbook?",a="Once Bethor confirms Gunther's identity, he sends you back to Brightwater Lake with the spellbook to convince Gunther that the Forsaken are truly free and wish to welcome him.",al={"what next","return the book quest","after the lichs identity"},sp=1}},ang={["race:Undead"]="For the Forsaken, reclaiming independent undead like Gunther Arcanus proves that breaking free from the Lich King was not an isolated miracle, while securing vital necromantic power for Sylvanas's court.",["class:Mage"]="Mages visiting Bethor Iceshard in the Magic Quarter see the surviving remnants of Lordaeron's and Dalaran's magical traditions transformed into instruments of Forsaken survival.",["faction:Horde"]="Recruiting powerful necromancers strengthens the northern frontier of the Horde against relentless attacks by the Scarlet Crusade and Scourge."},kw={"bethor iceshard","brightwater lake","forsaken","magic quarter","necromancer","sylvanas","the lich's spellbook","undercity"},rel={"npc:bethor-iceshard","npc:gunther-arcanus","quest:405","quest:366","subzone:brightwater-lake","zone:undercity","topic:forsaken","topic:scourge"},m={start="Bethor Iceshard",level="8",faction="Horde",id=357},src={"The Lich's Identity"}}
E["quest:405"] = {t="quest",n="The Prodigal Lich",z="undercity",s="Following your service in Brill against Scourge remnants and rot hide gnolls, Magistrate Sevren directs you south to the Undercity. Bethor Iceshard, a prominent archmage in the Magic Quarter, requires a capable operative for a sensitive mission regarding a wayward lich.",h="Following your service in Brill against Scourge remnants and rot hide gnolls, Magistrate Sevren directs you...",sec={{t="Summons to the Capital",b="Having proven your capability in the ruined town of Brill, Magistrate Sevren deems you worthy of higher-level Forsaken endeavors. Bethor Iceshard, a formidable mage dwelling in the Undercity's Magic Quarter, has demanded an agent tested in combat against the Scourge. Sevren hands over official orders, dispatching you beneath the ruins of Lordaeron into the subterranean corridors of the Forsaken capital.",sp=0},{t="A Wayward Lich",b="While Sevren admits ignorance of the exact specifics, he reveals that the task revolves around finding and recruiting a rogue lich. Liches are among the most lethal spellcasters raised by the Scourge, making any interaction fraught with peril. When you deliver the orders to Bethor atop his arcane sanctum, the icy mage cuts straight to business, eager to assess whether Brill's magistrate has sent someone strong enough to handle such dangerous quarry.",sp=0}},faq={{q="Who sends me on this task?",a="Magistrate Sevren, the Forsaken official administering the town of Brill in Tirisfal Glades, sends you with written orders directly to Bethor Iceshard.",al={"who gives the prodigal lich","quest giver prodigal lich","sevren orders"}},{q="Where do I find Bethor Iceshard?",a="Bethor Iceshard resides in the Magic Quarter of the Undercity, typically found atop the central elevated structure surrounded by arcane energies.",al={"where is bethor","bethor iceshard location","how to find bethor"}},{q="What is the mission mentioned in the orders?",a="Bethor intends to enlist a wandering, rogue lich into service, but he first needs an agent capable of tracking down clues to the lich's identity and whereabouts.",al={"what is the lich mission","who is the wayward lich","prodigal lich purpose"}},{q="Why does Bethor require an agent tested against the Scourge?",a="Liches are masters of necromantic frost and death magic bound originally to the Lich King. Handling a free-willed or isolated lich requires someone who has already proven capable of surviving against undead Scourge threats.",al={"why scourge testing","why does bethor need me"}},{q="What prerequisite must be completed before receiving this quest?",a="You must complete Magistrate Sevren's previous assignment, 'Graverobbers', clearing out the Rot Hide gnolls and grave thieves in Garren's Haunt.",al={"prodigal lich prequest","how to unlock prodigal lich"}},{q="What comes after reporting to Bethor?",a="Upon turning in Sevren's orders, Bethor offers the quest 'The Lich's Identity', directing you to investigate artifacts and clues to uncover who this mysterious entity was in life.",al={"what is next after prodigal lich","prodigal lich follow up"}}},ang={["race:Undead"]="Taking your first direct orders from the capital marks your transition from local militia work in Brill to executing the greater geopolitical will of the Undercity.",["class:Mage"]="Reporting to Bethor Iceshard offers an audience with one of the most powerful arcane and frost masters among the Forsaken.",["faction:Horde"]="Securing unaligned or powerful necromantic assets strengthens the Forsaken's precarious hold on the ruins of Lordaeron against common enemies."},kw={"bethor iceshard","brill","magic quarter","magistrate sevren","prodigal lich","sevren's orders","tirisfal glades","undercity"},rel={"npc:bethor-iceshard","npc:magistrate-sevren","subzone:magic-quarter","zone:undercity","quest:357","quest:358","topic:scourge"},m={start="Magistrate Sevren",["end"]="Bethor Iceshard",level="8",faction="Horde",id=405},src={"The Prodigal Lich"}}
E["quest:411"] = {t="quest",n="The Prodigal Lich Returns",z="undercity",s="The Prodigal Lich Returns marks the conclusion of the effort to recruit Gunther Arcanus into the Forsaken. Having proven your intentions and restored his grimoire, you carry an arcane communion gem back to Bethor Iceshard in the Undercity.",h="The Prodigal Lich Returns marks the conclusion of the effort to recruit Gunther Arcanus into the Forsaken.",sec={{t="A Rare Reconciliation",b="Gunther Arcanus spent years isolated on an island in Brightwater Lake, having broken free from the Lich King's grip through sheer force of will, completely unaware that Sylvanas Windrunner had liberated Lordaeron. Bitter and suspicious of outsiders, Gunther distrusted the emissaries of the Undercity until an adventurer returned his spellbook and proved their hostility toward the Scourge. Satisfied that his visitor was not an enemy, Gunther entrusted them with a Nether Gem to establish contact with his former colleague.",sp=0},{t="Communion in the Magic Quarter",b="Returning to the Mage Quarter of the Undercity, the bearer delivers the Nether Gem to Bethor Iceshard. Bethor channels the gem's power to conjure Gunther's ethereal visage right within the sanctuary. Through this magical communion, the self-made lich formally agrees to ally with the Forsaken cause. Securing a necromancer of Gunther's independent mastery is a tremendous coup for the Dark Lady's nascent kingdom, bolstering their magical defenses against both the Scourge and the living.",sp=1}},faq={{q="Who is Gunther Arcanus?",a="Gunther Arcanus is an exceptionally powerful necromancer who broke free from the Lich King's mental domination on his own. He lived in reclusive exile on an island in Brightwater Lake, assuming all other undead were mindless thralls until adventurers proved otherwise.",al={"gunther arcanus lore","who is the prodigal lich","gunther undercity"}},{q="Who is Bethor Iceshard?",a="Bethor Iceshard is a senior mage and scholar residing in the Magic Quarter of the Undercity. He is an old colleague of Gunther Arcanus and coordinated the efforts to find and recruit him into the Forsaken.",al={"bethor lore","who is bethor","iceshard undercity"}},{q="What does the Nether Gem do?",a="The Nether Gem is an enchanted artifact provided by Gunther Arcanus. When Bethor Iceshard channels arcane power into it, it manifests a spectral projection of Gunther, allowing the two spellcasters to converse across great distances.",al={"what is the nether gem","gunther gem"}},{q="Why does Gunther agree to join the Forsaken?",a="Gunther spent years fearing he was the only free-willed undead in Lordaeron. Once convinced that Sylvanas's Forsaken are genuinely free of the Scourge and actively fighting the Lich King, he willingly pledges his allegiance and re-establishes ties with his former peers.",al={"why join forsaken","gunther allegiance"},sp=1},{q="Why does the quest call Gunther a 'Lich'?",a="While Gunther uses the standard skeletal and decayed form of a Forsaken rather than the floating, frost-wreathed silhouette of a Scourge lich, he attained lichdom independently through his advanced mastery of necromancy and sustained will.",al={"is gunther a real lich","gunther lich form"}},{q="What happens when you turn in the Nether Gem?",a="Upon completing the delivery, Bethor activates the gem, conjuring Gunther's Visage in the Magic Quarter. The projection moves toward Bethor to initiate their long-overdue reunion before fading.",al={"nether gem turn in event","what happens at bethor"},sp=1}},ang={["race:Undead"]="Gunther's liberation without the Banshee Queen's intervention serves as living proof of the sheer willpower Lordaeron's fallen can muster.",["class:Mage"]="Watching Bethor commune with Gunther demonstrates the seamless fusion of traditional Dalaran spellcraft and dark necromancy practiced in the Undercity's Magic Quarter.",["faction:Horde"]="Recruiting an independent, master-level necromancer like Gunther significantly fortifies the Horde's magical standing in the Eastern Kingdoms."},kw={"arcanus","bethor","brightwater lake","gunther","iceshard","lich","nether gem","prodigal","undercity"},rel={"npc:gunther-arcanus","npc:bethor-iceshard","quest:409","zone:undercity","topic:forsaken"},m={start="Gunther Arcanus",["end"]="Bethor Iceshard",level="12",faction="Horde",id=411},src={"The Prodigal Lich Returns"}}
E["quest:441"] = {t="quest",n="Raleigh and the Undercity",z="undercity",s="This quest bridges an investigation from Brill to the Undercity, tasking an adventurer with delivering a recovered heirloom ring to a widower named Raleigh. Found on the corpse of a Scourge defiler, the jewelry points to a tragedy among Lordaeron's former inhabitants. Delivering it sets into motion a dark pursuit of vengeance.",h="This quest bridges an investigation from Brill to the Undercity, tasking an adventurer with delivering a...",sec={{t="A Tragic Heirloom",b="In Brill, Magistrate Sevren pieced together clues surrounding a stolen corpse and recovered an engraved ring that once belonged to a woman named Deliah. Hoping to confirm its origin and see it returned to her family, Sevren directed the finder deep into the subterranean halls of the Undercity to seek Deliah's surviving husband, Raleigh.",sp=0},{t="Cold Hearts, Bitter Vengeance",b="Located in the bustling Trade Quarter of the Undercity, Raleigh Andrean recognizes his former wife's ring without hesitation. Like many of the Forsaken, undeath has withered his capacity for sorrow, grief, or remorse over Deliah's passing and desecration. However, where tender emotions have died away, an unyielding thirst for retribution remains, prompting Raleigh to plot revenge against those who violated her final rest.",sp=1}},faq={{q="Who starts this quest?",a="Magistrate Sevren starts this quest in the town of Brill within Tirisfal Glades, immediately after you return Deliah's Ring to him.",al={"where do i get raleigh and the undercity","quest giver","magistrate sevren quest"}},{q="Where is Raleigh Andrean located?",a="Raleigh Andrean is located in the Trade Quarter of the Undercity, standing among the subterranean city's merchants and craftsmen.",al={"raleigh location","where is raleigh","trade quarter raleigh"}},{q="Whose ring is being delivered?",a="The ring belonged to Deliah, a woman from Brill who was Raleigh Andrean's wife prior to the fall of Lordaeron.",al={"deliah ring","who was deliah","whose ring is this"}},{q="Why doesn't Raleigh mourn his dead wife?",a="As one of the Forsaken, Raleigh admits that tender emotions like grief and love have grown cold within his undead heart. Instead, his lingering passions have curdled into a cold desire for vengeance.",al={"raleigh reaction","does raleigh care","why is raleigh cold"}},{q="What happens after this quest?",a="Handing in the ring leads directly into the quest 'A Husband's Revenge', where Raleigh sends you to avenge his wife's desecration.",al={"next quest","follow up to raleigh","what comes after"},sp=1},{q="How was Deliah's ring found initially?",a="The ring was recovered during the quest 'The Engraved Ring', retrieved from the defiler who plundered Deliah's grave in Tirisfal Glades.",al={"ring origin","where did the ring come from"}}},ang={["race:Undead"]="Raleigh's cold reaction to his wife's tragic demise reflects the widespread psychological trauma shared by the Forsaken, whose mortal attachments have decayed into bitter wrath.",["faction:Horde"]="Carrying tokens of old Lordaeron through the gates of the Undercity illustrates the somber realities of life among your Forsaken allies."},kw={"a husband's revenge","brill","deliah","deliah's ring","raleigh","sevren","trade quarter","undercity"},rel={"quest:440","quest:530","npc:raleigh-andrean","npc:magistrate-sevren","zone:undercity","subzone:trade-quarter","subzone:brill"},m={start="Magistrate Sevren",["end"]="Raleigh Andrean",level="16",faction="Horde",id=441},src={"Raleigh and the Undercity"}}
E["quest:444"] = {t="quest",n="Rot Hide Origins",z="undercity",s="\"Rot Hide Origins\" is a Forsaken quest bridging the research of the Royal Apothecary Society in the Silverpine forest with the sorcerous expertise of the Undercity. After analyzing putrid fluids taken from gnolls, Apothecary Renferrel sends an adventurer to consult Bethor Iceshard to uncover the magical lineage behind these rotting beasts.",h="\"Rot Hide Origins\" is a Forsaken quest bridging the research of the Royal Apothecary Society in the...",sec={{t="A Concoction of Death and Fel",b="While examining the fluid harvested from the rot hide gnolls infesting Silverpine Forest, Apothecary Renferrel manages to reduce the foul substance into its basic elements. His preliminary chemical distillation reveals something far stranger than ordinary gnoll disease: the ichor carries the unmistakable dual signature of necromancy and warlock arts. Realizing pure alchemy cannot unravel the full scope of the sorcery at play, Renferrel tasks an agent with taking a prepared sample directly to the capital for esoteric scrutiny.",sp=0},{t="Audience with the Mage",b="The sample is carried to Bethor Iceshard, an accomplished Forsaken mage stationed high within the Magic Quarter of the Undercity. Bethor does not belong to the Royal Apothecary Society, but his deep familiarity with arcane and dark disciplines makes him an invaluable resource for decoding unusual weaves of power. Upon receiving the vile vial, Bethor detects old, potent enchantments that he has not observed in years, immediately preparing a divination spell to identify who wove the foul magic.",sp=1}},faq={{q="Who sends the player on this quest?",a="Apothecary Renferrel, an alchemist of the Royal Apothecary Society based in Silverpine Forest at the Sepulcher, assigns this task after examining the ichor recovered from nearby rot hide gnolls.",al={"who starts rot hide origins","where do i get rot hide origins"}},{q="Why does Renferrel send the sample to Bethor Iceshard?",a="Renferrel discovers that the rot hide ichor is steeped in necromantic and warlock magic. Since alchemy alone cannot fully explain the enchantments at work, he seeks the arcane expertise of Bethor Iceshard in the Undercity to divine its magical origins.",al={"why bethor iceshard","why give sample to mage"}},{q="Where is Bethor Iceshard located?",a="Bethor Iceshard resides in the Magic Quarter of the Undercity, surrounded by arcane researchers and trainers.",al={"bethor location","where is bethor iceshard"}},{q="What are the Rot Hides?",a="Rot hides are undead gnolls prowling Silverpine Forest. Unlike ordinary mindless beasts, their rotting condition is artificially induced by foul magical experiments.",al={"what are rot hides","rot hide gnolls silverpine"}},{q="What happens when you deliver the sample to Bethor?",a="Bethor recognizes ancient and potent magic laced throughout the fluid, noting that he has not encountered these particular spells in a very long time. He immediately begins casting a divination spell to track the source of the magic.",al={"what does bethor do","bethor iceshard reaction"}},{q="What quest comes next?",a="Following this delivery and Bethor's divination, he sends the adventurer on the quest 'Thule Ravenclaw' to investigate the renegade mage responsible for corrupting the gnolls.",al={"next quest after rot hide origins","follow up to rot hide origins"},sp=1}},ang={["race:Undead"]="This task demonstrates the cooperation between the Royal Apothecary Society and the arcane masters of the Undercity, coordinating science and sorcery to safeguard Lordaeron.",["class:Mage"]="Bethor Iceshard's role underscores how arcane divination and scholarly spellcraft remain vital tools for solving dark mysteries that confound ordinary alchemy.",["class:Warlock"]="The discovery of fel and warlock magics intermingled with necromancy in the rot hide ichor points toward deliberate, taboo spellcraft at work in the Silverpine wilderness."},kw={"apothecary renferrel","bethor iceshard","magic quarter","rot hide ichor","rot hide origins","sample ichor","silverpine forest","undercity"},rel={"npc:bethor-iceshard","npc:apothecary-renferrel","zone:undercity","subzone:magic-quarter"},m={start="Apothecary Renferrel",["end"]="Bethor Iceshard",level="17",faction="Horde",id=444},src={"Rot Hide Origins"}}
E["quest:447"] = {t="quest",n="A Recipe For Death",z="undercity",s="A Recipe For Death is an alchemical errand commissioned by Apothecary Renferrel at the Sepulcher in Silverpine Forest. Tasked with gathering grizzly bear hearts and arachnid blood, adventurers transport the volatile biological reagents to Master Apothecary Faranell in the Undercity to aid in formulating the Forsaken's lethal New Plague.",h="A Recipe For Death is an alchemical errand commissioned by Apothecary Renferrel at the Sepulcher in...",sec={{t="A Weapon Against Two Foes",b="Positioned on the front lines in Silverpine Forest, Apothecary Renferrel recognizes the grim arithmetic facing Sylvanas's people. Surrounded by the relentless legions of Arthas and enduring remnants of humanity, conventional warfare offers little hope. The Forsaken's grand ambition lies in developing a New Plague—an engineered contagion potent enough to rot both living humans and undead Scourge alike. Renferrel's field research determined that combining arachnid venom from the Skittering Dark with toxins concentrated in the hearts of native bears yields a virulent foundation.",sp=0},{t="Dispatch to the Apothecarium",b="Once the harvested organs and blood are collected from the wilderness of Silverpine, they must be delivered beneath the ruins of Lordaeron into the heart of the Apothecarium. There, Master Apothecary Faranell oversees the grand design of the Royal Apothecary Society. Faranell immediately takes custody of Renferrel's samples, testing their contaminable properties to refine formulas that might one day secure Forsaken supremacy across the continent.",sp=0}},faq={{q="What is the purpose of collecting bear hearts and spider blood?",a="Apothecary Renferrel's research showed that spider blood from the Skittering Dark reacts lethally when combined with toxins found in grizzled bear hearts. Together, these reagents provide vital raw materials for testing and developing the Royal Apothecary Society's New Plague.",al={"why bear hearts","why spider blood","what is this recipe for"}},{q="Who is Master Apothecary Faranell?",a="Master Apothecary Faranell is the head of the Royal Apothecary Society, stationed in the Apothecarium quarter of the Undercity. He oversees all research into concocting the New Plague on behalf of Lady Sylvanas Windrunner.",al={"faranell lore","who is faranell","master apothecary"}},{q="Why do the Forsaken want to create a New Plague?",a="Outnumbered by the Scourge and despised by living humans, the Forsaken lack the sheer military manpower to win an extended conventional war. A bespoke New Plague is engineered to eliminate both living adversaries and undead Scourge, securing their survival and autonomy.",al={"why make new plague","forsaken plague motivation","new plague lore"}},{q="Where is Apothecary Renferrel located?",a="Apothecary Renferrel conducts his research out of the Sepulcher, the primary Forsaken settlement nestled within Silverpine Forest.",al={"renferrel location","where is renferrel"}},{q="Where is the Skittering Dark?",a="The Skittering Dark is an arachnid-infested wilderness located northwest of the Sepulcher in Silverpine Forest, filled with giant spiders whose blood Renferrel requires.",al={"skittering dark location","where to find spiders silverpine"}},{q="Does this quest continue further?",a="Yes. Master Apothecary Faranell uses the delivered reagents to continue his experiments, leading directly into subsequent tasks within the Apothecarium to refine and test the lethal mixture.",al={"recipe for death follow up","is there a part 2"}}},ang={["race:Undead"]="Contributing to the Apothecary Society's plague research is among the highest duties an aspiring Forsaken can undertake to safeguard their fragile realm against the Scourge and humanity.",["faction:Horde"]="While Forsaken apothecaries pursue victory through virulent biological concoctions, such horrific methods are kept under tight wraps from the honor-bound leadership in Kalimdor."},kw={"faranell","new plague","renferrel","royal apothecary society","silverpine","skittering dark","undercity"},rel={"npc:apothecary-renferrel","npc:master-apothecary-faranell","topic:royal-apothecary-society","quest:367","subzone:skittering-dark","zone:silverpine","zone:undercity","topic:scourge"},m={start="Apothecary Renferrel",["end"]="Master Apothecary Faranell",level="12",faction="Horde",id=447},src={"A Recipe For Death"}}
E["quest:450"] = {t="quest",n="A Recipe For Death",z="undercity",s="Master Apothecary Faranell tasks Horde adventurers with recovering the lost research of Apothecary Berard from Pyrewood Village. Berard fell victim to Archmage Arugal's shadow magic, leaving behind critical notes on an ancient blight that wiped out Lake Lordamere's aquatic life.",h="Master Apothecary Faranell tasks Horde adventurers with recovering the lost research of Apothecary Berard...",sec={{t="A Mind Lost to Shadow",b="Before his downfall, Apothecary Berard was considered one of the Royal Apothecary Society's most promising researchers. Stationed in Pyrewood Village, he investigated past ecological disasters to aid the Forsaken's alchemical pursuits. However, when Archmage Arugal unleashed his dark sorcery over Silverpine Forest, Berard succumbed to the curse, degrading into a mindless servant under the mage's thrall.",sp=0},{t="The Secrets of Lake Lordamere",b="Though Berard is considered a lost cause by Master Apothecary Faranell, his research remains immensely valuable to the Society. Berard had been cataloging the characteristics of a forgotten plague that eradicated all aquatic life in Lake Lordamere long ago. Recovering his journal from the Pyrewood Village Inn and delivering it to Apothecary Renferrel at the Sepulcher ensures the Royal Apothecary Society can adapt those deadly properties for the Dark Lady's arsenal.",sp=1}},faq={{q="Who is Apothecary Berard?",a="Apothecary Berard was once a brilliant researcher for the Royal Apothecary Society based in Silverpine Forest. His promising career ended when Archmage Arugal cast a dark curse across the region, shattering Berard's mind and binding him as a thrall in Pyrewood Village.",al={"berard lore","who was berard","apothecary berard pyrewood"}},{q="Why does the Royal Apothecary Society want Berard's journal?",a="Prior to his mental degradation, Berard was documenting an ancient plague that killed off all aquatic life in Lake Lordamere ages ago. The Society seeks these records to understand the virulent agent and incorporate its lethal mechanisms into their ongoing research.",al={"why get the journal","berards journal purpose","lake lordamere plague notes"}},{q="Where is Berard's journal located?",a="The journal is kept in Berard's study on an upper floor of the Pyrewood Village Inn, located toward the rear of the village. The afflicted apothecary still guards his former quarters.",al={"where is the journal","find berard journal","pyrewood inn journal"}},{q="Who receives the recovered journal?",a="The journal must be delivered to Apothecary Renferrel, who oversees the Royal Apothecary Society's field operations from the Sepulcher in Silverpine Forest.",al={"who turns in berard journal","who do i bring the journal to","where take journal"}},{q="What happened to Pyrewood Village?",a="Pyrewood Village fell under the corrupting influence of Archmage Arugal, who unleashed shadow magic from nearby Shadowfang Keep. The curse warp the minds and bodies of the villagers, subjecting them to Arugal's dark will.",al={"pyrewood curse","what is wrong with pyrewood","arugal curse pyrewood"}},{q="Who is Master Apothecary Faranell?",a="Master Apothecary Faranell is the head of the Royal Apothecary Society, conducting operations from the Apothecarium in the Undercity. He directly oversees the creation of new blights and venoms to defend the Forsaken and eradicate their enemies.",al={"faranell","who gives recipe for death","apothecary leader undercity"}}},ang={["race:Undead"]="The Royal Apothecary Society shows cold pragmatism: when a promising peer like Berard is lost to madness, his personal tragedy is disregarded in favor of salvaging his lethal research.",["faction:Horde"]="Assisting the Royal Apothecary Society in Silverpine helps secure the Forsaken's borders against the wild terrors unleashed by Arugal."},kw={"arugal","berard","faranell","journal","lordamere","pyrewood","renferrel","sepulcher"},rel={"quest:447","npc:master-apothecary-faranell","npc:apothecary-renferrel","subzone:pyrewood-village","subzone:sepulcher","npc:arugal","topic:royal-apothecary-society"},m={start="Master Apothecary Faranell",["end"]="Apothecary Renferrel",level="15",faction="Horde",id=450},src={"A Recipe For Death (2)"}}
E["quest:451"] = {t="quest",n="A Recipe For Death",z="undercity",s="A Recipe For Death concludes an investigation into the findings of a fallen researcher, directing adventurers to gather rare biological reagents across Lake Lordamere. By recovering harvested mosses and a strange tumor, the Forsaken bring essential components to Master Apothecary Faranell in the Undercity. This work directly supports the Royal Apothecary Society's overarching goal to develop a New Plague.",h="A Recipe For Death concludes an investigation into the findings of a fallen researcher, directing adventurers...",sec={{t="A Legacy of Research",b="The death of Apothecary Berard struck a blow against the Royal Apothecary Society, but his field journal left behind crucial insights into the blighted biology of Silverpine Forest and Lake Lordamere. Stationed at the Sepulcher, Apothecary Renferrel parsed through Berard's recovered notes and discovered that Berard had documented promising properties in local freshwater organisms. Rather than let Berard's sacrifice go to waste, Renferrel tasks champions of the Horde with fulfilling his late colleague's vision.",sp=0},{t="The Hazards of Lake Lordamere",b="Gathering Berard's specified reagents requires venturing onto the Dawning Isles, the mist-shrouded islands situated along the eastern waters of Lake Lordamere. The lake skulkers and lake creepers inhabiting these isles gather peculiar strains of moss that survive in tainted waters. More elusive is the hardened tumor, a bizarre growth noted by Berard among the vicious Vile Fin murloc tribes that nest along the islets and southern lake shoreline near Ambermill.",sp=0},{t="Fueling the Apothecarium",b="Once collected, the specimens bypass the Sepulcher entirely and are delivered straight to the Apothecarium in the Undercity, into the waiting hands of Master Apothecary Faranell. Faranell views these strange mutations as indispensable steps toward crafting a New Plague capable of eradicating both Scourge and living foes. Berard's research is swiftly integrated into the Society's ongoing cauldron vats, bringing the Forsaken one step closer to their ultimate weapon.",sp=1}},faq={{q="Why does the Royal Apothecary Society need moss and a tumor?",a="Apothecary Berard's field journal noted that the aquatic mosses found on lake beasts and the bizarre hardened tumors developing on local Vile Fin murlocs possess unique biological properties. Master Apothecary Faranell utilizes these rare mutated reagents to brew and refine the Royal Apothecary Society's New Plague.",al={"why moss and tumor","apothecary recipe ingredients","what is the tumor for"}},{q="Who was Berard?",a="Apothecary Berard was a researcher for the Royal Apothecary Society operating in Silverpine Forest. After his untimely death, his recovered field journal provided Apothecary Renferrel and Master Apothecary Faranell with the vital reagent specifications needed to continue his work.",al={"apothecary berard","who is berard","berard journal"}},{q="Where are the Dawning Isles located?",a="The Dawning Isles are a cluster of small islands situated in eastern Lake Lordamere, just east of Silverpine Forest. They are heavily infested with lake skulkers, lake creepers, and tribes of hostile Vile Fin murlocs.",al={"where are dawning isles","dawning isles location","lake skulker location"}},{q="Who is Master Apothecary Faranell?",a="Master Apothecary Faranell is the leader of the Royal Apothecary Society, stationed deep within the Apothecarium of the Undercity. He oversees all research and development concerning chemical warfare, biological concoctions, and the creation of the New Plague on behalf of Lady Sylvanas Windrunner.",al={"faranell","who is faranell","master apothecary faranell"}},{q="Why are Vile Fin murlocs growing hardened tumors?",a="The waters and shores around Lake Lordamere have been heavily warped by blighted decay and nearby arcane conflicts. The hardened tumors found on the Vile Fin are rare, abnormal growths resulting from this contaminated environment, making them of immense scientific interest to the Forsaken.",al={"why murloc tumor","vile fin tumor lore","hardened tumor murlocs"}},{q="How does this quest connect to the New Plague?",a="The entire Recipe for Death chain is an ingredient-gathering endeavor directly tied to the development of the New Plague. While junior apothecaries like Renferrel decipher and collect regional materials, everything is funneled directly to Faranell's central plague-brewing operations in the Undercity.",al={"new plague connection","a new plague questline","is this the plague"}}},ang={["race:Undead"]="Fulfilling Berard's unfinished experiments directly empowers the Dark Lady's vision, proving that every Forsaken mind contributes to the nation's survival even in death.",["faction:Horde"]="While Forsaken apothecaries welcome help from allied Horde combatants, they keep the finer chemical secrets and ultimate destructive potential of their New Plague carefully guarded."},kw={"a recipe for death","apothecarium","berard","dawning isles","faranell","hardened tumor","lake creeper","lake lordamere","lake skulker","new plague","renferrel","vile fin"},rel={"npc:master-apothecary-faranell","npc:apothecary-renferrel","quest:447","quest:367","topic:royal-apothecary-society","subzone:dawning-isles","zone:undercity","topic:murloc"},m={start="Apothecary Renferrel",["end"]="Master Apothecary Faranell",level="18",faction="Horde",id=451},src={"A Recipe For Death (3)"}}
E["quest:491"] = {t="quest",n="Wand to Bethor",z="undercity",s="This quest concludes the Fenris Keep confrontation by delivering a long-lost relic, the Woven Wand, back to Bethor Iceshard in the Undercity. Crafted years ago by three apprentice mages as a symbol of fellowship, the wand was hidden away when Thule Ravenclaw chose the Scourge. Returning it closes a bitter chapter in Bethor's past.",h="This quest concludes the Fenris Keep confrontation by delivering a long-lost relic, the Woven Wand, back to...",sec={{t="A Token of Fractured Fellowship",b="Long before Lordaeron fell into ruin, three young mages bound their training wands together into a single instrument known as the Woven Wand. It was meant to symbolize their shared bond and ambition within the magical arts. However, when Thule Ravenclaw turned his loyalty toward the Lich King and embraced the Scourge, that fellowship broke irrevocably. Though Thule came to despise the friendship they once shared, he could not bear to destroy the wand, nor could he stomach leaving it in his former comrades' hands.",sp=0},{t="Hidden in the Keep",b="Rather than part with the wand or destroy it, Thule carried it to Fenris Isle and concealed it in a dusty hidden shelf inside Fenris Keep. Untouched for years, its enchantment remained dormant; Thule never invoked its magic, an act Bethor noted would have immediately betrayed its whereabouts. Bringing it back to the Magic Quarter of the Undercity returns a rare keepsake of Bethor's mortal youth, recovered from the lair of a traitor who could neither love his friends nor let them go.",sp=1}},faq={{q="What is the Woven Wand?",a="The Woven Wand is a unique magical tool fashioned long ago by Thule Ravenclaw and two fellow mage apprentices, one of whom was Bethor Iceshard. Each contributed their early apprentice wand, weaving them together as a physical emblem of their mutual friendship and shared arcane studies.",al={"woven wand","what is the wand","thule wand lore"}},{q="Why did Thule Ravenclaw steal the wand?",a="When Thule defected to the Lich King, the bond between the colleagues disintegrated. Even though Thule came to hate the friendship it represented, he was too possessive to part with the relic or allow Bethor and his other companion to keep it. Instead, he stole the wand and hid it on Fenris Isle.",al={"why did thule take it","why steal the wand","thule stolen wand"}},{q="Who is Bethor Iceshard?",a="Bethor Iceshard is a Forsaken mage trainer residing in the Magic Quarter of the Undercity. In life, he was a peer and friend to Thule Ravenclaw before the kingdom collapsed and Thule surrendered his will to the Scourge.",al={"who is bethor","bethor iceshard lore","bethor undercity"}},{q="Why didn't Thule use the Woven Wand's magic?",a="Had Thule ever invoked the wand's latent enchantments, Bethor would have sensed the resonance across the arcane weave. Thule kept it tucked away on a forgotten shelf in Fenris Keep solely out of spite and possessiveness, leaving its power untouched.",al={"did thule use wand","wand power","why not use it"}},{q="Who was the third apprentice who helped make the wand?",a="Bethor and Thule made the wand with a third apprentice colleague long ago, though historical records surviving in the Undercity focus entirely on the bitter rift between Bethor and Thule Ravenclaw.",al={"third apprentice","three mages wand","third mage"}},{q="Where did the wand end up before being found?",a="The wand was stashed away in a dusty shelf within a hidden niche inside Fenris Keep, the stronghold on Fenris Isle where Thule Ravenclaw established his Scourge operations.",al={"where was wand","hidden niche wand","fenris keep wand"}}},ang={["class:Mage"]="The Woven Wand represents a classic arcane tradition: apprentice mages binding their foci together in fellowship, an innocence shattered when the Scourge tore Dalaran and Lordaeron apart.",["race:Undead"]="For Forsaken mages like Bethor, recovering pre-plague artifacts is a bittersweet reminder of mortal ambition and the former friends who chose the Lich King's tyranny over free will."},kw={"bethor iceshard","fenris isle","fenris keep","magic quarter","silverpine","thule ravenclaw","undercity","woven wand"},rel={"quest:461","quest:460","quest:446","npc:bethor-iceshard","subzone:magic-quarter","subzone:fenris-keep","zone:undercity","topic:lich-king"},m={start="Dusty Shelf",["end"]="Bethor Iceshard",level="18",faction="Horde",id=491},src={"Wand to Bethor"}}
E["quest:513"] = {t="quest",n="Elixir of Agony",z="undercity",s="This errand carries Apothecary Lydon's freshly mashed Mudsnout Composite from Tarren Mill straight to the heart of the Royal Apothecary Society in the Undercity. Master Apothecary Faranell requires the plant mash to treat it with a colloid of decay, furthering the Forsaken's development of a new plague.",h="This errand carries Apothecary Lydon's freshly mashed Mudsnout Composite from Tarren Mill straight to the...",sec={{t="A Courier to the Capital",b="In the ongoing efforts of the Royal Apothecary Society, regional researchers frequently send their raw discoveries back to Undercity for specialized refinement. Apothecary Lydon has mashed down local Mudsnout Blossoms into a composite, but bringing it to lethal fruition requires the advanced reagents kept only in the capital's laboratory.",sp=0},{t="The Master's Urgency",b="Master Apothecary Faranell works under tremendous pressure within the Apothecarium. Caught between the ever-present shadow of the Scourge in the north and aggressive human populations to the south, Lady Sylvanas Windrunner has demanded a potent new plague to defend their people. Receiving Lydon's composite provides Faranell with exactly the kind of toxic breakthrough the Dark Lady expects.",sp=0}},faq={{q="Why do I need to take the Mudsnout Composite to the Undercity?",a="Apothecary Lydon in Tarren Mill lacks the specific reagents required to finish this stage of his experiment. Master Apothecary Faranell holds a colloid of decay in the Apothecarium that must be applied to the Mudsnout Composite before the mixture can progress.",al={"why go to undercity","mudsnout composite destination","why bring to faranell"}},{q="Who is Master Apothecary Faranell?",a="Master Apothecary Faranell leads the Royal Apothecary Society from his laboratory deep in the Undercity. He oversees all major chemical and alchemical research for the Forsaken, answering directly to Lady Sylvanas Windrunner.",al={"who is faranell","master apothecary faranell lore","apothecarium leader"}},{q="What is the new plague the apothecaries keep mentioning?",a="The new plague is an ongoing Forsaken project commanded by Lady Sylvanas. It is engineered to annihilate both the living and the undead Scourge, providing the Forsaken with an absolute weapon against their enemies.",al={"what is the new plague","forsaken plague project","why make a new plague"}},{q="Where can I find Master Apothecary Faranell?",a="Faranell resides within the Apothecarium, the southwestern quarter of the Undercity dedicated entirely to alchemy, poison brewing, and surgical experimentation.",al={"where is faranell","faranell location","apothecarium location"}},{q="What is Apothecary Lydon trying to create?",a="Lydon is concocting the Elixir of Agony, an intensely virulent toxin brewed from Hillsbrad flora and decay agents, designed to prove the effectiveness of new strains in the field.",al={"what is lydon making","elixir of agony purpose","lydon experiment"}},{q="Why is the Royal Apothecary Society so rushed?",a="The Forsaken perceive threats on every side. Northrend's Scourge threatens to overrun them, while remnants of human resistance apply relentless pressure from the south, making the completion of a decisive biological weapon urgently necessary.",al={"why rush","faranell busy","undercity threat"}}},ang={["race:Undead"]="Every batch of raw plant matter delivered to Faranell contributes to the ultimate survival and sovereign defense of the Forsaken against both the living and the Scourge.",["faction:Horde"]="The Horde relies on Forsaken territory to hold northern Lordaeron, and the Royal Apothecary Society's research forms a vital part of holding those vulnerable borders."},kw={"apothecarium","apothecary lydon","colloid of decay","elixir of agony","master apothecary faranell","mudsnout composite","new plague","undercity"},rel={"npc:master-apothecary-faranell","quest:509","subzone:apothecarium","zone:undercity","quest:367","zone:hillsbrad","topic:scourge","topic:horde"},m={start="Apothecary Lydon",["end"]="Master Apothecary Faranell",level="28",faction="Horde",id=513},src={"Elixir of Agony (2)"}}
E["quest:515"] = {t="quest",n="Elixir of Agony",z="undercity",s="This errand continues the development of the Royal Apothecary Society's new plague, dispatching a courier from Undercity back to Tarren Mill. Master Apothecary Faranell enriches a captured gnoll mixture with his own decaying compounds, demanding coastal reagents and alchemical draughts to catalyze the lethal brew.",h="This errand continues the development of the Royal Apothecary Society's new plague, dispatching a courier...",sec={{t="A Colloid of Decay",b="When Apothecary Lydon's field work uncovered a potent composite brewed by the local Mudsnout gnolls, he sent it straight to the Apothecarium in the Undercity. Master Apothecary Faranell, head of the Royal Apothecary Society, immediately recognized the concoction's grim potential. Delighted by its toxic properties, Faranell added his own specialized colloid of decay to the mixture before outlining the catalysts required to weaponize it fully.",sp=0},{t="Catalysts from the Coast",b="Activating the volatile contaminating agents requires precise reagents that Lydon must assemble in Tarren Mill. In addition to a restorative draught of Strong Troll's Blood to feed and stabilize the chemical reaction, Faranell requires organic components harvested from the southern shoreline of Hillsbrad: scales stripped from the serpentine Daggerspine naga and eyes carved from the coastal Torn Fin murlocs.",sp=0},{t="Cruelty in Tarren Mill",b="Back in Tarren Mill, Lydon passes the waiting hours in morbid amusement, routinely poisoning, infecting, and reanimating his unfortunate undead test subject, Umpi. The delivery of Faranell's enriched mixture and coastal catalysts brings the apothecary closer to his ultimate goal: perfecting a new strain of agonizing blight to unleash against the living settlements of Hillsbrad.",sp=1}},faq={{q="Why does the plague require a restorative troll's blood elixir?",a="Apothecary concoctions frequently use regenerative substances to sustain, fuel, and rapidly mutate aggressive biological agents. The restorative properties of Strong Troll's Blood keep the toxic cultures thriving long enough to catalyze against the other reactive tissues.",al={"why troll blood","strong trolls blood purpose","trolls blood elixir plague"}},{q="Where are the Daggerspine scales found?",a="Daggerspine scales are harvested from the hostile Daggerspine naga inhabiting the eastern beaches of the Hillsbrad Foothills, situated along the shoreline east of the Alliance town of Southshore.",al={"daggerspine scales location","where are naga scales","where to get scales"}},{q="Where are the Torn Fin eyes obtained?",a="Torn Fin eyes are gathered from the Torn Fin murlocs dwelling in tribes along the western coastline of the Hillsbrad Foothills, just west of Southshore.",al={"torn fin eye location","where are torn fin murlocs","murloc eyes hillsbrad"}},{q="Who is Umpi?",a="Umpi is an undead servant stationed with Apothecary Lydon in Tarren Mill. Lydon spends his idle hours using her as a disposable test subject, repeatedly inflicting lethal toxins and diseases upon her only to reanimate her once more.",al={"who is umpi","umpi hillsbrad","lydon assistant umpi"}},{q="Why is Master Apothecary Faranell involved in this local project?",a="As the leader of the Royal Apothecary Society, Faranell oversees all research into new biological agents and plagues. Field apothecaries like Lydon send promising wild discoveries directly to Faranell in the Undercity for refinement and authorization.",al={"why faranell","master apothecary faranell role","royal apothecary society leader"}},{q="What is the Mudsnout Mixture?",a="It is an unrefined toxic composite originally extracted from the Mudsnout gnolls of the Hillsbrad Foothills. Recognizing its unusual virulence, Lydon sent it to Undercity, where Faranell blended it with decayed colloids to build a deadlier contagion.",al={"mudsnout mixture","gnoll poison","mudsnout composite"}}},ang={["race:Undead"]="Every refined reagent in this quest line brings the Royal Apothecary Society one step closer to fulfilling Lady Sylvanas's desire for an ultimate weapon against the living.",["faction:Horde"]="Tarren Mill stands on the brink of constant border skirmishes with the Alliance of Southshore; Lydon's toxic experiments are meant to tip the regional balance of power."},kw={"daggerspine","elixir of agony","faranell","lydon","mudsnout","tarren mill","torn fin","umpi","undercity"},rel={"npc:master-apothecary-faranell","subzone:tarren-mill","topic:royal-apothecary-society","npc:umpi","quest:509","zone:hillsbrad","zone:undercity","subzone:southshore"},m={start="Master Apothecary Faranell",["end"]="Apothecary Lydon",level="30",faction="Horde",id=515},src={"Elixir of Agony (3)"}}
E["quest:530"] = {t="quest",n="A Husband's Revenge",z="undercity",s="A Husband's Revenge is the conclusion to a tragic tale of past betrayal carried into undeath. Raleigh Andrean, a Forsaken residing in the Undercity, charges travelers with tracking down his former friend Valdred Moray, who murdered his wife in life.",h="A Husband's Revenge is the conclusion to a tragic tale of past betrayal carried into undeath.",sec={{t="A Bitter Memory",b="When Raleigh Andrean received the engraved ring carried from Hillsbrad Foothills, it rekindled memories of his mortal life that undeath had mostly withered away. Among those memories was a profound betrayal: his close friend, Valdred Moray, had murdered Raleigh's wife, Deliah. While the chill of the Scourge and subsequent Forsaken existence dulled Raleigh's capacity for grief and love, his thirst for retribution remained entirely intact.",sp=0},{t="Justice at the Wall",b="Fleeing the consequences of his past actions and the horrors of Lordaeron, Valdred Moray fled southward through Silverpine Forest, desperate to escape into the isolationist human kingdom behind the Greymane Wall. Yet the colossal gates remained sealed against refugees and outcasts alike. Trapped against the stonework, Valdred met his end at the behest of the friend he betrayed, his severed hands severed and carried back to the Undercity.",sp=1},{t="Cold Keepsakes",b="Upon receiving the hands of his former friend, Raleigh feels no rush of warmth or redemption—only cold finality. Having settled the score, he surrenders Deliah's wedding band without sentiment, declaring it a useless bauble. In its place, the severed hands of Valdred Moray remain in the Undercity as Raleigh's grim, permanent reminder of mortal betrayal.",sp=1}},faq={{q="Who was Deliah?",a="Deliah was Raleigh Andrean's wife during their mortal lives in Lordaeron. She was murdered by Raleigh's once-trusted friend, Valdred Moray, before the kingdom fell.",al={"who is deliah","raleigh's wife","raleigh wife"}},{q="Why does Raleigh want Valdred's hands specifically?",a="Raleigh demands Valdred's hands because they are the physical instruments that ended his wife's life. He intends to keep them in the Undercity as a permanent trophy and reminder of his friend's betrayal.",al={"why hands","valdred hands","raleigh wants hands"}},{q="Where is Valdred Moray hiding?",a="Valdred Moray is located in far southern Silverpine Forest, camped against the colossal Greymane Wall, having failed to gain entry into the closed kingdom of Gilneas.",al={"where is valdred","valdred location","valdred moray spot"}},{q="Why does Raleigh give back the wedding ring?",a="In undeath, Raleigh's emotional attachment to Deliah has withered away to nothing. Without the capacity for grief or affection, her ring is an empty trinket to him; only the malice of revenge held any real value.",al={"why give ring away","ring of scorn lore","why discard ring"},sp=1},{q="Can Valdred Moray enter Gilneas?",a="No. King Genn Greymane ordered the wall sealed during the Third War to shut out the rest of the world and the Scourge. Valdred, like many desperate refugees, found himself stranded at the locked gates.",al={"greymane wall closed","why is valdred outside wall"}},{q="What quests lead up to this task?",a="The chain begins with finding 'The Engraved Ring' in Hillsbrad Foothills, which directs you to the Undercity in 'Raleigh and the Undercity', unlocking 'A Husband's Revenge'.",al={"husband revenge chain","prerequisite quest","previous quest"}}},ang={["race:Undead"]="Raleigh's cold detachment from his dead wife, paired with his lingering obsession with hatred and vengeance, is a stark portrait of how undeath warps mortal psychology.",["faction:Horde"]="Carrying out justice across Silverpine Forest helps secure the borders around the Undercity against lingering human outlaws."},kw={"deliah","engraved ring","greymane wall","raleigh andrean","ring of scorn","silverpine forest","undercity","valdred moray"},rel={"npc:raleigh-andrean","quest:441","quest:440","subzone:greymane-wall","zone:undercity"},m={start="Raleigh Andrean",level="20",faction="Horde",id=530},src={"A Husband's Revenge"}}
E["quest:550"] = {t="quest",n="Battle of Hillsbrad",z="undercity",s="This mission marks the conclusion of the Forsaken campaign against the human township of Hillsbrad. Having shattered the local Alliance forces, you are sent by High Executor Darthalia to present an official commendation to Varimathras in the Undercity.",h="This mission marks the conclusion of the Forsaken campaign against the human township of Hillsbrad.",sec={{t="A Decisive Campaign",b="The campaign in the Hillsbrad Foothills represents a brutal struggle for southern Lordaeron. Across a protracted series of strikes coordinated from Tarren Mill, Horde champions dismantled the human township's farmers, militia, blacksmiths, and civic leaders. With the Alliance presence crippled and the territory secured for the Forsaken, High Executor Darthalia drafts an official commendation to ensure the executor's exploits reach the highest ranks of command.",sp=0},{t="Audience with the Dreadlord",b="Carrying Darthalia's sealed commendation leads directly to the Royal Quarter of the Undercity, into the presence of Varimathras. Standing alongside Lady Sylvanas Windrunner, the dreadlord oversees military operations across Lordaeron. While the Scourge descending from the northern Plaguelands remains the Dark Lady's paramount existential threat, securing the southern borders against surviving human enclaves is vital for the nascent Forsaken nation.",sp=0}},faq={{q="What is this quest?",a="It is the final turn-in for the extensive Battle of Hillsbrad quest chain. After completing your tasks for High Executor Darthalia at Tarren Mill, she gives you a sealed letter of commendation to deliver personally to Varimathras in the Undercity.",al={"battle of hillsbrad finale","hillsbrad final quest","quest 550"}},{q="Where do I turn in Darthalia's Sealed Commendation?",a="You turn it in to Varimathras, who stands beside Lady Sylvanas Windrunner in the Royal Quarter of the Undercity.",al={"where is varimathras","turn in commendation","darthalia letter turn in"}},{q="Why does Varimathras care about Hillsbrad?",a="As the Dark Lady's chief military lieutenant, Varimathras oversees strategic defense and expansion. Although the Scourge in the north is the Undercity's greatest threat, human settlements to the south constantly harass Forsaken lines. Eliminating the threat in Hillsbrad protects their southern frontier.",al={"why varimathras","varimathras role in hillsbrad"}},{q="Who is High Executor Darthalia?",a="High Executor Darthalia is the senior Forsaken commander stationed at Tarren Mill in the Hillsbrad Foothills, directing the offensive operations against the nearby human settlement.",al={"darthalia","who gave the quest"}},{q="Does this quest lead to further missions in Hillsbrad?",a="No. Delivering the commendation to Varimathras is the official conclusion of the Battle of Hillsbrad storyline, rewarding you for breaking the town's defenses.",al={"next quest after battle of hillsbrad","what comes after quest 550"}},{q="Why were the Forsaken attacking Hillsbrad in the first place?",a="The town of Hillsbrad represents one of the last organized human footholds in Lordaeron. Aligned with the Alliance, its militia and proximity pose an immediate military threat to Tarren Mill and the southern approaches to the Undercity.",al={"why attack hillsbrad","hillsbrad lore"}}},ang={["race:Undead"]="Reporting your victory over the living of Hillsbrad earns direct praise from the Royal Quarter, affirming your place within the Dark Lady's rising empire.",["faction:Horde"]="By driving back Alliance forces in Lordaeron, you secure vital ground for the Horde in the Eastern Kingdoms."},kw={"battle of hillsbrad","darthalia","hillsbrad foothills","royal quarter","sealed commendation","tarren mill","undercity","varimathras"},rel={"npc:varimathras","npc:high-executor-darthalia","zone:hillsbrad","zone:undercity","topic:scourge","topic:alliance","topic:lich-king"},m={start="High Executor Darthalia",["end"]="Varimathras",level="32",faction="Horde",id=550},src={"Battle of Hillsbrad (7) (Classic)"}}
E["quest:5679"] = {t="quest",n="Devouring Plague",z="undercity",s="Devouring Plague is a rite of instruction offered to Forsaken priests who have proven their dedication to shadow magic. Granted by Priestess Aelthalyste in the Undercity, the teaching marks an acolyte's initiation into one of the most dreaded curses woven by the undead priesthood.",h="Devouring Plague is a rite of instruction offered to Forsaken priests who have proven their dedication to...",sec={{t="A Curse of the Shadow",b="In the murky cloisters of the War Quarter, Priestess Aelthalyste guides Forsaken practitioners through the grim arts of the Shadow. While living priests of other races appeal to the Holy Light or ancestral spirits for their power, the Forsaken have forged their own spiritual doctrines. Devouring Plague represents the crystallization of their philosophy: inflicting suffering upon their foes while leeching the stolen vitality back into their own decaying bodies.",sp=0},{t="A Test of Mastery",b="Aelthalyste does not offer the knowledge of the plague lightly. The spell is considered a weapon of potent malice, intended to turn the tide against the Scourge and the Scarlet Crusade. When imparting the spell, Aelthalyste warns her disciples to hone their command over it through relentless practice, cautioning that far greater trials lie ahead for those who seek to master the dark arts.",sp=0}},faq={{q="What is the purpose of this quest?",a="The quest serves as a formal lesson for Forsaken priests reaching seasoned standing. By speaking with Priestess Aelthalyste, the priest is taught how to cast Devouring Plague, a signature shadow affliction unique to undead practitioners.",al={"why do devouring plague","what does devouring plague quest do","devouring plague purpose"}},{q="Who is Priestess Aelthalyste?",a="Priestess Aelthalyste is a Forsaken priest trainer residing in the War Quarter of the Undercity. She oversees the development of emerging shadow casters and ensures they wield their destructive blessings effectively for the Forsaken.",al={"who is aelthalyste","aelthalyste lore","aelthalyste undercity"}},{q="Can priests of other races learn Devouring Plague from Aelthalyste?",a="No. Devouring Plague is an esoteric spell exclusive to Forsaken priests. Trolls, humans, night elves, and dwarves commune with different spiritual forces and possess their own distinct racial teachings instead.",al={"can trolls learn devouring plague","is devouring plague undead only","other races devouring plague"}},{q="Where do I turn in this quest?",a="Priestess Aelthalyste can be found in the War Quarter of the Undercity, lingering among the Forsaken's priest instructors and practitioners.",al={"aelthalyste location","where is devouring plague quest","undercity priest trainer location"}},{q="Why do Forsaken priests specialize in plague and shadow magic?",a="Forsaken priests endure intense physical pain whenever they channel the Holy Light due to their undead state. As a result, many turn toward the teachings of the Shadow, using afflictions, curses, and stolen life-force to survive and wage war.",al={"why forsaken shadow priests","lore behind undead priests","forsaken priest magic"}},{q="What tests is Aelthalyste referring to?",a="Aelthalyste warns that as a priest grows in power, the trials faced across Lordaeron will intensify. Wielding dark magic invites dangerous scrutiny and deadly foes, demanding absolute command over every curse in an acolyte's repertoire.",al={"tests later meaning","future tests aelthalyste","what tests"}}},ang={["class:Priest"]="This rite provides Forsaken priests with one of their most iconic racial spells, binding their survival directly to the affliction they inflict on enemies.",["race:Undead"]="Embracing plague-like shadowcraft reflects the Forsaken's divergence from traditional Lordaeron worship following the Third War.",["faction:Horde"]="While other Horde allies rely on ancestral spirits or elemental balance, the Forsaken bring ruthless, disease-like curses into the faction's collective arsenal."},kw={"aelthalyste","devouring plague","forsaken","lordaeron","priest","shadow","undercity","war quarter"},rel={"npc:aelthalyste","quest:5644"},m={start="Aelthalyste",level="20",faction="Horde",id=5679},src={"Devouring Plague (Undercity)"}}
E["quest:6322"] = {t="quest",n="Michael Garrett",z="undercity",s="Michael Garrett is a simple courier task linking trade in the Undercity with the Forsaken's flight network. After collecting supplies packed by Gordon Wendham in the Trade Quarter, you are directed to deliver the crate to the bat handler Michael Garrett to arrange aerial transport out toward the Sepulcher. It highlights how the Forsaken utilize trained vampire bats to connect their capital with outposts across Lordaeron.",h="Michael Garrett is a simple courier task linking trade in the Undercity with the Forsaken's flight network.",sec={{t="Supplying the Outposts",b="Running a fledgeling kingdom carved out of the ruins of Lordaeron requires constant logistics. Outposts like the Sepulcher in Silverpine Forest rely heavily on goods, munitions, and provisions moving out from the Undercity. Gordon Wendham packs the necessary field supplies into a single crate in the city's Trade Quarter, but carting freight by ground through blighted forests is both slow and vulnerable to ambush by Scourge remnants or wild beasts.",sp=0},{t="Wings of the Forsaken",b="To bypass the dangers on the roads, the Forsaken rely on captive vampire bats bred and maintained by skilled handlers. Michael Garrett oversees these winged beasts from his roost near the entrance of the Undercity. Delivering the cargo to him ensures the supplies can be strapped to a bat and flown directly over the hills to Silverpine, teaching new couriers how the capital coordinates with remote settlements.",sp=0}},faq={{q="Who is Michael Garrett?",a="Michael Garrett is the Undercity's bat handler, stationed in the upper terrace above the subterranean canals near the surface exit. He manages the flight network's vampire bats, arranging travel and air delivery between the Forsaken capital and allied flight masters throughout Lordaeron.",al={"michael garrett","undercity bat master","who is garrett"}},{q="What is in Gordon's Crate?",a="The crate contains vital provisions and field supplies gathered by Gordon Wendham in the Trade Quarter, earmarked specifically for the Forsaken forces stationed at the Sepulcher in Silverpine Forest.",al={"gordon's crate","what supplies","sepulcher crate"}},{q="Why use bats instead of carts or horses?",a="The overland roads winding out of Tirisfal Glades into Silverpine Forest are fraught with hazards, including roaming Scourge beasts, hostile humans, and treacherous terrain. Flying routes overhead via trained giant bats are drastically faster and completely bypass ground ambushes.",al={"why bat flight","why use bats","flying supplies"}},{q="Where does the delivery go after Michael Garrett?",a="Once Michael Garrett receives Gordon's Crate, the cargo is prepped to fly by bat directly to the bat master stationed at the Sepulcher in Silverpine Forest, completing the logistics chain.",al={"next step","after michael garrett","where do bats fly"}},{q="Where can Michael Garrett be found in Undercity?",a="He is located on the upper terrace near the main entrance leading out toward the surface ruins of Lordaeron, where the cavernous ceilings open enough for flying mounts to take wing.",al={"where is garrett","find bat handler","undercity flight master location"}},{q="Do you need to have visited the Sepulcher before doing this?",a="To ride a bat yourself alongside the delivery, you must have previously spoken with the flight handler at the Sepulcher to unlock the aerial route; otherwise, you will have to travel there by foot.",al={"sepulcher flight path required","can i fly immediately"}}},ang={["race:Undead"]="Understanding the aerial supply line run by handlers like Michael Garrett is essential for maintaining Sylvanas's presence beyond Tirisfal Glades.",["faction:Horde"]="For travelers arriving from Kalimdor, the Forsaken bat network serves as the primary mode of rapid transit across the northern Eastern Kingdoms."},kw={"bat master","flight master","gordon wendham","gordon's crate","michael garrett","sepulcher","silverpine","undercity"},rel={"npc:gordon-wendham","zone:undercity","subzone:sepulcher","quest:6324"},m={start="Gordon Wendham",["end"]="Michael Garrett",level="10",faction="Horde",id=6322},src={"Michael Garrett (Classic)"}}
E["quest:6323"] = {t="quest",n="Ride to the Undercity",z="undercity",s="Ride to the Undercity introduces fledgling Forsaken adventurers to the Horde's aerial flight network across Lordaeron. Carrying weapon requisitions from the embattled outpost of the Sepulcher, couriers take a dread bat directly into the Undercity's Trade Quarter to resupply regional defenders.",h="Ride to the Undercity introduces fledgling Forsaken adventurers to the Horde's aerial flight network across...",sec={{t="Wings Over Silverpine",b="Maintaining lines of communication between the Forsaken capital and its frontline outposts requires swift, reliable transit. Karos Razok, the bat handler stationed at the Sepulcher in Silverpine Forest, manages the trained dread bats that ferry messengers and supplies across the plagued landscape. With roads crawling with hostile beasts, Moonrage worgen, and remnants of the Scourge, taking to the skies is the safest and fastest way to ensure urgent military requests reach the capital.",sp=0},{t="Arming the Front",b="Upon touching down in the Undercity's bustling Trade Quarter, the courier delivers Podrig's equipment requisition directly to Gordon Wendham. As an Undercity weaponsmith dedicated to the Dark Lady's cause, Wendham ensures that regional outposts like the Sepulcher remain outfitted with clean, battle-ready armaments. Sustaining these defensive hubs is vital for the fledgling Forsaken nation as it secures its borders against surrounding enemies.",sp=0}},faq={{q="What is the purpose of this flight to the Undercity?",a="The mission serves to deliver an official weapons requisition from Deathguard Podrig at the Sepulcher directly to Gordon Wendham, an armorer working in the Trade Quarter of the Undercity, while teaching new champions how to use the Forsaken flight network.",al={"why ride to undercity","ride to the undercity objective","podrig's order use"}},{q="Who is Karos Razok?",a="Karos Razok is the bat master stationed at the Sepulcher in Silverpine Forest. He oversees the roost of dread bats used by the Forsaken to maintain rapid travel and communication with the Undercity.",al={"karos razok role","who is the sepulcher bat master"}},{q="Who is Gordon Wendham?",a="Gordon Wendham is a Forsaken weapon crafter located in the Trade Quarter of the Undercity, right near the bat handler's landing platform. He takes pride in keeping weapons cleaned, sharpened, and ready for Lady Sylvanas's frontline forces.",al={"gordon wendham","where is gordon wendham"}},{q="Why do the Forsaken use bats for transit?",a="Dread bats are native nocturnal predators well-suited to Lordaeron's blighted skies. They provide swift passage above treacherous ground hazards such as feral worgen, hostile rot hides, and the Scourge.",al={"why bats","forsaken flight mounts"}},{q="What happens after completing the delivery?",a="After receiving the order, Gordon Wendham directs couriers to Michael Garrett, the Undercity bat handler, establishing a return flight path back toward the Sepulcher.",al={"what comes next","follow up to ride to the undercity"}},{q="Where does the dread bat land in the Undercity?",a="The dread bat lands on the raised bat roost perched directly in the center of the Undercity's Trade Quarter, providing immediate access to the city's craftsmen and supply merchants.",al={"undercity bat landing","where does bat land"}}},ang={["race:Undead"]="Taking wing from Silverpine to the capital highlights the reach and organization of the Dark Lady's network, ensuring isolated garrisons are never cut off from Undercity's industry.",["profession:Blacksmithing"]="Delivering orders to Gordon Wendham offers smiths a look at the logistical spine of Lordaeron, where every piece of iron is kept sharp and ready for war.",["faction:Horde"]="Flight masters form the essential connective tissue of the Horde's territorial expansion, turning arduous wilderness treks into rapid tactical deployments."},kw={"dread bat","flight master","gordon wendham","karos razok","podrig's order","ride to the undercity","sepulcher","trade quarter"},rel={"npc:karos-razok","npc:gordon-wendham","zone:undercity","subzone:trade-quarter","subzone:sepulcher","quest:6321"},m={start="Karos Razok",["end"]="Gordon Wendham",level="10",faction="Horde",id=6323},src={"Ride to the Undercity (Classic)"}}
E["quest:6324"] = {t="quest",n="Return to Podrig",z="undercity",s="Return to Podrig is a logistics quest concluding a courier run between Silverpine Forest and the Undercity. After delivering a dispatch to the capital, the courier is entrusted with a crate of weapons to ferry back to Deathguard Podrig at the Sepulcher using the Forsaken bat handler network.",h="Return to Podrig is a logistics quest concluding a courier run between Silverpine Forest and the Undercity.",sec={{t="The Undercity Supply Line",b="Outposts throughout Lordaeron depend heavily on regular shipments from the Undercity to remain operational. At the Sepulcher in Silverpine Forest, Deathguard sentries face pressure from local worgen, Dalaran remnants, and Scourge stragglers. Supplying remote garrisons with freshly forged armaments is vital to holding the region under Forsaken control.",sp=0},{t="Wings of the Forsaken",b="Bat Master Michael Garrett operates the central roost in the Undercity courtyard, serving as the hub for Forsaken aerial travel. While bats naturally return to the capital, riders must first coordinate with local handlers like Karos Razok before flights to distant outposts can be charted. Flying Gordon's Crate across Lordaeron's skies teaches couriers how the Forsaken bind their scattered strongholds together.",sp=0}},faq={{q="What is in Gordon's Crate?",a="The crate contains fresh weapons produced in the Undercity to keep the Deathguards stationed at the Sepulcher properly equipped against surrounding threats.",al={"gordons crate contents","what am i delivering to podrig"}},{q="Who is Deathguard Podrig?",a="Deathguard Podrig is a Forsaken soldier stationed at the Sepulcher in Silverpine Forest who oversees logistical and defense duties for the local garrison.",al={"podrig","who is podrig"}},{q="Who is Michael Garrett?",a="Michael Garrett is the Forsaken bat master stationed in the upper courtyard of the Undercity, responsible for coordinating flight paths across Lordaeron.",al={"michael garrett","undercity bat master"}},{q="Why do you have to speak to a bat master before flying somewhere?",a="Forsaken bats naturally know the way back to the central roost in the Undercity, but outward flights require establishing a route with a regional handler first to ensure safe arrival.",al={"flight path rules","how do bat handlers work"}},{q="Why is the Sepulcher so important to supply?",a="The Sepulcher is the Forsaken's main forward base in Silverpine Forest. It anchors their military presence against worgen packs, Moonrage threats, and Dalaran forces in the area.",al={"why sepulcher matters","sepulcher importance"}},{q="Who is Karos Razok?",a="Karos Razok is the bat master stationed at the Sepulcher in Silverpine Forest, managing roosted bats that connect the outpost to the Undercity.",al={"karos razok","sepulcher bat master"}}},ang={["race:Undead"]="Keeping forward garrisons armed is essential to defending Lordaeron and securing Queen Sylvanas's fledgling realm.",["faction:Horde"]="This task demonstrates the logistical framework connecting the Undercity to remote outposts across the northern continent."},kw={"bat master","gordons crate","karos razok","michael garrett","podrig","sepulcher","silverpine","undercity"},rel={"quest:6322","zone:undercity","subzone:sepulcher","npc:karos-razok"},m={start="Michael Garrett",["end"]="Deathguard Podrig",level="10",faction="Horde",id=6324},src={"Return to Podrig"}}
E["quest:8354"] = {t="quest",n="Chicken Clucking for a Mint",z="undercity",s="During the festive season of Hallow's End, Innkeeper Norman of the Undercity offers a piece of candy to travelers helping an ailing child. To earn the Undercity Mint, adventurers must cast aside their dignity and flap about like a chicken.",h="During the festive season of Hallow's End, Innkeeper Norman of the Undercity offers a piece of candy to...",sec={{t="A Rare Bit of Mirth",b="The Undercity is rarely known for laughter or warmth, built as it is beneath the ruins of Lordaeron by the liberated Forsaken. Yet when Hallow's End arrives, even the grim denizens of the Trade Quarter join in seasonal revelry. Innkeeper Norman holds onto a stash of Undercity Mints, designated for those collecting treats on behalf of young Spoops, a sick orphan in need of holiday cheer.",sp=0},{t="Earning the Treat",b="Rather than surrendering the treat outright to seasoned adventurers, Norman demands a bit of humiliating spectacle. Believing that grown warriors and spellcasters ought to earn their confections, he refuses to part with the mint until the petitioner mimics a barnyard chicken right before his counter.",sp=0}},faq={{q="Why does Innkeeper Norman want me to cluck like a chicken?",a="Innkeeper Norman believes grown champions are too old to go around trick-or-treating without putting on a show. To lighten the mood during Hallow's End, he demands a ridiculous performance—flapping and clucking like a chicken—before he will hand over his holiday treat.",al={"why chicken emote","why cluck norman","norman chicken dance"}},{q="Who is the treat intended for?",a="The Undercity Mint is collected on behalf of Spoops, a sick orphan resting in Orgrimmar who is unable to go trick-or-treating himself during the Hallow's End festival.",al={"who gets the mint","what is the mint for","why get undercity mint"}},{q="Where is Innkeeper Norman located?",a="Innkeeper Norman operates the central tavern within the Trade Quarter of the Undercity, serving Forsaken patrons and visiting Horde travelers.",al={"norman location","where is undercity innkeeper"}},{q="Is this a seasonal festival quest?",a="Yes. This quest is part of the annual Hallow's End holiday celebrations celebrated across Azeroth by both Horde and Alliance.",al={"is this hallows end","when is this quest available"}},{q="Do Forsaken normally celebrate Hallow's End?",a="The Forsaken celebrate Hallow's End with great enthusiasm, burning a massive wicker man outside the ruins of Lordaeron to commemorate their liberation and break with their former mortal lives.",al={"forsaken hallows end","undead holiday"}},{q="What happens after getting the Undercity Mint?",a="The mint is combined with other signature treats gathered from the various Horde racial capitals to assemble a full holiday gift for young Spoops.",al={"next quest","what do i do with the mint"}}},ang={["race:Undead"]="Finding silly humor among the rotting halls of the Undercity is rare, making Norman's seasonal demand a bizarre break from daily necromantic pragmatism.",["faction:Horde"]="Horde adventurers travel between every capital city during Hallow's End, braving foolish indignities in each to bring joy to an orphaned child."},kw={"chicken","cluck","hallow's end","innkeeper norman","spoops","trade quarter","undercity","undercity mint"},rel={"npc:innkeeper-norman","zone:undercity"},m={start="Innkeeper Norman",faction="Horde",id=8354},src={"Chicken Clucking for a Mint (Horde)"}}
E["quest:8648"] = {t="quest",n="Darkcore the Elder",z="undercity",s="Darkcore the Elder is a seasonal quest encountered during the Lunar Festival within the Undercity. By seeking out Elder Darkcore, travelers pay homage to the ancient spirits honored across Azeroth and receive a Coin of Ancestry in return.",h="Darkcore the Elder is a seasonal quest encountered during the Lunar Festival within the Undercity.",sec={{t="A Spirit in the Undercity",b="During the Lunar Festival, spirits of ancient night elven and earthen ancestors appear throughout the continents to share their wisdom and blessings. Elder Darkcore resides in the shadowed halls of the Undercity, bearing witness to the modern realm while offering remembrance to those who seek out the roots of the world.",sp=0},{t="Honoring the Ancestors",b="Approaching Elder Darkcore satisfies an ancient custom of showing respect to the venerable dead and the timeless wardens of Azeroth. In recognition of this pilgrimage, the spirit gifts travelers a Coin of Ancestry as a token of goodwill and enduring memory.",sp=0}},faq={{q="What is the purpose of visiting Elder Darkcore?",a="Visiting Elder Darkcore during the Lunar Festival allows adventurers to pay homage to the ancient peoples of Azeroth. Speaking with him completes the quest and earns a Coin of Ancestry.",al={"elder darkcore goal","why visit darkcore","darkcore quest purpose"}},{q="Where can Elder Darkcore be found?",a="Elder Darkcore manifests inside the Undercity, standing among the somber subterranean avenues of the Forsaken capital.",al={"elder darkcore location","where is elder darkcore","darkcore undercity spot"}},{q="What is the Lunar Festival?",a="The Lunar Festival is an annual season of remembrance and renewal observed across Azeroth, celebrating the triumph over the Burning Legion and paying reverence to ancient elders who guided mortal races.",al={"lunar festival lore","why are elders appearing","what are the elders"}},{q="What do the elders represent?",a="Elders are ancient spirits, typically linked to the night elves or early earthen cultures, who emerge during the Lunar Festival to bless those who remember their deeds and carry forward the lessons of antiquity.",al={"who are the elders","lunar festival elders lore","ancestor spirits"}},{q="Can Alliance adventurers speak to Elder Darkcore?",a="Elder Darkcore will greet any traveler who manages to reach him, though Alliance players must brave the heavily defended Forsaken capital to do so.",al={"alliance darkcore","can alliance get darkcore","elder darkcore alliance"}},{q="What is a Coin of Ancestry?",a="A Coin of Ancestry is a festive token bestowed by elders during the Lunar Festival, symbolizing reverence for antiquity and tradable for festive garb and seasonal keepsakes.",al={"what are coins of ancestry","coin of ancestry use","lunar festival coin"}}},ang={["race:Undead"]="For the Forsaken walking through the ruins of their former kingdom, Elder Darkcore offers an eerie reminder of older times before the Scourge and the fall of Lordaeron.",["faction:Horde"]="Elder Darkcore allows members of the Horde to partake in the continent-wide rites of the Lunar Festival directly within the safety of an allied capital."},kw={"ancestor","coin of ancestry","darkcore the elder","elder darkcore","elders","lunar festival","undercity"},rel={"npc:elder-darkcore"},m={start="Elder Darkcore",id=8648},src={"Darkcore the Elder"}}
E["quest:9189"] = {t="quest",n="Delivery to the Sepulcher",z="undercity",s="Delivery to the Sepulcher concludes the fateful journey that brought Sylvanas Windrunner's long-lost necklace to the Undercity. Following an emotional encounter with the Banshee Queen, Ambassador Sunsorrow directs blood elf travelers to ferry sealed orders south into Silverpine Forest. The errand connects elven diplomats in the capital with their field representatives assisting the Forsaken.",h="Delivery to the Sepulcher concludes the fateful journey that brought Sylvanas Windrunner's long-lost necklace...",sec={{t="Diplomatic Footwork",b="After presenting Lady Sylvanas Windrunner with her family heirloom, elven adventurers are swiftly redirected to matters of state. Ambassador Sunsorrow, the sin'dorei emissary stationed within the Royal Quarter, uses the moment to send critical instructions to the field. Rather than remaining amidst the gloomy halls of Undercity, the courier is sent south into Silverpine Forest carrying Sealed Sin'dorei Orders meant for Advisor Sorrelon.",sp=0},{t="A Precarious Alliance",b="The destination is the Sepulcher, a weathered crypt repurposed into the Forsaken's main staging ground in northern Silverpine. For the high-minded sin'dorei, operating out of a dilapidated burial site alongside undead allies is an unsettling reality of their new geopolitical position. Advisor Sorrelon represents Quel'Thalas among these troops, tasked with observing Forsaken military efforts and ensuring blood elf wanderers maintain good conduct to protect their fledgling alliance with the Horde.",sp=0}},faq={{q="Why does Ambassador Sunsorrow send me away from Undercity?",a="Following the stir caused by returning the necklace to Lady Sylvanas, Ambassador Sunsorrow needs sealed instructions carried to Advisor Sorrelon in Silverpine Forest. It serves both as a practical courier duty and a diplomatic posting for blood elf champions eager to prove their worth to the Horde.",al={"why go to sepulcher","sunsorrow errand","why leave undercity"}},{q="What is the Sepulcher?",a="The Sepulcher is a ruined human crypt in northern Silverpine Forest that the Forsaken have turned into a regional command post and outpost. Despite its squalid and decaying appearance, it serves as a central hub for coordinating local defense and supply lines.",al={"where is the sepulcher","what kind of place is sepulcher","sepulcher lore"}},{q="Who is Advisor Sorrelon?",a="Advisor Sorrelon is an elven official stationed at the Sepulcher who represents Quel'Thalas to the Forsaken forces in Silverpine. He manages regional interests and monitors sin'dorei travelers assisting in local military matters.",al={"sorrelon lore","who is sorrelon","advisor sorrelon silverpine"}},{q="How does Sorrelon view the interaction with Sylvanas?",a="Sorrelon acknowledges the difficult encounter with Lady Sylvanas, noting that while the Banshee Queen's reaction was cold and haughty, returning her lost necklace was honorable. He warns travelers not to brood over royal temperaments and to focus on maintaining smooth ties with the Horde.",al={"sorrelon reaction sylvanas","necklace aftermath","what does sorrelon say"}},{q="What is inside the Sealed Sin'dorei Orders?",a="The sealed parchment carries Ambassador Sunsorrow's official recommendations and tactical instructions regarding blood elf involvement in Silverpine, noting the adventurer's loyalty and potential as a credit to the sin'dorei.",al={"what are the orders","sealed orders","sin'dorei orders contents"}},{q="How should a courier travel to the Sepulcher?",a="The quickest standard path without boarding a flight master's bat is to exit the Undercity through the ruins of Lordaeron, travel west through Tirisfal Glades, and follow the road south into Silverpine Forest past the regional signposts.",al={"directions to sepulcher","how to get to sepulcher"}}},ang={["faction:Horde"]="The delivery highlights the fragile yet burgeoning bond between Quel'Thalas and the Horde, where early diplomatic missions rely heavily on showing deference and cooperation to the Forsaken.",["race:Undead"]="While elven diplomats find places like the Sepulcher squalid and strange, the Forsaken depend on such fortified tombs to hold Silverpine against regional threats."},kw={"advisor sorrelon","ambassador sunsorrow","delivery to the sepulcher","sepulcher","silverpine forest","sin'dorei orders","sylvanas","the lady's necklace","undercity"},rel={"npc:ambassador-sunsorrow","subzone:sepulcher","zone:silverpine","zone:undercity","topic:forsaken","topic:horde"},m={start="Ambassador Sunsorrow",["end"]="Advisor Sorrelon",level="15",faction="Horde",id=9189},src={"Delivery to the Sepulcher"}}
E["quest:9265"] = {t="quest",n="Investigate the Scourge of the Undercity",z="undercity",s="Lieutenant Rukag dispatches Horde defenders to combat the Scourge forces that have dared to encamp outside the Undercity. Agents are tasked with investigating ominous, glowing runic circles linked to the dread necropolis overhead and retrieving Dim Necrotic Stones as proof of their destruction.",h="Lieutenant Rukag dispatches Horde defenders to combat the Scourge forces that have dared to encamp outside...",sec={{t="On the Doorstep",b="The Scourge invasion pushes right to the gates of Lordaeron's fallen capital. Rather than hiding behind the fortified gates of the Undercity, Horde commanders like Lieutenant Rukag organize an immediate counter-offensive to eradicate the encroaching dead before they can mount an assault.",sp=0},{t="Necrotic Relics",b="Outside the citadel, the Scourge have erected glowing runic circles pulsing with foul necromantic energies that resonate with the floating necropolises darkening the skies. Defeating these Scourge trespassers yields Dim Necrotic Stones, dark focuses used to fuel their terrifying rituals and sustain their unnatural march.",sp=0}},faq={{q="Who orders the investigation outside the Undercity?",a="Lieutenant Rukag, a Horde officer stationed to defend the Undercity, commands warriors to investigate the growing Scourge presence outside the gates and cut down their forces.",al={"who gives investigate the scourge","lieutenant rukag","rukag undercity"}},{q="What are Dim Necrotic Stones?",a="Dim Necrotic Stones are shadowy magical artifacts carried by the invading Scourge. They hum with foul necromancy and serve as proof of their demise when returned to Horde officers.",al={"what are necrotic stones","dim necrotic stone","scourge stones"}},{q="What are the glowing runic circles?",a="They are ritualistic circles scribed upon the ground by the Scourge encampments, radiating the same dark magic that shields and sustains the necropolis looming overhead.",al={"runic circles outside undercity","glowing circle scourge","scourge runes"}},{q="Why is the Scourge attacking outside the Undercity?",a="The Lich King seeks to eradicate the renegade Forsaken and conquer the ruins of Lordaeron, deploying necropolises and ground troops to besiege the capital directly.",al={"why is scourge at undercity","scourge invasion undercity","undercity under attack"}},{q="Why does this matter to the Forsaken?",a="The Forsaken fought tirelessly to break free of the Lich King's iron will. The Scourge landing at their very threshold threatens the freedom and sovereignty of their fledgling nation.",al={"forsaken scourge threat","undead defending undercity"}},{q="Can non-Forsaken Horde members take this mission?",a="Yes. All members of the Horde are summoned to aid in Lordaeron's defense, as a threat to the Undercity threatens the security of the entire coalition.",al={"can orcs do this quest","horde defense undercity"}}},ang={["race:Undead"]="The Scourge represents your former master and perpetual enslaver; repelling them from Lordaeron's soil is a matter of pure survival and vengeance.",["faction:Horde"]="Honor demands coming to the defense of the Forsaken, securing the Horde's vital foothold in the Eastern Kingdoms against the Scourge."},kw={"dim necrotic stone","lordaeron","necropolis","rukag","runic circle","scourge","undercity"},rel={"zone:undercity","topic:scourge"},m={start="Lieutenant Rukag",level="8",faction="Horde",id=9265},src={"Investigate the Scourge of the Undercity"}}
E["quest:9425"] = {t="quest",n="Report to Tarren Mill",z="undercity",s="Report to Tarren Mill is a diplomatic dispatch directing Sin'dorei champions into the contested territories of Lordaeron. Commissioned by Ambassador Sunsorrow in the Undercity, it urges blood elf travelers to offer their aid to the Forsaken garrison at Tarren Mill. By proving their worth in foreign theaters of war, the blood elves hope to secure vital Horde goodwill and resources.",h="Report to Tarren Mill is a diplomatic dispatch directing Sin'dorei champions into the contested territories...",sec={{t="A Diplomatic Calculus",b="The blood elves stand as recent arrivals within the Horde, and their foothold remains fragile. In the royal corridors of the Undercity, Ambassador Sunsorrow understands that alliances are forged in blood, not merely ratified on parchment. To earn the full, active support of the Horde—and particularly the dark lady's Forsaken, who share northern kinship—the Sin'dorei must take up the mantle of their allies' regional conflicts. Directing capable adventurers into the field demonstrates that Silvermoon is a potent partner rather than a dependent supplicant.",sp=0},{t="The Southern Outpost",b="South across the Silverpine border and past the ruins of Lordaeron lies the Hillsbrad Foothills, where the Forsaken stronghold of Tarren Mill holds the line against regional enemies. It is here that Advisor Duskingdawn coordinates blood elf interests alongside Forsaken commanders. Arriving travelers are integrated directly into the town's operations, aiding the undead war effort against hostile human militia, Syndicate rogue elements, and Alliance incursions along the southern frontier.",sp=0}},faq={{q="Why is Ambassador Sunsorrow sending blood elves to Tarren Mill?",a="Sunsorrow seeks to cement the newly formed bond between Silvermoon and the Horde. By assisting the Forsaken directly with their defensive and strategic struggles in the Hillsbrad Foothills, the blood elves build reciprocal trust and ensure the Horde will aid them in their own homeland.",al={"why tarren mill","sunsorrow motive","why are elves sent to hillsbrad"}},{q="Who is Advisor Duskingdawn?",a="Advisor Duskingdawn is a blood elf representative stationed at Tarren Mill in Hillsbrad Foothills. He oversees incoming Sin'dorei forces and directs them toward Forsaken commanders and local tasks that benefit the mutual war effort.",al={"who is duskingdawn","advisor duskingdawn identity"}},{q="Where is Tarren Mill located?",a="Tarren Mill is a primary Forsaken bastion located in the northern region of the Hillsbrad Foothills, situated southeast of Silverpine Forest and south of the Alterac Mountains.",al={"tarren mill location","how to get to tarren mill"}},{q="What threats face the Horde in Hillsbrad Foothills?",a="Tarren Mill faces immediate pressure from the human town of Southshore, remnants of the Syndicate hiding in ruins, aggressive wild beasts, and regional skirmishes for control of the foothills.",al={"hillsbrad enemies","dangers in tarren mill"}},{q="Why are the Forsaken and blood elves particularly aligned?",a="Both peoples share deep historical ties to the northern lands of Lordaeron and Quel'Thalas, having both suffered catastrophic devastation at the hands of the Scourge during the Third War. These shared wounds and geographical proximity foster practical cooperation.",al={"forsaken blood elf alliance","why do elves work with undead"}},{q="Does this mission involve combat immediately upon arrival?",a="The mission itself is purely travel and introduction. However, once you report to Advisor Duskingdawn, he encourages you to seek out local Forsaken officers who urgently require combat assistance across Hillsbrad.",al={"is report to tarren mill dangerous","combat in tarren mill quest"}}},ang={["faction:Horde"]="This mission exemplifies the practical diplomacy required to unite distant kingdoms under the banner of the Horde, trading martial service for coalition support.",["race:Undead"]="For the Forsaken, every arriving elven recruit strengthens the bulwark at Tarren Mill against nearby Southshore and lurking Syndicate outlaws."},kw={"blood elf","diplomacy","duskingdawn","forsaken","hillsbrad","sunsorrow","tarren mill","undercity"},rel={"subzone:tarren-mill","npc:ambassador-sunsorrow","npc:advisor-duskingdawn","zone:hillsbrad","topic:forsaken","topic:horde"},m={start="Ambassador Sunsorrow",["end"]="Advisor Duskingdawn",level="20",faction="Horde",id=9425},src={"Report to Tarren Mill"}}
E["quest:9621"] = {t="quest",n="Envoy to the Horde",z="undercity",s="Envoy to the Horde marks a pivotal diplomatic journey for the blood elves following the defeat of the traitor Dar'Khan Drathir. Entrusted with a missive from Regent Lord Lor'themar Theron, an emissary travels from Quel'Thalas to the Undercity to deliver proof of Sin'dorei strength directly to Lady Sylvanas Windrunner.",h="Envoy to the Horde marks a pivotal diplomatic journey for the blood elves following the defeat of the traitor...",sec={{t="Proving Sin'dorei Worth",b="Before this mission, prospective allies in the Horde harbored grave doubts regarding the blood elves' martial prowess. Besieged by the Scourge and struggling to pacify the Ghostlands, Quel'Thalas appeared fragile and incapable of resolving its own domestic crises. The downfall of Dar'Khan Drathir completely upended this dynamic. By eliminating the arch-traitor who orchestrated the fall of the Sunwell, the Sin'dorei demonstrated they could reclaim their homelands and enter the Horde not as desperate supplicants, but as powerful equals.",sp=0},{t="Audience with the Banshee Queen",b="Lor'themar Theron directs his messenger southwest across the blighted lands to the Undercity, the subterranean capital of the Forsaken in Tirisfal Glades. Lady Sylvanas Windrunner, once the Ranger-General of Silvermoon who gave her life defending Quel'Thalas, serves as the blood elves' greatest advocate among the Horde's leadership. Presenting Lor'themar's letter to her confirms Dar'Khan's demise and paves the way for further overtures to Warchief Thrall in distant Orgrimmar.",sp=0}},faq={{q="Why is Lor'themar Theron sending an emissary to Sylvanas?",a="Sylvanas Windrunner is already sympathetic to the plight of Quel'Thalas and acts as the blood elves' primary sponsor within the Horde. Delivering proof of Dar'Khan Drathir's death allows her to advocate for their formal admittance into the Horde with undeniable proof of their strength.",al={"why visit sylvanas","envoy to the horde purpose","why send letter to undercity"}},{q="Who was Dar'Khan Drathir and why does his death matter?",a="Dar'Khan Drathir was the high elf traitor who sold out Silvermoon's magical defenses to Arthas and the Scourge during the Third War. Eliminating him in the Ghostlands broke the Scourge's local command and proved the Sin'dorei could handle their own domestic threats.",al={"why is darkhan death important","who was darkhan","dar'khan significance"}},{q="Where does this diplomatic mission lead next?",a="Upon receiving Lor'themar's letter, Sylvanas directs the emissary across the Great Sea to Kalimdor, specifically to Orgrimmar, to present the blood elves' case before Warchief Thrall and the orcish leadership.",al={"what quest comes after envoy to the horde","where do I go after undercity","next stop after sylvanas"}},{q="Why were the Horde hesitant to ally with the blood elves?",a="The leaders of the Horde doubted whether the blood elves could contribute meaningfully to an alliance when they appeared unable to drive out the remnants of the Scourge from their own ruined kingdom.",al={"why did horde doubt blood elves","horde doubts sin'dorei","why were orcs skeptical"}},{q="How does this missive affect relations with the Darkspear trolls?",a="Sylvanas notes that Lor'themar's letter contains additional tidings designed to soothe long-standing animosity between the elves and the trolls, improving relations as the blood elves seek entry into the Horde.",al={"troll relations blood elf","what does this have to do with trolls","lor'themar letter trolls"}},{q="What is Sylvanas's personal stake in this news?",a="In life, Sylvanas was the Ranger-General of Silvermoon who fell fighting the Scourge brought in by Dar'Khan's treason. Hearing that the traitor has met his end is deeply satisfying to her both politically and personally.",al={"why does sylvanas care about darkhan","sylvanas reaction to darkhan","sylvanas and quel'thalas"}}},ang={["faction:Horde"]="This mission forms the cornerstone of the Sin'dorei petition to join the Horde, providing the leverage needed to secure a formal alliance with Orgrimmar and Undercity.",["race:Undead"]="The Forsaken view the blood elves as crucial northern allies, and Sylvanas personally champions their inclusion in the greater Horde council.",["race:Troll"]="Centuries of bitter conflict between elves and trolls make this diplomatic step fraught, requiring Lor'themar to include delicate concessions to appease the Darkspear."},kw={"dar'khan drathir","envoy to the horde","lor'themar theron","quel'thalas","silvermoon","sin'dorei","sylvanas windrunner","undercity"},rel={"npc:lor-themar-theron","npc:sylvanas-windrunner","zone:undercity","zone:tirisfal","zone:orgrimmar","topic:horde","topic:forsaken","topic:troll"},m={start="Lor'themar Theron",["end"]="Lady Sylvanas Windrunner",faction="Horde",id=9621},src={"Envoy to the Horde (blood elf)"}}
E["quest:9626"] = {t="quest",n="Meeting the Orcs",z="undercity",s="Meeting the Orcs is an audience in Orgrimmar arranged by Lady Sylvanas Windrunner to advance Silvermoon's petition to join the Horde. Carrying a personally endorsed letter from the Banshee Queen, an envoy travels from the Undercity across the sea to present the sin'dorei cause directly to the leadership in Durotar. It represents a pivotal diplomatic step in forging a formal pact between Quel'Thalas and the wider Horde.",h="Meeting the Orcs is an audience in Orgrimmar arranged by Lady Sylvanas Windrunner to advance Silvermoon's...",sec={{t="A Queen's Endorsement",b="Even in undeath, Lady Sylvanas Windrunner retains a fierce protective bond with her former homeland of Quel'Thalas. Championing the blood elves' admission into the Horde, she personally endorses their diplomatic outreach to overcome the hesitation of the other member races. By sending an emissary from Silvermoon with a letter bearing her own seal, the Dark Lady aims to force the Orcish leadership to take the sin'dorei plea seriously.",sp=0},{t="Crossing to Kalimdor",b="The diplomatic mission requires leaving the gloomy vaults of the Undercity and taking a zeppelin across the Great Sea to the sun-baked canyons of Durotar. Presenting credentials to the warlords in Orgrimmar is not a mere formality: the orcs are culturally and geographically distant from the Quel'Thalas plight, harboring deep skepticism regarding the magical practices and historical loyalties of the high elves who once opposed them.",sp=0},{t="Skepticism in the Valley of Strength",b="Upon arrival in Orgrimmar, the bearer of the sealed letter finds a leadership guarded against easy alliances. While acknowledging Sylvanas's tenacity in lobbying for her kin, the orcish command remains cautious. Reading the Dark Lady's missive, the leadership questions whether the appearance of a single elven champion is truly enough to shift the strategic calculations of the entire Horde.",sp=1}},faq={{q="Why is Sylvanas helping the blood elves join the Horde?",a="Sylvanas Windrunner was the Ranger-General of Silvermoon in life and fell defending her people from the Scourge. Despite her undeath and transformation into the Banshee Queen, she still cares for Quel'Thalas and has fought fiercely to give Silvermoon a seat at the Horde's negotiating table alongside Undercity and Orgrimmar.",al={"sylvanas blood elves","why sylvanas helps silvermoon","banshee queen motives"}},{q="Where does this diplomatic journey lead?",a="The mission begins in the Royal Quarter of the Undercity and leads northwest to the zeppelin tower outside the ruins of Lordaeron. From there, the zeppelin carries travelers across the sea directly to Durotar, landing outside the gates of Orgrimmar.",al={"where do i go","how to get to orgrimmar","turn in location"}},{q="Why are the orcs hesitant to accept the blood elves?",a="The orcs fought the high elves in the Second War and know little of their recent rebirth as the sin'dorei. Orcish culture prizes physical martial prowess and honor, making them cautious of distant, magic-reliant kingdoms whose loyalties and struggles are unfamiliar to the clans in Kalimdor.",al={"why orcs distrust elves","orcs blood elves alliance","orc skepticism"}},{q="What is inside the letter carried to Orgrimmar?",a="The missive contains Lady Sylvanas Windrunner's formal and personal endorsement of Silvermoon's pledge. It outlines the sin'dorei petition for membership in the Horde, backed by the Dark Lady's insistence that Quel'Thalas would be a valuable strategic partner.",al={"sylvanas letter contents","sealed letter sylvanas","what is the letter"}},{q="Who receives the diplomatic letter in Orgrimmar?",a="The letter is brought before the highest leadership of the orcs residing in the Valley of Strength in Orgrimmar, where the letter's merits and Sylvanas's persistent lobbying are judged by the clan leaders.",al={"who do i turn this in to","meeting the orcs turn in","orgrimmar recipient"}},{q="What follows after delivering the letter?",a="Delivering the endorsement leads directly to the question of formal allegiance, requiring the leadership in Orgrimmar to determine whether to accept Silvermoon's pledge and grant the sin'dorei full standing within the Horde.",al={"next quest","what happens next","after meeting the orcs"}}},ang={["faction:Horde"]="This embassy marks a critical expansion of the Horde's influence into the Eastern Kingdoms, bridging the gap between the Kalimdor clans and the ancient kingdom of Quel'Thalas.",["race:Undead"]="For the Forsaken, bringing Silvermoon into the fold secures a vital northern ally on their border, easing their isolation amidst the hostile Scourge and Scarlet Crusade.",["race:Orc"]="Orcs view the petition through the lens of honor and strength, skeptical of whether the arcane-reliant elves can pull their weight alongside the warriors of Durotar."},kw={"blood elf","durotar","meeting the orcs","orgrimmar","saurfang","silvermoon","sin'dorei","sylvanas","undercity"},rel={"npc:sylvanas-windrunner","zone:undercity","zone:orgrimmar","zone:durotar","npc:thrall","npc:vol-jin"},m={start="Lady Sylvanas Windrunner",["end"]="High Overlord Saurfang",faction="Horde",id=9626},src={"Meeting the Orcs (blood elf)"}}
E["subzone:apothecarium"] = {t="subzone",n="Apothecarium",z="undercity",s="The Apothecarium is the southwestern quarter of the Undercity and the headquarters of the Royal Apothecary Society. Within these noxious laboratories, Forsaken alchemists labor tirelessly under Master Apothecary Faranell to concoct virulent plagues, toxins, and engineered horrors. It stands as the grim heart of Undercity's biological research, vital to Lady Sylvanas's campaign against the living and the Scourge.",h="The Apothecarium is the southwestern quarter of the Undercity and the headquarters of the Royal Apothecary...",sec={{t="Chamber of Horrors",b="Occupying the southwestern terrace of the subterranean capital, the Apothecarium is a labyrinth of bubbling vats, dissection tables, and pungent chemical fumes. Led by Master Apothecary Faranell, the Royal Apothecary Society utilizes this district to advance their understanding of mortality and rot. Here, alchemists and surgeons experiment on tissue grafts, vivisection, and the assembly of mighty abominations. Their overriding purpose, mandated by Lady Sylvanas Windrunner, is the formulation of a new plague capable of eradicating both the Scourge and the lingering human presence across Lordaeron.",sp=0},{t="Center of Forsaken Alchemy",b="Beyond grand military ambitions, the quarter serves as the premier center of practical alchemy and herbalism for the Horde in the Eastern Kingdoms. Initiates and masters alike gather beside toxic canals to distill concoctions, study botanical blights, and consult master practitioners. The Society also uses these halls to train battlefield medics in the gruesome science of organ transplantation and corpse suturing, ensuring Forsaken shock troops and patchwork constructs remain functional on the front lines.",sp=0}},faq={{q="What is the Apothecarium used for?",a="The Apothecarium serves as the research and manufacturing wing for the Royal Apothecary Society. It is where Forsaken alchemists brew experimental poisons, refine the New Plague, construct abominations, and instruct practitioners in alchemy and herbalism.",al={"apothecarium purpose","what happens here","why does the apothecarium exist"}},{q="Who leads the Apothecarium?",a="The district and its researchers are led by Master Apothecary Faranell, the chief scientist of the Royal Apothecary Society, operating with the full authority and patronage of Queen Sylvanas Windrunner.",al={"apothecarium leader","who runs the apothecarium","faranell undercity"}},{q="What is the Royal Apothecary Society trying to create?",a="Their primary endeavor is cultivating a lethal New Plague engineered to annihilate both the Scourge forces of the Lich King and any living human resistance contesting Forsaken territory in Lordaeron.",al={"forsaken plague research","new plague undercity","what are they brewing"}},{q="Can players learn professions here?",a="Yes. The district is the capital's main hub for alchemists and herbalists, hosting advanced profession trainers along its walkways and chambers.",al={"apothecarium trainers","alchemy in undercity","undercity herbalism trainer"}}},ang={["race:Undead"]="For the Forsaken, the Apothecarium is the forge of their survival, producing the chemical and stitched weapons essential to holding Lordaeron against overwhelming enemies.",["profession:Herbalism"]="Botanists supply the foul distillers of the Royal Apothecary Society with rare, blighted flora gathered from the ruins of the northern kingdoms."},kw={"abominations","alchemy","apothecarium","faranell","new plague","royal apothecary society","sylvanas","undercity"},rel={"topic:royal-apothecary-society","npc:master-apothecary-faranell","zone:undercity","npc:sylvanas-windrunner","quest:447","topic:forsaken","topic:lordaeron","quest:445"},src={"Apothecarium"}}
E["subzone:canals-undercity"] = {t="subzone",n="Canals (Undercity)",z="undercity",s="The Canals form a murky, circular moat winding between the distinct quarters of the Undercity. Filled with an unnatural, noxious green slime rather than fresh water, they serve as both a sewage system and a grim symbol of the Forsaken's subterranean stronghold.",h="The Canals form a murky, circular moat winding between the distinct quarters of the Undercity.",sec={{t="A Toxic Moat",b="Carved into the subterranean depths beneath the ruins of Lordaeron, the Canals encircle the heart of the Undercity, dividing its quarters with wide channels of sluggish green sludge. While mortal cities channel flowing river water to clean their avenues, the Forsaken have filled these stone conduits with industrial refuse, chemical runoff, and alchemical waste. The liquid emits a faint, sickly glow and foul vapors, making it impossible to traverse by ordinary magical means like water walking. Despite the lethality of the slurry, desperate anglers occasionally haul bizarre, tainted curiosities from the muck.",sp=0}},faq={{q="What is the green liquid in the canals?",a="It is an alchemical sludge composed of toxic runoff, plague byproducts, and industrial waste that collects within the Undercity's drainage system. Unlike clean water, it is visibly tainted and noxious.",al={"undercity green water","what is the slime in undercity","green slime river"}},{q="Can you fish in the Undercity canals?",a="Yes, patient anglers can cast a line into the sludge. Along with sickly, contaminated fish, people occasionally haul up discarded junk, including old human skulls from Lordaeron's fallen past.",al={"fishing undercity","can you fish here","fishing in green slime"}},{q="Why doesn't Water Walking work on the canals?",a="The thick, chemical slurry does not behave like natural water. Its foul viscosity and unnatural composition prevent shamans and other spellcasters from holding surface tension through conventional water-walking magic.",al={"water walking undercity","shaman water walking bug","why cant i walk on water undercity"}}},ang={["race:Undead"]="For the Forsaken, the foul canals are entirely harmless to their unliving physiology, serving as a functional moat and chemical runoff channel suited to their subterranean realm.",["class:Shaman"]="The elements hold little sway over the polluted muck filling the Undercity's waterways, causing conventional spells like Water Walking to fail entirely."},kw={"canals","fishing","forsaken","green slime","lordaeron","sludge","toxic","undercity"},rel={"zone:undercity","topic:forsaken","subzone:canals-stormwind-city"},src={"Canals (Undercity)"}}
E["subzone:magic-quarter"] = {t="subzone",n="Magic Quarter",z="undercity",s="The Magic Quarter is the northeastern district of the Undercity, serving as the center for Forsaken arcane study and dark spellcraft. Dominated by an ominous Temple of the Damned, the quarter houses practitioners of both the arcane and fel arts.",h="The Magic Quarter is the northeastern district of the Undercity, serving as the center for Forsaken arcane...",sec={{t="A Conclave of Dark Arts",b="Occupying the northeastern quadrant of the subterranean city, the Magic Quarter is where the Forsaken preserve their arcane heritage and delve into darker methodologies. The centerpiece of the district is a looming Temple of the Damned, an architectural relic of Scourge design that has been repurposed by the free-willed undead. Beneath its vaulted, shadowy ceilings, mages practice subtle manipulations of magical energies alongside warlocks communing with demonic entities, making the quarter the nexus of intellectual power and occult research in Lordaeron.",sp=0},{t="Scholars, Weavers, and Summoners",b="Beyond the study of raw evocation and summoning, the Magic Quarter functions as an essential civic hub for spellcasters. Portal trainers maintain transport links across Horde territories, while master tailors work with magically infused fabrics to craft robes, shrouds, and spellthread. Unlike Dalaran's strict segregation between academic wizardry and forbidden magic, the Forsaken blend arcane curiosity and fel power openly within these halls to secure their place against their many enemies.",sp=0}},faq={{q="What is the purpose of the Magic Quarter?",a="The Magic Quarter serves as the center of arcane and demonic studies for the Forsaken. It houses class trainers for mages and warlocks, portal masters connecting to other cities, and tailoring professionals who weave enchanted cloth.",al={"what is magic quarter","magic quarter purpose","undercity magic district"}},{q="Why is there a Temple of the Damned in the Undercity?",a="When the Undercity was carved out beneath the ruins of Capital City by the Scourge, they erected structures like the Temple of the Damned. When Sylvanas and her free-willed Forsaken seized the subterranean complex, they claimed these existing facilities and repurposed them for their own spellcasters.",al={"temple of the damned undercity","why temple of the damned here","scourge building undercity"}},{q="Who can be trained in the Magic Quarter?",a="Mages, warlocks, and demon trainers instruct practitioners within the quarter, while portal specialists and tailoring artisans offer training in transport and craft.",al={"trainers in magic quarter","who trains here","magic quarter classes"}},{q="Where is the Magic Quarter located?",a="It is situated in the northeastern quadrant of the Undercity, directly across the central ring from the Rogue and Apothecary quarters.",al={"where is magic quarter","magic quarter location","find magic quarter"}}},ang={["class:Mage"]="The Magic Quarter is the heart of Forsaken wizardry, offering training in arcane arts and teleportation networks that link the Undercity with the wider Horde.",["class:Warlock"]="Within the dark alcoves of the Temple of the Damned, warlocks summon demonic minions and hone shadow magic far from the judgmental eyes of the Alliance."},kw={"forsaken","mage","magic quarter","portal trainer","tailoring","temple of the damned","undercity","warlock"},rel={"zone:undercity","topic:forsaken"},src={"Magic Quarter"}}
E["subzone:rogues-quarter"] = {t="subzone",n="Rogues' Quarter",z="undercity",s="The Rogues' Quarter is a dimly lit district in the southeastern wing of the Undercity. It serves as the staging ground for the Forsaken's scouts, assassins, and underworld operatives, along with the craftsmen who support them.",h="The Rogues' Quarter is a dimly lit district in the southeastern wing of the Undercity.",sec={{t="Shadows of the Undercity",b="Tucked away in the southeastern quadrant of the subterranean city, the Rogues' Quarter gathers the Forsaken's most cunning and lethal survivors. In life, many were thieves, cutpurses, or silent blades for the Kingdom of Lordaeron; in death, their expertise in stealth, poisons, and misdirection has been repurposed to protect the fledgling nation from the Scourge and the Scarlet Crusade. The district hums with quiet activity, offering a covert haven where operatives sharpen their daggers, brew deadly toxins, and hone clandestine skills.",sp=0},{t="Tools of the Trade",b="Beyond stealth and assassination, the Rogues' Quarter is home to the specialized trades that enable undercover survival. Artisans gather here to instruct travelers in leatherworking and skinning, turning raw hides into light, silent armor. The clatter of engineering benches echoes through the stone halls as tinkers assemble gadgets, while field medics and apothecaries provide instruction in first aid and vend lethal poisons essential for covert work.",sp=0}},faq={{q="Where is the Rogues' Quarter located?",a="The Rogues' Quarter is situated in the southeastern section of the Undercity's outer ring, past the Trade Quarter.",al={"rogues quarter location","where is rogues quarter","undercity rogues quarter map"}},{q="What trainers can be found here?",a="The quarter houses trainers for rogues, as well as instructors for leatherworking, skinning, engineering, and first aid. Poison vendors are also stationed nearby to supply reagents.",al={"rogues quarter trainers","undercity rogue trainer","who trains in rogues quarter"}},{q="Why do the Forsaken maintain a dedicated district for rogues?",a="Surrounded by hostile forces like the Scourge and the Scarlet Crusade, the Forsaken rely heavily on espionage, assassination, and hit-and-run tactics to defend their territory, making covert operatives vital to their survival.",al={"why do forsaken need rogues","forsaken assassins","undercity rogue lore"}}},ang={["class:Rogue"]="For Forsaken and Horde assassins, this quarter is the premier hub for mastering stealth, learning combat techniques, and stocking up on lethal poison reagents.",["profession:Engineering"]="Tinkers visit the Rogues' Quarter to learn schematics and craft bombs, gadgets, and mechanical tools favored by undercover agents."},kw={"engineering","forsaken","leatherworking","poison vendor","rogue trainer","rogues quarter","rogues' quarter","skinning","undercity"},rel={"zone:undercity","topic:forsaken"},src={"Rogues' Quarter"}}
E["subzone:royal-quarter"] = {t="subzone",n="Royal Quarter",z="undercity",s="The Royal Quarter is the secluded seat of power within the Undercity, serving as the throne room for Lady Sylvanas Windrunner. Here, the Banshee Queen directs the Forsaken alongside her dreadlord enforcer, Varimathras, guarded by an elite cohort of Royal Dreadguards.",h="The Royal Quarter is the secluded seat of power within the Undercity, serving as the throne room for Lady...",sec={{t="The Seat of the Dark Lady",b="Tucked away behind towering archways and shadowed corridors, the Royal Quarter—also known as the Hall of the Dark Lady—is the political and military nerve center of the Forsaken. Sylvanas Windrunner holds court in this cavernous subterranean chamber, plotting the survival of her free-willed undead and the destruction of the Scourge. Heavily armored Royal Dreadguards stand vigil along the dais, ensuring that uninvited guests and would-be assassins never reach their queen.",sp=0},{t="A Dangerous Alliance",b="Standing beside the Dark Lady is the nathrezim Varimathras, an unexpected and uneasy fixture in the heart of the Undercity. After siding with Sylvanas during the civil war in the ruins of Lordaeron to save his own life, the dreadlord pledged loyalty to her cause. From the Royal Quarter, he commands deathstalkers and coordinates defensive operations across the realm. While his tactical cunning serves the Forsaken well, his demonic nature leaves many Horde allies wary of his true allegiances.",sp=0}},faq={{q="Who rules from the Royal Quarter?",a="Lady Sylvanas Windrunner, the Banshee Queen, rules the Forsaken from the throne within the Royal Quarter. She is flanked by the nathrezim Varimathras, who pledged allegiance to her after the liberation of Lordaeron.",al={"who is in the royal quarter","undercity throne room leader","who leads undercity"}},{q="Why is there a dreadlord standing in the throne room?",a="Varimathras surrendered to Sylvanas Windrunner during the reconquest of Capital City after betraying his brothers Detheroc and Balnazzar. He spared his own life by swearing loyalty to Sylvanas, and now acts as her enforcer and master of scouts.",al={"why is varimathras here","dreadlord in undercity","why is demon in royal quarter"}},{q="What are the Royal Dreadguards?",a="The Royal Dreadguards are elite Forsaken protectors chosen specifically to guard Lady Sylvanas and the Royal Quarter. They are among the most disciplined and lethal defenders in the Undercity.",al={"dreadguards","undercity throne room guards","royal quarter guards"}},{q="What other function does this chamber serve?",a="Beyond serving as the primary audience chamber for the Dark Lady and Varimathras, the Royal Quarter houses battlemasters who coordinate Horde combatants for foreign campaigns and strategic skirmishes across Azeroth.",al={"what else is in royal quarter","royal quarter purpose","battlemasters royal quarter"}}},ang={["race:Undead"]="The Royal Quarter represents the heart of Forsaken independence, where Sylvanas Windrunner and her dreadlord lieutenant chart the future of their liberated people.",["faction:Horde"]="Visiting Horde envoys to the Royal Quarter often view the Dark Lady's nathrezim councilor with intense suspicion, questioning the wisdom of trusting a demon in the heart of a Horde capital."},kw={"banshee queen","hall of the dark lady","royal dreadguard","royal quarter","sylvanas windrunner","throne room","undercity","varimathras"},rel={"zone:undercity","npc:sylvanas-windrunner","npc:varimathras","quest:1886","topic:horde","topic:burning-legion"},src={"Royal Quarter"}}
E["subzone:ruins-of-lordaeron"] = {t="subzone",n="Ruins of Lordaeron",z="undercity",s="The Ruins of Lordaeron are the hollowed-out surface remnants of Capital City, the once-glorious heart of humanity's northern empire. Destroyed when Prince Arthas murdered his father and unleashed the Scourge, the blasted courtyards and throne room now serve as the fortified gateway to the Undercity below.",h="The Ruins of Lordaeron are the hollowed-out surface remnants of Capital City, the once-glorious heart of...",sec={{t="A Fallen Empire's Gateway",b="Capital City was once the radiant summit of human civilization, uniting the northern realms under King Terenas Menethil II. When Prince Arthas returned from Northrend carrying the cursed runeblade Frostmourne, the celebrations turned into a slaughterhouse. Arthas slew his father on the throne, leaving the metropolis to rot under Scourge rule. Following the civil war that tore the Scourge apart, Lady Sylvanas Windrunner claimed the devastated palace, securing the surface while expanding the crypts and dungeons beneath into the Undercity.",sp=0},{t="Echoes of Betrayal",b="The palace ruins remain psychically scarred by their violent fall. Travelers walking through the entryway and courtyards often hear the ghostly chime of celebration bells, hushed murmurs of adoring crowds, and the chilling dialogue between Arthas and his father just before the regicide. Blood still stains the floor of the grand throne room, and those possessing magical detection can glimpse spectral citizens eternally reliving the afternoon their prince doomed them all.",sp=0}},faq={{q="Why do I hear bells and whispers when walking through the entrance?",a="The sudden slaughter of King Terenas and his city left a psychic imprint on the stone. Anyone passing through the outer gate and the shattered throne room can hear phantom bells, spectral cheers, and the final conversation between Terenas and Arthas echoed across time.",al={"creepy sounds lordaeron","throne room whispers","haunted castle sounds"}},{q="Who rules the ruins today?",a="The surface ruins are held and patrolled by the Forsaken under Lady Sylvanas Windrunner. While Sylvanas and her court reside directly below in the Undercity, the ruins above serve as the grand fortified entrance to her subterranean realm.",al={"who owns lordaeron ruins","who controls ruins of lordaeron"}},{q="What happened to the people who used to live here?",a="Most of the inhabitants were slaughtered when Arthas unleashed the Scourge upon the city. Many were raised into mindless undead and later broke free to join Sylvanas as the Forsaken, while the unseen spirits of others still drift through the palace courtyards.",al={"where did lordaeron people go","what happened to capital city humans"}},{q="What is the dark stain in the throne room?",a="The dark, dried residue marking the royal dais is the blood of King Terenas Menethil II, spilled by his own son Arthas when the prince drove Frostmourne through his heart.",al={"blood on throne room floor","stain in lordaeron throne room"}}},ang={["race:Undead"]="These ruined ramparts are your ancestral home. What was once the seat of the living kingdom that birthed you is now the hallowed doorway guarding the Undercity and the Banshee Queen.",["race:Human"]="Standing within these halls is a bitter reminder of the greatest betrayal in human history, where Prince Arthas shattered the Alliance of Lordaeron and left humanity's jewel in the hands of the dead."},kw={"arthas","capital city","haunted","lordaeron","palace","scourge","sylvanas","terenas","throne room","undercity"},rel={"zone:undercity","topic:lordaeron","topic:arthas-menethil","topic:forsaken","npc:sylvanas-windrunner","topic:scourge","topic:alliance","topic:knights-of-the-silver-hand"},src={"Ruins of Lordaeron"}}
E["subzone:sewers"] = {t="subzone",n="Sewers",z="undercity",s="The Sewers are a sprawling subterranean drainage network that provides a secondary, unguarded entrance directly into the Undercity. Cutting beneath the hills west of the ruined palace of Lordaeron, this conduit allows bat handlers and stealthy travelers to bypass the precarious elevators leading down from the throne room.",h="The Sewers are a sprawling subterranean drainage network that provides a secondary, unguarded entrance...",sec={{t="A Backdoor into the Catacombs",b="Before the plague wiped out Lordaeron, these stone culverts served as the mundane sewer lines draining the royal capital. In the hands of Sylvanas Windrunner's Forsaken, however, the runoff tunnels have been integrated into the Undercity's outer defenses. Emerging west of the surface ruins near a contested Scarlet Watchtower in Tirisfal Glades, the passage provides a level, direct slope inside. Forsaken bat handlers use this cavernous conduit to fly riders swiftly into the subterranean rings, avoiding the sluggish cage lifts entirely. Because it circumvents the heavily fortified surface courtyards, it remains a dangerous vulnerability that hostile infiltrators constantly seek to exploit.",sp=0}},faq={{q="Where does the sewer tunnel lead outside?",a="The conduit empties onto the rolling hills of Tirisfal Glades, just west of the main gates of the Ruins of Lordaeron. It is situated not far from the Scarlet Watchtower overlooking the lake.",al={"undercity sewer exit","where do sewers go","sewer back entrance"}},{q="Why would anyone use the sewers instead of the main entrance?",a="The primary way into the Undercity requires riding iron cage elevators down from the palace ruins, which can be slow and dangerous during an attack. The sewer is a direct, ramped route that handles the Forsaken bat transit and permits quick egress without waiting on lifts.",al={"why use sewers","sewers vs elevators","undercity backdoor"}},{q="Is the sewer safe from Alliance raiders?",a="Hardly. Because it bypasses the fortified gatehouse and throne room of Lordaeron, the sewer is the preferred breach point for daring Alliance scouts and strike teams attempting to sneak directly into the Forsaken capital.",al={"alliance attack sewers","is sewer guarded","undercity sewer defense"}}},ang={["race:Undead"]="For the Forsaken, the sewers are an essential lifeline and flight corridor that keeps the Undercity connected to the rest of Lordaeron without bottling up traffic in the courtyard elevators.",["faction:Alliance"]="Anyone foolish or brave enough to assault the Forsaken capital knows the sewers provide the only covert path past the heavily defended surface ruins."},kw={"backdoor","bat handler","drainage","flight path","lordaeron","sewers","tirisfal glades","undercity"},rel={"zone:undercity","zone:ruinsoflordaeron","zone:tirisfal","subzone:scarlet-watchtower","topic:lordaeron","topic:alliance"},src={"Sewers"}}
E["subzone:trade-quarter"] = {t="subzone",n="Trade Quarter",z="undercity",s="The Trade Quarter forms the central core of the Undercity, resting directly beneath the lifts from the Ruins of Lordaeron. It functions as the beating economic heart of the Forsaken, housing their primary bank vaults, auction market, and essential civic services. From this concentric hub, vaulted corridors branch outward into the surrounding districts.",h="The Trade Quarter forms the central core of the Undercity, resting directly beneath the lifts from the Ruins...",sec={{t="Heart of the Crypts",b="Descending from the shattered surface of Lordaeron, travelers step off the lifts into the echoing stone expanse of the Trade Quarter. Designed around a tiered, circular layout, its central platform holds the city coffers and central bank, framed by bridges spanning noxious runoff canals. Surrounding terraces buzz with vendors, guild registries, and auctioneers bargaining amidst the eerie gloom. Even basic accommodations reflect Forsaken pragmatism: the local inn offers unlined wooden caskets rather than soft beds. From this central nexus, stone archways lead outward into the city's specialized quarters, making it the unavoidable crossroads for any business conducted within the capital.",sp=0}},faq={{q="Where is the Trade Quarter located?",a="The Trade Quarter occupies the dead center of the Undercity. When entering the capital via the surface elevators beneath the Ruins of Lordaeron, you step out immediately onto the upper ring of the district.",al={"trade quarter location","how to find trade quarter","where is trade quarter"}},{q="What services are found in the Trade Quarter?",a="The district hosts the central Undercity bank, an auction house along the outer ring, the primary inn, a bat handler for air travel, guild registrars, and various trade trainers including the city's cooking mentor.",al={"trade quarter services","what is in trade quarter","undercity bank location"}},{q="Why are there coffins in the inn?",a="Forsaken physiology requires no true sleep, and many retain habits suited to their undead condition. The inn provides plain, unlined wooden caskets rather than traditional bedding—a matter of routine comfort for the dead, though deeply unsettling for living visitors.",al={"undercity inn coffins","why caskets in inn","undercity beds"}},{q="Who is the vendor lurking beneath the bridges?",a="Jeremiah Payson makes his living under one of the central bridges crossing into the bank. While standard merchants peddle weaponry and trade goods up above, Payson sells live pet cockroaches to curious passersby.",al={"jeremiah payson","cockroach guy undercity","who sells cockroaches"}}},ang={["race:Undead"]="The Trade Quarter represents the swift reclamation of civilized order by the Forsaken, turning subterranean dungeons into a thriving market dedicated to funding their survival.",["faction:Horde"]="For Orc, Tauren, or Troll emissaries arriving in Tirisfal Glades, the Trade Quarter serves as the foreign, shadowy market center of their northern allies."},kw={"auction house","bank","bat handler","caskets","inn","jeremiah payson","trade quarter","undercity"},rel={"zone:undercity","zone:ruinsoflordaeron","topic:lordaeron","topic:horde"},src={"Trade Quarter"}}
E["subzone:war-quarter"] = {t="subzone",n="War Quarter",z="undercity",s="The War Quarter is the northwestern district of the Undercity, serving as the command post and martial training ground for the Forsaken. Within its echoing stone chambers, the soldiers, priests, and crafters of Lordaeron hone their weapons and shadow magic in defense of their fledgling kingdom. It houses training halls for warriors and priests alongside weapon masters and heavy industry.",h="The War Quarter is the northwestern district of the Undercity, serving as the command post and martial...",sec={{t="The Forsaken Garrison",b="Occupying the northwest sector of the subterranean metropolis, the War Quarter stands as the bastion of martial strength for the Forsaken. Beneath its gloomy stone arches, rank-and-file guards and elite champions assemble to drill in armed combat. Unlike traditional barracks of living kingdoms, this military center combines ruthless iron warfare with the chilling rites of shadow, housing an ominous Altar of Darkness where spiritual discipline merges with military ambition.",sp=0},{t="Forge and Steel",b="Beyond housing warrior and priest guilds, the quarter functions as the heart of Undercity's wartime production. The clatter of blades and armor echoes continually against the stone, supported by the district's blacksmiths, smelters, and weapon masters. Here, iron forged deep in the earth is shaped to outfit the forces defending the ruins of Lordaeron from the Scourge and Scarlet Crusade.",sp=0}},faq={{q="What is the purpose of the War Quarter?",a="The War Quarter serves as the military headquarters of the Undercity. It hosts martial training grounds for warriors, priests, and hunters, along with vital crafting centers for blacksmithing and mining to keep the Forsaken army armed and armored.",al={"what is war quarter","war quarter purpose","why visit war quarter"}},{q="Why are priests located in the War Quarter?",a="Forsaken priests largely focus on the discipline of the Shadow, using it as a potent weapon alongside their warriors rather than maintaining pastoral sanctuaries. Their presence near the martial forces and the Altar of Darkness reflects how deeply intertwined faith and warfare are in the defense of the Forsaken.",al={"undead priest location","why are priests in war quarter","priest trainers undercity"}},{q="What is the Altar of Darkness?",a="The Altar of Darkness is a focal point of dark spiritual power located within the War Quarter. It is tied to the Forsaken's dark rites and training, anchoring the shadowy magic wielded by their priests and champions.",al={"altar of darkness undercity","altar in war quarter"}},{q="Where is the War Quarter located in the Undercity?",a="The War Quarter occupies the northwest quadrant of the Undercity's circular layout, situated between the Rogues' Quarter to the west and the Trade Quarter towards the center.",al={"where is war quarter","war quarter location","war quarter directions"}}},ang={["class:Warrior"]="The War Quarter is your primary haven in the Undercity, offering weapon masters, advanced combat instructors, and heavy armories to prepare you for the brutal frontline battles of Lordaeron.",["profession:Blacksmithing"]="Housing both training masters and high-heat anvils, the War Quarter is the central hub for smiths hammering out munitions and plate for the Forsaken war effort."},kw={"altar of darkness","barracks","blacksmithing","forsaken","priest trainer","undercity","war quarter","warrior trainer"},rel={"zone:undercity","topic:forsaken"},src={"War Quarter"}}
E["zone:undercity"] = {t="city",n="Undercity",z="undercity",s="Deep beneath the shattered ruins of Lordaeron's Capital City lies the Undercity, the dark stronghold of the Forsaken. Originally carved out of ancient royal crypts and dungeons by the Scourge, it was seized by Lady Sylvanas Windrunner and remade into an impenetrable subterranean sanctuary. Today it serves as the seat of Forsaken power and the Horde's vital bastion in the northern Eastern Kingdoms.",h="Deep beneath the shattered ruins of Lordaeron's Capital City lies the Undercity, the dark stronghold of the...",sec={{t="From Royal Crypts to Scourge Redoubt",b="Long before the plague swept Lordaeron, the catacombs, dungeons, and sewers beneath the palace were collectively known as the Undercity. It held the tombs of nobility, the kingdom's deepest prisons—where the former Warchief Orgrim Doomhammer was once held before his escape—and the poorest denizens of the realm. When Arthas Menethil murdered King Terenas and laid waste to the capital in 20 ADP, the prince ordered his undead servants to excavate and expand the subterranean passages into a fortified seat of Scourge rule.",sp=0},{t="Rise of the Forsaken",b="The Scourge never saw their dark capital completed. When the Lich King's powers waned following the battle of Mount Hyjal, Lady Sylvanas Windrunner broke free from the hive mind, taking thousands of undead with her. She lured Arthas into an ambush and drove him back to Northrend. After a vicious three-way civil war against Scourge remnants, dreadlords, and human resistance, Sylvanas claimed the half-finished catacombs. Naming her people the Forsaken, she oversaw years of labor completing the sprawling subterranean city.",sp=0},{t="Architecture of the Damned",b="The Undercity is laid out in concentric rings divided into functional quarters. At its heart lies the Trade Quarter, connected by great lifts to the palace ruins above. Surrounding it are the War Quarter, Rogues' Quarter, Magic Quarter, and the toxic Apothecarium, where the Royal Apothecary Society brews virulent plagues in green slime-filled canals. Deeper still lies the Royal Quarter, where the Banshee Queen holds court alongside her dreadlord commander, Varimathras, guarded by legions of towering abominations.",sp=0}},faq={{q="What was the Undercity before the undead took it over?",a="Beneath the palace of Lordaeron lay the ancient crypts of human royalty, along with the city's dungeon complex and vast sewer network. It housed prisoners of war, including Orgrim Doomhammer, as well as destitute citizens living in the subterranean shadows. After sacking the capital, Prince Arthas began turning these catacombs into a Scourge fortress before Sylvanas captured them.",al={"undercity origins","what was undercity originally","lordaeron sewers history"}},{q="Why is the city built underground instead of on the surface?",a="The surface city of Lordaeron was utterly ruined during the Third War, making it difficult to defend against the Scarlet Crusade, Scourge forces, and Alliance survivors. The subterranean tunnels offered natural fortification, choke points, and secrecy, allowing the Forsaken to complete the Scourge's initial construction and thrive unseen.",al={"why live underground","why not rebuild lordaeron","why undercity beneath ruins"}},{q="Who rules the Undercity?",a="The city is ruled by Lady Sylvanas Windrunner, the Banshee Queen and Queen of the Forsaken. She governs from the Royal Quarter, guarded by Forsaken royal sentries and her subjugated dreadlord lieutenant, Varimathras.",al={"who is leader of undercity","undercity ruler","who runs undercity"}},{q="What is King Terenas's memorial in the ruins above?",a="Above the city's main lifts sits a stone memorial for the slain King Terenas Menethil II. It does not contain his body, as his corpse was cremated and his ashes discarded during Kel'Thuzad's resurrection. Surviving Alliance humans bravely carved the monument amidst the ruins so the memory of Lordaeron's last true king would endure.",al={"king terenas tomb","lordaeron throne room grave","who built the tomb above undercity"}},{q="What are the strange noises in the Lordaeron throne room?",a="In the ruined throne room above the Undercity lifts, spectral echoes of the past still linger. Visitors standing in the center can hear faint phantom sounds: the celebratory bells and rose petals of Arthas's return, the warning words of the prophet Medivh, and the final conversation between King Terenas and his patricidal son.",al={"ghost sounds throne room","throne room whispering","voices in lordaeron throne room"}},{q="Why do the Forsaken allow other Horde members here?",a="The Forsaken formed an alliance of convenience with Warchief Thrall's Horde for survival, surrounded as they are by hostile Scarlet zealots and Scourge legions. While living Horde races find the toxic fumes and alchemical rivers stifling, emissaries and travelers are allowed access to foster diplomatic and military ties.",al={"why are orcs in undercity","horde in undercity","why is undercity part of horde"}}},ang={["race:Undead"]="The Undercity is your sovereign sanctuary and homeland, carved out by your own hands after breaking the Lich King's iron grip on your mind.",["faction:Horde"]="As the Horde's primary foothold in the Eastern Kingdoms, the Undercity secures zeppelin links directly back to Durotar and Grom'gol Base Camp.",["race:Human"]="Beneath the soil of your fallen ancestral kingdom lies a grim perversion of Lordaeron's royal crypts, occupied by the walking corpses of your former brethren.",["race:Orc"]="Deep within these very dungeons, the legendary Warchief Orgrim Doomhammer was once imprisoned by the Alliance of Lordaeron before making his historic escape."},kw={"apothecarium","arthas","forsaken","lordaeron","scourge","sylvanas","terenas","tirisfal","undercity","varimathras"},rel={"npc:sylvanas-windrunner","topic:forsaken","zone:tirisfal","zone:ruinsoflordaeron","topic:lordaeron","topic:scourge","topic:arthas-menethil","subzone:apothecarium"},src={"Undercity"}}
